  if(!sections.some(x=>x[0]===setNav))setNav=sections[0][0];
  const AU=window.MA_AUTH,ses=AU&&AU.session,nm=(S.profile&&S.profile.name)||"",em=ses&&ses.user?ses.user.email:"",pro=typeof isPro==="function"&&isPro();
