  $("#rstBtn").onclick=()=>confirmIn("#rstBox","Yes, reset",()=>{Object.assign(S,{best:{},rapid:0,daily:{},newsq:{},mock:0,mockXP:0,mockBest:{},xpLog:{}});save();render();renderMock();renderSettings(true);toast("Progress reset")});
