const addDaysKey=(n)=>{const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString("en-CA")};
const daysUntil=k=>Math.round((new Date(k+"T12:00:00")-new Date(today()+"T12:00:00"))/864e5);

/* ---------- 1. onboarding + plan ---------- */
const PLAN_ORDER={"Investment banking":["f","b","ib","x","pm"],"Private equity":["f","ib","pe","x","b"],"Hedge funds & markets":["f","pm","b","x"],"Restructuring":["f","rx","ib","b"],"Consulting":["f","mc","b","x"],"Equity research":["f","pm","ib","b","x"],"Not sure yet":["f","b","ib","pm"]};
function onboarding(force){if(!force&&(S.plan||S.onboardSkip))return;const p=S.plan||{};let step=-1;
  const a={year:p.year||"",target:p.target||"",weeks:p.weeks||"",know:p.know||"",mins:p.mins||"",school:p.school||S.profile.school||""};
  const Q=[["year","What year are you in?",["High school","Freshman","Sophomore","Junior","Senior","Grad / other"],"So we start you at the right level."],
    ["target","What do you want to break into?",Object.keys(PLAN_ORDER),"Not sure is totally fine. We'll show you a bit of everything."],
    ["weeks","When does recruiting start for you?",["Already recruiting","Within 3 months","3–6 months","6–12 months","1+ year away","Not sure"],"We'll pace your plan so you're ready in time."],
    ["know","How much finance do you know?",["Brand new","I know the basics","Ready for interviews"],"Be honest. You can skip ahead anytime."],
    ["mins","How much time can you give it a day?",["10 minutes","20 minutes","45 minutes"],"Small and steady wins. You can change this later."],
    ["school","What school do you go to?",null,"Optional. Puts you on your school's team on the leaderboard."]];
  const WEEKS={"Already recruiting":3,"Within 3 months":10,"3–6 months":20,"6–12 months":40,"1+ year away":60,"Not sure":26};
  let tested=false,placedN=0,score=null;
  const next=()=>{if(step<Q.length-1){if(Q[step+1][0]==="school"&&!tested){tested=true;if(a.know!=="Brand new"){placement(()=>{step++;draw()});return}}step++;draw()}else finish()};
  /* placement test: 8 real questions from their path, weighted by year; correct answers in a row test them out of early levels */
  const placement=done=>{const PATH={"Investment banking":"ib","Private equity":"pe","Hedge funds & markets":"pm","Restructuring":"rx","Consulting":"mc","Equity research":"pm","Not sure yet":"ib"};
    const path=PATH[a.target]||"ib",early=["High school","Freshman"].includes(a.year),mid=a.year==="Sophomore";
    const plan=[["f",early?5:mid?4:3],[path,early?3:mid?4:5]],items=[];
    plan.forEach(([t,n])=>{const L=T(t).levels;n=Math.min(n,L.length);const idx=[...new Set(Array.from({length:n},(_,i)=>n<2?0:Math.round(i*(L.length-1)/(n-1))))];
      idx.forEach(l=>{const qs=L[l].q||[];if(qs.length)items.push({t,l,q:qs[Math.floor(Math.random()*qs.length)]})})});
    const intro=()=>{openPanel(`<div class="ob"><div class="label">Quick check · optional</div><h2>Test out of what you already know</h2>
      <p class="sub">${items.length} real interview questions from ${esc(T("f").name)} and ${esc(T(path).name)}, picked for your year. About 2 minutes. Get them right and we'll skip those levels in your plan.</p>
      <div class="actions"><button class="btn" id="ptGo">Start the test →</button><button class="ghost" id="ptSkip">Skip, start from the beginning</button></div></div>`);
      $("#ptGo").onclick=()=>ask(0,[]);$("#ptSkip").onclick=done;$("#ptGo").focus()};
    const ask=(i,ans)=>{if(i>=items.length)return result(ans);const it=items[i];
      openPanel(`<div class="ob"><div class="ob-dots">${items.map((_,j)=>`<i class="${j<=i?'on':''}"></i>`).join("")}</div><div class="label">Question ${i+1} of ${items.length} · ${esc(T(it.t).name)}</div><h2 style="font-size:20px;line-height:1.35">${esc(it.q[0])}</h2>
        <div class="ob-opts" style="grid-template-columns:1fr">${it.q[1].map((o,j)=>`<button class="ob-o" data-j="${j}">${esc(o)}</button>`).join("")}</div>
        <div class="actions"><button class="ghost" id="ptIdk">I don't know</button></div></div>`);
      panel.querySelectorAll(".ob-o").forEach(b=>b.onclick=()=>ask(i+1,ans.concat(+b.dataset.j===it.q[2])));$("#ptIdk").onclick=()=>ask(i+1,ans.concat(false));panel.querySelector(".ob-o").focus()};
    const result=ans=>{S.placed=S.placed||{};placedN=0;
      plan.forEach(([t])=>{let streak=true;items.forEach((it,k)=>{if(it.t!==t)return;if(!ans[k])streak=false;if(streak){const L=T(t).levels;const nextIdx=(items.filter(x=>x.t===t).find(x=>x.l>it.l)||{l:L.length}).l;for(let l=0;l<nextIdx&&l<=it.l;l++){if(!cleared(t,l)){S.placed[lid(t,l)]=1;placedN++}}}})});
      const right=ans.filter(Boolean).length;score=[right,items.length];save();
      const msg=right===items.length?"Wow, you know your stuff. We'll start you further along.":right>=items.length*.6?"Solid base. We'll skip what you already know.":right>0?"Good start. Your plan covers the gaps.":"No worries, that's what this is for. Your plan starts at the beginning.";
      openPanel(`<div class="ob"><div class="label">Your result</div><h2>${right} of ${items.length} right</h2><p class="sub">${msg}${placedN?` You tested out of <b>${placedN} level${placedN>1?"s":""}</b>.`:""}</p>
        <div class="actions"><button class="btn" id="ptNext">Continue →</button></div></div>`);$("#ptNext").onclick=done;$("#ptNext").focus()};
    intro()};
  const draw=()=>{
    if(step<0){openPanel(`<div class="ob"><div class="label">Welcome to M&amp;A Prep</div><h2>Let's build your plan 👋</h2>
      <p class="sub">6 quick questions about where you are and where you want to go. Then you'll get a step-by-step plan, paced to your recruiting timeline. Takes about 30 seconds.</p>
      <div class="actions"><button class="btn" id="obStart">Let's go →</button><button class="ghost" id="obSkip">Skip, I'll look around</button></div></div>`);
      $("#obStart").onclick=next;$("#obSkip").onclick=()=>{S.onboardSkip=true;save();closePanel()};$("#obStart").focus();return}
    const [k,t,opts,hint]=Q[step];
    const body=opts?`<div class="ob-opts">${opts.map(o=>`<button class="ob-o" data-v="${esc(o)}" aria-pressed="${a[k]===o}">${esc(o)}</button>`).join("")}</div>`
      :`<form id="obForm" class="ob-in"><input id="obText" type="text" maxlength="60" autocomplete="organization" placeholder="e.g. Ohio State" value="${esc(a[k])}"><button class="btn" type="submit">Continue →</button></form>`;
    openPanel(`<div class="ob"><div class="ob-dots">${Q.map((_,i)=>`<i class="${i<=step?'on':''}"></i>`).join("")}</div><div class="label">Step ${step+1} of ${Q.length}</div><h2>${t}</h2><p class="sub" style="margin-top:-4px">${hint}</p>
      ${body}<div class="actions"><button class="ghost" id="obBack">Back</button>${opts?"":'<button class="ghost" id="obNext">Skip</button>'}</div></div>`);
    panel.querySelectorAll(".ob-o").forEach(b=>b.onclick=()=>{a[k]=b.dataset.v;next()});
    $("#obBack").onclick=()=>{step--;draw()};
    if($("#obForm"))$("#obForm").onsubmit=e=>{e.preventDefault();a[k]=$("#obText").value.trim();next()};
    if($("#obNext"))$("#obNext").onclick=()=>{a[k]="";next()};
    (panel.querySelector(".ob-o")||$("#obText")).focus()};
  const finish=()=>{let order=(PLAN_ORDER[a.target]||PLAN_ORDER["Not sure yet"]).slice();
    if(a.know==="Ready for interviews"&&order.length>2)order=order.filter(t=>t!=="f");
    const rem=t=>T(t).levels.filter((_,i)=>!cleared(t,i)).length;order=order.filter(t=>rem(t)>0);if(!order.length)order=(PLAN_ORDER[a.target]||PLAN_ORDER["Not sure yet"]).slice();
    const total=Math.max(1,order.reduce((n,t)=>n+rem(t),0)),wk=WEEKS[a.weeks]||26;
    /* realistic pace: levels per week follow the time they said they have, never inflated to "fit" a deadline */
    const per={"10 minutes":3,"20 minutes":5,"45 minutes":10}[a.mins]||5,weeksToFinish=Math.ceil(total/per),known=a.weeks&&a.weeks!=="Not sure",onTime=weeksToFinish<=wk;
    let focus=order.length;if(known&&!onTime){let n=0;focus=0;for(const t of order){if(focus>0&&n+rem(t)>wk*per)break;n+=rem(t);focus++}}
    const focusLv=order.slice(0,focus).reduce((n,t)=>n+rem(t),0);
    S.plan={...a,order,focus,perWeek:per,created:today()};
    if(S.settings.goal===undefined)S.settings.goal={"10 minutes":20,"20 minutes":50,"45 minutes":100}[a.mins]||50;
    if(!S.profile.target&&a.target!=="Not sure yet")S.profile.target=a.target.replace("Hedge funds & markets","Hedge funds");
    if(a.school&&!S.profile.school)S.profile.school=a.school;if(a.year)S.profile.year=a.year;save();render();
    const nx=nextPlanLevel();
    panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="ob"><div class="label">Your plan is ready</div><h2>${esc(a.target)} · ${per} levels a week</h2>
      <p class="sub">${!known?`At ${per} levels a week, the full plan takes about <b>${weeksToFinish} weeks</b>. No rush: steady beats cramming.`
        :onTime?`At ${per} levels a week, you'll finish in about <b>${weeksToFinish} weeks</b>, before recruiting starts. 👍`
        :`The full plan takes about <b>${weeksToFinish} weeks</b> at your pace, and recruiting is closer than that. So your first <b>${focus} track${focus>1?"s":""}</b> (${focusLv} levels) are the ones interviews test most. Do those first; the rest can come after.`} Your daily XP goal is ${S.settings.goal}.${score?` Placement test: ${score[0]}/${score[1]}${placedN?`, ${placedN} level${placedN>1?"s":""} skipped`:""}.`:""}</p>
      <ol class="ob-plan">${order.map((t,i)=>`<li${i>=focus?' style="opacity:.55"':""}><b>${T(t).name}</b><span>${rem(t)} level${rem(t)===1?"":"s"}${rem(t)<T(t).levels.length?" left":""}${i===focus-1&&focus<order.length?" · before recruiting":""}${i>=focus?" · after":""}</span></li>`).join("")}</ol>
      <div class="actions">${nx?`<button class="btn" id="obGo">Start: ${esc(nx.tr.levels[nx.i].n)} →</button>`:""}<button class="ghost" id="obDone">Go to Home</button>${S.profile.headline?"":`<button class="ghost" id="obProf">Set up your profile (1 min)</button>`}</div></div>`;bindClose();
    if($("#obProf"))$("#obProf").onclick=()=>editProfile();
    if($("#obGo"))$("#obGo").onclick=()=>{closePanel();showBrief(nx.tr,nx.i)};$("#obDone").onclick=()=>{closePanel();showTab("home")};(($("#obGo")||$("#obDone"))).focus()};
  draw()}
function nextPlanLevel(){const order=(S.plan&&Array.isArray(S.plan.order)&&S.plan.order)||(S.plan&&PLAN_ORDER[S.plan.target])||ORDER;for(const t of order){const tr=T(t);if(!trackUnlocked(tr))continue;for(let i=0;i<tr.levels.length;i++)if(!cleared(t,i))return{tr,i}}return nextLevel()}
function weekStart(){const d=new Date();const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toLocaleDateString("en-CA")}
function renderPlan(){const el=$("#planCard");if(!el)return;if(!S.plan){el.innerHTML=`<button class="ghost gopro" id="planMake" style="margin-top:14px">Set a weekly study goal →</button>`;$("#planMake").onclick=()=>onboarding(true);return}
  const ws=weekStart(),done=Object.values(S.clearDates||{}).filter(d=>d>=ws).length,goal=S.plan.perWeek;
  el.innerHTML=`<div class="plan-card"><div class="pc-top"><span class="label">Your plan · ${esc(S.plan.target)}</span><button class="flink" id="planEdit">Edit</button></div>
    <div class="pc-week"><b>${Math.min(done,goal)}/${goal}</b> levels this week<span class="gbar"><i style="width:${Math.min(100,done/goal*100)}%"></i></span></div>
    <div class="pc-tracks">${S.plan.order.map(t=>{const tr=T(t),c=clearedCount(t);return `<button class="pc-t ${c===tr.levels.length?'done':''}" data-act="track|${t}">${tr.name}<small>${c}/${tr.levels.length}</small></button>`}).join("")}</div></div>`;
  $("#planEdit").onclick=()=>onboarding(true);bindRel(el)}

/* ---------- 3. mistake review ---------- */
const BOX_DAYS=[1,3,7,14];
function logAnswer(raw,ok){const hr=new Date().getHours();if(hr<4&&!A().night){A().night=1;save()}if(hr>=5&&hr<7&&!A().early){A().early=1;save()}if(!raw||!raw[0])return;S.review=S.review||{};const k=raw[0];if(!ok){S.review[k]={q:raw,box:0,due:addDaysKey(1)};save()}}
const dueReviews=()=>Object.values(S.review||{}).filter(r=>r.due<=today());
function renderReview(){const el=$("#reviewCard");if(!el)return;const all=Object.keys(S.review||{}).length,due=dueReviews().length;
  el.innerHTML=`<div class="rv"><div><div class="label">Review queue</div><b>${due?`${due} question${due===1?"":"s"} due today`:all?"All caught up":"Nothing to review yet"}</b><span>${all?`Questions you missed come back after 1, 3, 7 and 14 days until they stick. ${all} in your queue.`:"Questions you miss anywhere on the site land here so you can retry them later."}</span></div>${due?`<button class="btn sm" id="rvGo">Review now</button>`:""}</div>`;
  if(due)$("#rvGo").onclick=runReview}
function runReview(){const items=dueReviews().slice(0,15);if(!items.length)return;
  quiz({title:"Review",qs:items.map(r=>r.q),noLog:true,onAnswer:(i,ok)=>{const r=S.review[items[i].q[0]];if(!r)return;if(ok){questEvt("review");A().reviewOk=(A().reviewOk||0)+1;r.box++;if(r.box>=BOX_DAYS.length)delete S.review[items[i].q[0]];else r.due=addDaysKey(BOX_DAYS[r.box])}else{r.box=0;r.due=addDaysKey(1)}save()},
    finish:c=>{render();return `<h2>${c} of ${items.length} remembered</h2><p>${c===items.length?"Clean sweep.":"Missed ones come back tomorrow."} ${dueReviews().length?dueReviews().length+" still due.":""}</p>`}})}

/* ---------- 2. clubs ---------- */
const randCode=n=>Array.from({length:n},()=>"abcdefghjkmnpqrstuvwxyz23456789"[rint(31)]).join("");
function clubMembers(){const c=S.club&&S.club.code;if(!c)return[];const list=PLAYERS.filter(p=>p.club===c);if(myId&&!list.find(p=>p.id===myId))list.push({id:myId,...myStats()});return list}
function renderClub(){const el=$("#clubCard");if(!el)return;
  if(!S.club||!S.club.code){el.innerHTML=`<div class="label">Clubs</div><h3>Compete with your club</h3><p class="note">A private leaderboard, the weekly Gauntlet as a club, and an officer view of everyone's progress.</p>
     <div class="club-forms"><div><input id="clubName" maxlength="40" placeholder="Club name" aria-label="Club name"><button class="btn sm" id="clubCreate">Create club</button></div><div><input id="clubCode" maxlength="8" placeholder="Join code" aria-label="Club code"><button class="ghost outline" id="clubJoin">Join</button></div></div>`;
    $("#clubCreate").onclick=()=>{const n=$("#clubName").value.trim();if(!n){$("#clubName").focus();toast("Name your club first");return}S.club={code:randCode(6),name:n,officer:true};save();syncProfile();renderClub();toast("Club created. Share the code with members.")};
    $("#clubJoin").onclick=()=>{const c=$("#clubCode").value.trim().toLowerCase();if(!/^[a-z0-9]{4,8}$/.test(c)){toast("Enter the code your club officer shared");return}const off=PLAYERS.find(p=>p.club===c&&p.clubOfficer);S.club={code:c,name:off?off.clubName:"",officer:false};save();syncProfile();renderClub();toast(off?`Joined ${off.clubName}`:"Joined. The club name appears once your officer is online.")};return}
  const mem=clubMembers(),name=S.club.name||(PLAYERS.find(p=>p.club===S.club.code&&p.clubOfficer)||{}).clubName||"Your club";
  if(!S.club.name&&name!=="Your club"){S.club.name=name;save()}
  const top=mem.slice().sort((a,b)=>(b.xp||0)-(a.xp||0)).slice(0,5),gw=mem.filter(p=>p.gWeek===isoWeek()).sort((a,b)=>b.gScore-a.gScore);
  el.innerHTML=`<div class="label">Your club${S.club.officer?" · Officer":""}</div><h3>${esc(name)}</h3>
    <div class="club-meta"><span>${mem.length} member${mem.length===1?"":"s"}</span><span>Code <b class="code">${esc(S.club.code)}</b> <button class="flink" id="clubCopy">Copy</button></span></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px"><button class="btn sm" id="clubInvFr">Invite friends</button><button class="ghost outline sm" id="clubInvite">Invite by email</button></div>
    <ol class="mini-board">${top.map((p,i)=>`<li><span>${i+1}</span><span class="nm" data-id="${esc(p.id)}"></span><b>${p.xp||0} XP</b></li>`).join("")}</ol>
    <p class="note">${gw.length?`Gauntlet leader this week: <b class="gl"></b> with ${gw[0].gScore}.`:"No one in the club has played this week's Gauntlet yet."}</p>
    <div class="actions" style="margin-top:8px">${S.club.officer?`<button class="btn sm" id="clubOfficer">Officer view</button>`:""}<button class="ghost" id="clubLeave">Leave club</button></div>`;
  el.querySelectorAll(".nm[data-id]").forEach(n=>n.textContent=displayName(n.dataset.id));if(gw.length)el.querySelector(".gl").textContent=displayName(gw[0].id);
  $("#clubInvite").onclick=()=>inviteClub(name);
  $("#clubCopy").onclick=async()=>{try{await navigator.clipboard.writeText(S.club.code);toast("Code copied")}catch(e){toast("Code: "+S.club.code)}};
  $("#clubLeave").onclick=()=>{const b=$("#clubLeave");b.outerHTML=`<span class="confirm">Leave ${esc(name)}? <button class="ghost danger" id="clY">Leave</button><button class="ghost" id="clN">Cancel</button></span>`;$("#clY").onclick=()=>{S.club=null;save();syncProfile();renderClub()};$("#clN").onclick=renderClub;$("#clN").focus()};
  if($("#clubOfficer"))$("#clubOfficer").onclick=()=>{const rows=mem.slice().sort((a,b)=>(b.xp||0)-(a.xp||0));
    openPanel(`<div class="label">Officer view</div><h2>${esc(name)}</h2><p class="sub">${rows.length} members. Members appear here once they join with code <b>${esc(S.club.code)}</b> while signed in.</p>
      <div class="tbl-wrap"><table><thead><tr><th>Member</th><th>Title</th><th>XP</th><th>Levels</th><th>Interview avg</th><th>Gauntlet</th><th>Streak</th><th>Active</th></tr></thead><tbody>${rows.map(p=>`<tr><td class="nm" data-id="${esc(p.id)}"></td><td>${RANKS[p.rank||0][0]}</td><td>${p.xp||0}</td><td>${p.levels||0}</td><td>${p.mockN?p.mockAvg:"–"}</td><td>${p.gWeek===isoWeek()?p.gScore:"–"}</td><td>${p.streak||0}</td><td>${p.updated?ago(p.updated):"–"}</td></tr>`).join("")}</tbody></table></div>`);
    panel.classList.add("wide");panel.querySelectorAll(".nm[data-id]").forEach(n=>n.textContent=displayName(n.dataset.id))}}
function ago(t){const m=Math.round((Date.now()-t)/6e4);return m<60?m+"m ago":m<1440?Math.round(m/60)+"h ago":Math.round(m/1440)+"d ago"}

/* ---------- 5. live duels ---------- */
let ROOM=null,DUEL=null;
/* Live rooms on the real site: Supabase Realtime presence (free, no tables needed). Same interface the duel code
   used before (join -> presence(obj) / onPeers(cb, onLost) / leave), so duels work on mnaprep.com, not just in previews. */
function sbRoom(){const sb=window.MA_AUTH&&MA_AUTH.sb;if(!sb||typeof sb.channel!=="function")return null;
  const me=(typeof myId!=="undefined"&&myId)||("g"+Math.random().toString(36).slice(2,10));
  return {join:name=>new Promise((res,rej)=>{const key=me+"-"+Math.random().toString(36).slice(2,6);
    let ch=null,mine={by:(typeof myId!=="undefined"&&myId)||null},cbs=[],lost=null,done=false,left=false,tries=0,retryT=null;
    const peers=()=>{if(!ch)return[];const st=ch.presenceState();return Object.entries(st).map(([k,arr])=>{const p=arr[arr.length-1]||{};return {key:k,sameTab:k===key,kind:"viewer",presence:p,by:p.by||null}})};
    const api={presence:async o=>{mine={...mine,...o};if(ch)try{await ch.track(mine)}catch(e){}},onPeers:(f,l)=>{cbs.push(f);lost=l;f({peers:peers()})},
      leave:()=>{if(left)return;left=true;clearTimeout(retryT);const c=ch;ch=null;if(c){try{c.untrack()}catch(e){}try{sb.removeChannel(c)}catch(e){}}}};
    /* (Re)connect. Background tabs and phone sleep can drop the socket: rejoin the same room with the same
       presence (score so far) instead of ending the duel. Give up only after several tries. */
    function connect(){if(left)return;const c=sb.channel("ma-"+name,{config:{presence:{key}}});ch=c;
      c.on("presence",{event:"sync"},()=>{if(ch!==c)return;const ps=peers();cbs.forEach(f=>{try{f({peers:ps})}catch(e){}})});
      c.subscribe(s=>{if(left||ch!==c)return;
        if(s==="SUBSCRIBED"){tries=0;if(!done){done=true;clearTimeout(to);res(api)}c.track(mine).catch(()=>{});return}
        if(!done){if(s==="CHANNEL_ERROR"||s==="TIMED_OUT"){done=true;clearTimeout(to);rej(new Error(s))}return}
        if(++tries>6){if(lost){const l=lost;lost=null;try{l()}catch(e){}}return}
        ch=null;try{sb.removeChannel(c)}catch(e){}clearTimeout(retryT);retryT=setTimeout(connect,Math.min(800*tries,4000))})}
    const to=setTimeout(()=>{if(!done){done=true;left=true;try{ch&&sb.removeChannel(ch)}catch(e){}rej(new Error("timeout"))}},10000);
    document.addEventListener("visibilitychange",()=>{if(!document.hidden&&done&&!left&&!ch){clearTimeout(retryT);connect()}});
    connect()})}}
const roomPromise=capUse("room").then(r=>ROOM=r);
function renderDuel(){const el=$("#duelCard");if(!el)return;
  if(DUEL){el.innerHTML=`<div class="label">Live duel</div><h3>Duel in progress</h3><p class="note">Code <b class="code">${esc(DUEL.code)}</b></p><button class="btn sm" id="duelOpen">Return to duel</button>`;$("#duelOpen").onclick=drawDuel;return}
  el.innerHTML=`<div class="label">Live duel</div><h3>Challenge a friend</h3><p class="note">Same 10 questions, live. Most correct wins; ties go to the faster player.</p>
    <div class="club-forms"><div><button class="btn sm" id="duelNew">Start a duel</button></div><div><input id="duelCode" maxlength="6" placeholder="Duel code" aria-label="Duel code"><button class="ghost outline" id="duelJoin">Join</button></div></div>`;
  $("#duelNew").onclick=()=>startDuel(randCode(5),true);$("#duelJoin").onclick=()=>{const c=$("#duelCode").value.trim().toLowerCase();if(!/^[a-z0-9]{5}$/.test(c)){toast("Enter the 5-character code");return}startDuel(c,false)}}
async function startDuel(code,host){await roomPromise;if(!ROOM)ROOM=sbRoom();if(!ROOM){toast("Live duels need a connection. Refresh and try again.");return}
  let r;try{r=await ROOM.join("duel-"+code)}catch(e){toast(e&&e.code==="not_permitted"?"Duels aren't available for your account here.":"Couldn't connect. Try again.");return}
  DUEL={code,host,room:r,seed:host?randCode(8):null,state:"lobby",n:0,correct:0,t0:0,opp:null};
  await r.presence({role:host?"host":"guest",seed:DUEL.seed,n:0,correct:0,done:false,ready:true});
  r.onPeers(ch=>{const others=ch.peers.filter(p=>!p.sameTab&&p.kind==="viewer"&&p.presence&&p.presence.role);DUEL&&(DUEL.opp=others[0]||null);
    if(DUEL&&DUEL.opp&&DUEL.opp.by)loadNames([DUEL.opp.by]).then(()=>{if(DUEL&&!ov.hidden&&panel.querySelector(".duel"))drawDuel()});
    if(DUEL&&!DUEL.host&&DUEL.state==="lobby"){const h=others.find(p=>p.presence.role==="host");if(h&&h.presence.seed)DUEL.seed=h.presence.seed;if(h&&h.presence.start)beginDuel()}
    if(DUEL&&!ov.hidden&&panel.querySelector(".duel"))drawDuel()},()=>{toast("Duel connection lost");endDuelRoom()});
  drawDuel();renderDuel()}
function duelQs(){const r=seeded("duel"+DUEL.seed);const p=allQs().slice();for(let i=p.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[p[i],p[j]]=[p[j],p[i]]}return p.slice(0,10).map(q=>{const r2=seeded(q[0]+DUEL.seed);const idx=q[1].map((_,k)=>k).sort(()=>r2()-.5);return{raw:q,q:q[0],o:idx.map(k=>q[1][k]),a:idx.indexOf(q[2]),w:q[3]}})}
function beginDuel(){if(!DUEL||DUEL.state!=="lobby")return;DUEL.state="countdown";DUEL.Q=duelQs();drawDuel();setTimeout(()=>{if(!DUEL)return;DUEL.state="play";DUEL.t0=Date.now();drawDuel()},3000)}
function oppName(){const o=DUEL&&DUEL.opp;return o?(o.by&&NAMES[o.by])||"Opponent":"Opponent"}
function drawDuel(){if(!DUEL)return;const o=DUEL.opp,op=o?o.presence:{};const isOpen=!ov.hidden&&panel.querySelector(".duel");
  const bars=`<div class="duel-bars"><div><span>You</span><div class="db"><i style="width:${DUEL.n*10}%"></i></div><b>${DUEL.correct}</b></div><div><span class="on"></span><div class="db opp"><i style="width:${(op.n||0)*10}%"></i></div><b>${op.correct||0}</b></div></div>`;
  let body="";
  if(DUEL.state==="lobby")body=`<h2>${o?"Opponent connected":"Waiting for an opponent"}</h2><p class="sub">Share this code: <b class="code big">${esc(DUEL.code)}</b></p>${o?(DUEL.host?`<div class="actions"><button class="btn" id="duStart">Start the duel</button></div>`:`<p class="note">Waiting for the host to start…</p>`):`<p class="note">They open Compete, tap Join and enter the code.</p>`}`;
  else if(DUEL.state==="countdown")body=`<h2 class="count">Get ready…</h2>`;
  else if(DUEL.state==="play"){const q=DUEL.Q[DUEL.n];body=`${bars}<div class="q">${q.q}</div><div class="opts">${q.o.map((x,j)=>`<button class="opt" data-k="${j}"><span class="k">${"ABCD"[j]}</span><span>${x}</span></button>`).join("")}</div>`}
  else if(DUEL.state==="done"){const od=op.done;let res="Waiting for your opponent to finish…";
    if(od){const me=DUEL.correct,them=op.correct||0;if(!DUEL.counted){DUEL.counted=true;A().duels=(A().duels||0)+1;if(me>them||(me===them&&DUEL.secs<(op.secs||1e9)))A().duelWins=(A().duelWins||0)+1;save();setTimeout(checkBadges,50)}res=me>them||(me===them&&DUEL.secs<=(op.secs||1e9))?"You win.":me===them&&DUEL.secs===op.secs?"It's a tie.":"You lost this one."}
    body=`${bars}<h2>${res}</h2><p class="sub">You: ${DUEL.correct}/10 in ${fmtSec(DUEL.secs)}${od?` · Opponent: ${op.correct||0}/10 in ${fmtSec(op.secs||0)}`:""}</p><div class="actions"><button class="btn" id="duAgain">New duel</button><button class="ghost" id="duClose">Close</button></div>`}
  const html=`<div class="duel"><div class="label">Live duel · ${esc(DUEL.code)}</div>${body}</div>`;
  if(isOpen){panel.querySelector(".duel").outerHTML=html}else{openPanel(html);panel.querySelector(".close").onclick=()=>{closePanel();if(DUEL&&DUEL.state!=="play"&&DUEL.state!=="countdown"&&!(DUEL.state==="lobby"))endDuelRoom();renderDuel()}}
  const on=panel.querySelector(".duel-bars .on");if(on)on.textContent=oppName();
  if($("#duStart"))$("#duStart").onclick=async()=>{await DUEL.room.presence({start:Date.now()});beginDuel()};
  if($("#duAgain"))$("#duAgain").onclick=()=>{endDuelRoom();closePanel();startDuel(randCode(5),true)};
  if($("#duClose"))$("#duClose").onclick=()=>{endDuelRoom();closePanel();renderDuel()};
  if(DUEL.state==="play")panel.querySelectorAll(".opt").forEach(b=>b.onclick=()=>{const q=DUEL.Q[DUEL.n],ok=+b.dataset.k===q.a;logAnswer(q.raw,ok);if(ok)DUEL.correct++;
    panel.querySelectorAll(".opt").forEach(x=>{x.disabled=true;if(+x.dataset.k===q.a)x.classList.add("right")});if(!ok)b.classList.add("wrong");DUEL.n++;
    const fin=DUEL.n>=10;if(fin){DUEL.secs=Math.round((Date.now()-DUEL.t0)/1000)}
    DUEL.room.presence({n:DUEL.n,correct:DUEL.correct,done:fin,secs:fin?DUEL.secs:null}).catch(()=>{});
    setTimeout(()=>{if(!DUEL)return;if(fin)DUEL.state="done";drawDuel()},ok?300:700)});
  const f=panel.querySelector(".opt,.btn");if(f&&!isOpen)f.focus()}
function endDuelRoom(){const d=DUEL;DUEL=null;if(d&&d.room){try{d.room.leave()}catch(e){}}renderDuel()}

/* ---------- 6. deal breakdowns ---------- */
let DEALS=[
 {"id":"d38","buyer":"Marvell Technology","target":"Lumentum","value":"~$115B","usd":115,"date":"Nov 2, 2026","terms":["4.5 Marvell shares per Lumentum share","All stock","~23.9% premium to Oct 28 prices"],"what":"Marvell agreed to buy Lumentum, a maker of lasers and optical parts for AI data centers, in an all-stock deal valued at about $115 billion, or about $1,132 per Lumentum share at Oct 28 prices. Marvell owners would hold about 67% of the combined company and Lumentum owners about 33%, with closing expected in the first half of 2028.","why":"Marvell makes chips that move data, and it wants more optical technology and factory capacity as AI data centers shift from copper to light. The companies expect more than $1 billion of yearly cost savings and say the deal should add to Marvell's adjusted EPS in the first year after closing.","say":"\"Because Marvell is paying a fixed 4.5 shares, the $115 billion headline moves with its stock, so Lumentum's owners take on Marvell's share price risk until closing in 2028.\"","src":[["Yahoo Finance","https://finance.yahoo.com/markets/stocks/articles/marvell-strikes-115b-deal-acquire-124300132.html"],["Marvell 8-K via Stocktitan","https://www.stocktitan.net/sec-filings/MRVL/8-k-marvell-technology-inc-reports-material-event-7df547335b18.html"]],"q":[["Marvell is paying a fixed 4.5 Marvell shares for each Lumentum share. If Marvell's stock falls before closing, what happens to Lumentum owners' payout?",["It stays locked at the $1,132 headline price","It rises because Marvell issues extra shares","Its value falls because the 4.5 ratio is fixed","It converts into cash at the Oct 28 stock price"],2,"With a fixed exchange ratio, the share count stays the same, so the dollar value moves up and down with the buyer's stock."],["Marvell must pay Lumentum $3.2 billion if the merger ends over certain regulatory problems. Why would Lumentum ask for this fee?",["It pays Lumentum for failed-review risk","It lets Marvell skip the U.S. antitrust review","It raises the exchange ratio when deals close","It funds the $1 billion of planned cost savings"],0,"A reverse termination fee protects the target, which can lose years and business momentum if regulators block the merger."]]},
 {"id":"d39","buyer":"Blackstone and four Canadian pension investors","target":"49.9% of a Mitsubishi LNG Canada unit","value":"$3.1B","usd":3.1,"date":"Nov 2, 2026","terms":["49.9% non-controlling stake","Unit holds Mitsubishi's 15% of LNG Canada","Mitsubishi keeps its full LNG supply"],"what":"Blackstone, CPP Investments, OMERS, IMCO and PSP Investments agreed to pay US$3.1 billion for 49.9% of a Mitsubishi subsidiary. The subsidiary holds Mitsubishi's 15% interest in LNG Canada, the country's first liquefied natural gas export plant.","why":"Mitsubishi raises cash from a finished, long-life project while keeping control and its full share of the plant's gas. The investors get a stake in energy infrastructure, which pension funds like for steady, long-term income.","say":"\"It's a minority stake sale: Mitsubishi gets $3.1 billion of cash and keeps control, and the price implies about $6.2 billion for the whole unit.\"","src":[["Canadian Press via BNN Bloomberg","https://bnnbloomberg.ca/business/company-news/2026/11/02/blackstone-led-group-buys-into-mitsubishi-subsidiary-that-holds-lng-canada-stake"]],"q":[["A Blackstone-led group is buying a 49.9% non-controlling stake in a Mitsubishi unit that holds part of LNG Canada. What does non-controlling mean here?",["Blackstone's group can force a sale of the unit","Mitsubishi keeps majority ownership of the unit","Mitsubishi must buy the stake back within a year","The Canadian government must run the LNG plant"],1,"Holding under 50% means the investors own a big piece, but Mitsubishi keeps the majority and with it control."],["Blackstone's group is paying $3.1 billion for 49.9% of a Mitsubishi LNG Canada unit. About what value does that imply for all of the unit?",["$1.5 billion","$3.1 billion","$4.6 billion","$6.2 billion"],3,"Divide the price by the stake: $3.1 billion ÷ 0.499 ≈ $6.2 billion for 100% of the unit."]]},
 {"id":"d35","buyer":"UMB Financial","target":"El Dorado Savings Bank","value":"~$506M","usd":0.506,"date":"Oct 29, 2026","terms":["~52% cash, ~48% UMB stock","13.553 UMB shares + $1,958.88 cash per share","$2.1B of deposits, 35 branches"],"what":"Kansas City-based UMB Financial agreed to buy El Dorado Savings Bank, a California bank with about $2.4 billion of assets, for about $506 million in cash and stock. Closing is expected in the first quarter of 2027 if regulators and El Dorado's owners approve.","why":"El Dorado brings $2.1 billion of deposits and 35 branches in California and Nevada, taking UMB to 227 branches in 15 states. UMB gets a much bigger West Coast footprint and a cheap, steady base of deposits to fund loans.","say":"\"UMB is paying about $506 million, mostly for El Dorado's $2.1 billion of deposits and 35 West Coast branches, which give it cheap funding and a bigger footprint in California.\"","src":[["South Tahoe Now","https://southtahoenow.com/10/29/2026/umb-financial-corporation-to-acquire-el-dorado-savings"]],"q":[["UMB Financial is paying for El Dorado Savings Bank with about 52% cash and 48% UMB stock. What does the stock part mean for El Dorado's owners?",["They must sell their shares back to El Dorado for cash","They become part-owners of UMB and share in its results","They receive UMB bonds that pay a fixed yearly interest rate","They keep their El Dorado shares, which stay publicly listed"],1,"Sellers paid in stock swap their shares for the buyer's shares, so they own part of the combined bank and share its future ups and downs."],["UMB Financial's ~$506M purchase of El Dorado Savings Bank adds $2.1 billion of deposits and 35 branches. Why do banks often buy other banks for their deposits?",["Deposits count as revenue the day the deal closes","Regulators require banks to double deposits every five years","Deposits let a bank skip its own capital requirements","Deposits are a cheap, steady source of money to fund loans"],3,"Banks earn money by lending, and customer deposits usually cost much less than borrowing in the bond market, so a big deposit base is valuable."]]},
 {"id":"d1","buyer":"Schneider Electric","target":"PTC","value":"$22.6B","date":"Oct 5, 2026","terms":["$205 per share","All cash","Equity value"],"what":"French industrial giant Schneider Electric agreed to buy PTC, a U.S. maker of design and engineering software, for $205 a share in cash.","why":"Schneider sells equipment for factories and buildings. Owning PTC's software adds recurring revenue and ties its hardware to the tools engineers use every day.","say":"\"It's a strategic deal: a hardware company paying up for recurring software revenue it can cross-sell to its industrial customers.\"","q":[["Schneider is best described as what kind of buyer?",["Financial buyer","Strategic buyer","Activist","Sovereign fund"],1,"It's an operating company buying a business that fits its own, so it can pay for synergies."],["Paying all cash means PTC shareholders:",["Become Schneider shareholders","Receive cash and exit","Keep their PTC shares","Get bonds"],1,"In an all-cash deal, target shareholders are paid out and no longer own the business."]]},
 {"id":"d34","buyer":"Thrive Holdings","target":"ADT","value":"~$7.6B","usd":7.6,"date":"Oct 29, 2026","terms":["$10.00 per share","All cash","~46% premium"],"what":"Thrive Holdings, a company that buys and runs businesses for the long term, agreed to buy home-security company ADT for $10.00 a share in cash. That values ADT's stock at about $7.6 billion and the whole company, including its debt, at about $15.3 billion.","why":"ADT will become the base of Thrive's smart-home security business, next to the more than 75 companies it owns in areas like accounting and IT services. Funds managed by Apollo affiliates are providing all of the financing, and the deal has no financing condition.","say":"\"Thrive's $10 cash offer gives ADT a $7.6 billion equity value but a $15.3 billion enterprise value, so roughly half of what Thrive is taking on is ADT's debt and other claims.\"","src":[["ADT press release (SEC 8-K)","https://www.sec.gov/Archives/edgar/data/0001703056/000119312526437123/d572133dex991.htm"],["Quiver Quantitative","https://www.quiverquant.com/news/ADT+to+Be+Acquired+by+Thrive+Holdings+in+$7.6+Billion+All-Cash+Deal"]],"q":[["Thrive Holdings agreed to pay $10.00 cash per ADT share, versus ADT's unaffected close of $6.87. About what premium is that?",["33%","46%","52%","60%"],1,"($10.00 − $6.87) ÷ $6.87 ≈ 46%; the 52% figure is the premium over ADT's 30-day average price, not its last close."],["ADT's deal with Thrive Holdings includes a 30-day go-shop ending Nov 28, 2026. What does that let ADT do?",["Sell ADT assets to raise cash before closing","Delay the vote until Apollo's financing is set","Seek rival bids from other buyers for 30 days","Buy back ADT shares at the $10 offer price"],2,"A go-shop lets the target actively look for a higher offer after signing, which helps the board show it got the best price."]]},
 {"id":"d33","buyer":"DoorDash","target":"Instacart (Maplebear)","value":"~$17B","usd":17,"date":"Oct 29, 2026","terms":["$65.00 per share","At least 75% cash","26% premium"],"what":"DoorDash agreed to buy Instacart's parent company, Maplebear, for $65 a share, about $17 billion of equity value. Instacart holders can choose cash, DoorDash stock or a mix, but stock is capped at 25% of the total, and the deal should close by late 2027 or the first half of 2028.","why":"DoorDash gets the leading U.S. grocery-delivery platform and its retailer software, plus a bigger ad business. Together they can offer local grocers one delivery network to compete with Walmart and Amazon.","say":"\"It's a mostly-cash strategic deal funded with a bridge loan, so the key risks are antitrust review and how much new debt DoorDash takes on while trying to keep its investment-grade rating.\"","src":[["DoorDash press release","https://ir.doordash.com/news/news-details/2026/DoorDash-to-Acquire-Instacart-to-Help-Local-Stores-Win/default.aspx"],["InsideArbitrage","https://www.insidearbitrage.com/2026/10/doordash-to-acquire-instacart-for-17-billion/"]],"q":[["DoorDash is paying for Instacart with at least 75% cash and at most 25% DoorDash stock. What is the main benefit of the stock portion for DoorDash?",["It uses less new debt and protects the credit rating","It guarantees antitrust approval from regulators","It lets DoorDash skip the shareholder vote","It locks in a lower price per Instacart share"],0,"Paying part of the price in stock means borrowing less, which helps DoorDash keep its investment-grade rating."],["JPMorgan gave DoorDash a 364-day bridge loan commitment for the Instacart deal. What is a bridge loan used for?",["Paying Instacart's employee retention bonuses","Covering the breakup fee if the deal fails","Short-term funding until bonds are issued later","Buying back DoorDash shares after closing"],2,"A bridge loan guarantees the cash is there at signing; the buyer usually replaces it with longer-term bonds before or at closing."]]},
 {"id":"d29","buyer":"GE Vernova","target":"Trench Group (from Triton Partners)","value":"~$9.0B","usd":9,"date":"Oct 28, 2026","terms":["~$9.0B (euro price at 1.12 $/€)","Half cash, half new debt","~13x 2028E adj. EBITDA"],"what":"GE Vernova agreed to buy Trench Group, a Berlin-based maker of high-voltage grid parts, from private equity firm Triton Partners for about $9 billion. GE Vernova will pay with roughly equal parts cash and debt, and expects the deal to close in late 2027 after regulatory approvals.","why":"Trench already supplies GE Vernova, so buying it locks in parts that are in short supply as utilities and data centers rush to expand the power grid. Trench brings about $5 billion of backlog and roughly 33-36% EBITDA margins, which should lift GE Vernova's margins.","say":"\"It's a vertical deal: GE Vernova is buying a key supplier at about 13x forward EBITDA to secure grid capacity, and it hands seller Triton a clean exit to a strategic buyer.\"","src":[["GE Vernova via Yahoo Finance","https://finance.yahoo.com/energy/articles/ge-vernova-acquire-trench-group-101700412.html"],["Bloomberg","https://www.bloomberg.com/news/articles/2026-10-28/ge-vernova-agrees-to-pay-9-billion-to-acquire-trench-group"]],"q":[["GE Vernova is buying Trench Group, a company that already supplies it with grid parts. What kind of acquisition is GE Vernova's Trench deal?",["A horizontal deal that removes a direct rival","A conglomerate deal into an unrelated industry","A vertical deal that buys a key supplier","A reverse merger that takes Trench public"],2,"Buying a company earlier in your own supply chain is vertical integration, which secures supply and captures the supplier's margin."],["GE Vernova values Trench at about 13x its 2028 adjusted EBITDA. Why would a buyer quote a multiple on a future year's EBITDA?",["Future EBITDA numbers are always audited by the SEC","Fast growth makes a forward multiple look cheaper","Tax law requires deal prices to use forward figures","Triton insisted on using last year's actual results"],1,"For a fast-growing target, a forward-year multiple is lower than a trailing one, so it makes the price look more reasonable."]]},
 {"id":"d13","buyer":"EQT","target":"Qiagen","value":"~$12.1B","usd":12.1,"date":"Oct 21, 2026","terms":["€46.50 per share","All cash","~40% premium"],"what":"Private equity firm EQT agreed to take diagnostics company Qiagen private for €46.50 a share in cash. Including about $1.1 billion of debt, the deal is worth about €10.8 billion (~$12.1 billion).","why":"Qiagen says private ownership will let it invest for the long term and move faster. Analysts at William Blair put the price at about 15x expected 2027 EBITDA, below similar life-science deals.","say":"\"This is a take-private: EQT pays a ~40% premium over the undisturbed price, measured before takeover rumors leaked in July.\"","src":[["MedTech Dive","https://www.medtechdive.com/news/qiagen-agrees-to-private-equity-takeover/833805/"]],"q":[["The ~40% premium is measured against Qiagen's price before takeover reports in July. Why use that date?",["It was the highest price of the year","It is the undisturbed price, before rumors pushed the stock up","Regulators require July prices","It is the date the deal closes"],1,"Rumors lift a stock, so premiums are measured from the undisturbed price."],["EQT pays €46.50 a share, about a 40% premium. Qiagen's undisturbed share price was roughly:",["€19","€28","€33","€40"],2,"46.50 ÷ 1.40 ≈ €33."]]},
 {"id":"d23","buyer":"Ares Capital","target":"MidCap Financial Investment Corp.","value":"~$2.6B","usd":2.6,"date":"Oct 27, 2026","terms":["$10.88 per share","~$1.21 cash + ~$9.67 in ARCC stock","~30% premium"],"what":"Ares Capital (ARCC), the largest business development company (BDC), agreed to buy Apollo-managed lender MidCap Financial (MFIC) in a deal worth about $2.6 billion. MFIC holders get about $10.88 a share, mostly in ARCC stock plus some cash paid by Ares Management, with closing expected in the first half of 2027.","why":"BDCs are public funds that lend to mid-sized, often PE-owned companies, and scale lowers their costs and borrowing rates. ARCC adds more than 200 loans and says the deal should modestly lift core earnings per share.","say":"\"MFIC traded below its net asset value, so Ares can pay a 30% premium to the share price and still buy the loan book for less than the roughly $12.86 per share it is carried at.\"","src":[["Stock Titan (Business Wire)","https://www.stocktitan.net/news/ARCC/ares-capital-corporation-agrees-to-acquire-mid-cap-financial-dhrvbzpwpvlr.html"],["FX News Group","https://fxnewsgroup.com/forex-news/institutional/ares-capital-corporation-agrees-to-acquire-midcap-financial-investment-corporation-for-2-6bn/"]],"q":[["Ares Capital is paying MFIC holders about $10.88 a share, mostly in ARCC stock. What does a mostly-stock offer mean for MFIC holders?",["They lock in a fixed cash amount at closing","They share in ARCC's future share price moves","They must pay tax at signing, not closing","They lose all ownership in the combined lender"],1,"Taking stock means MFIC holders become ARCC owners, so their final value rises or falls with ARCC's shares."],["Ares Capital's $10.88 offer is a 30% premium to MFIC's price but below MFIC's ~$12.86 net asset value. Why can both be true?",["MFIC's NAV was restated lower by Ares at signing","The premium is measured against the 30-day VWAP","MFIC stock traded at a big discount to its NAV","The cash part is excluded from the premium math"],2,"BDC shares often trade below the value of their loans, so a buyer can pay a premium to price and still pay under NAV."]]},
 {"id":"d16","buyer":"EQT Corp.","target":"Range Resources","value":"~$12.8B","usd":12.83,"date":"Oct 26, 2026","terms":["0.987 EQT shares per Range share","All stock","~20.6% premium"],"what":"EQT Corp., the largest U.S. natural gas producer, agreed to buy rival Range Resources by swapping its own shares for Range's. Reuters put Range's equity value at about $12.8 billion, and the combined company is worth more than $50 billion including debt.","why":"Data centers are driving up demand for natural gas, and a bigger producer can drill more cheaply and sell gas more effectively. EQT expects about $325 million a year in savings within two years, rising to over $600 million long term.","say":"\"It's an all-stock merger of equals in spirit: Range holders take a ~20% premium in EQT shares and end up owning about 27% of the combined gas giant.\"","src":[["Reuters via Investing.com","https://za.investing.com/news/stock-market-news/eqt-range-resources-tie-up-in-50-billionplus-deal-to-create-us-gas-giant-4524945"],["Investing.com","https://www.investing.com/news/company-news/eqt-to-acquire-range-resources-in-50-billion-allstock-deal-93CH-4971856"]],"q":[["Range holders get 0.987 EQT shares each. If EQT stock falls 10% before closing, what happens to the value Range holders receive?",["It stays fixed at $54.91","It falls too, because the share ratio is fixed","It rises","The deal is cancelled automatically"],1,"With a fixed exchange ratio, the target's payout moves with the buyer's stock price."],["Why might EQT's stock fall when the deal is announced while Range's jumps?",["EQT is paying a premium and issuing new shares, diluting its holders","Range is paying EQT","All-stock deals are illegal","EQT is going private"],0,"The buyer pays a premium and issues shares, so its stock often dips while the target rises toward the offer."]]},
 {"id":"d26","buyer":"CoStar Group","target":"Vexcel","value":"~$730M","usd":0.73,"date":"Oct 27, 2026","terms":["~$730M purchase price","All cash (cash on hand + revolver)","Expected close Q1 2027"],"what":"Real estate data company CoStar agreed to buy Vexcel, which flies planes with its own UltraCam cameras to take high-detail aerial photos of 320 big cities and turns them into property data. Vexcel had over $140 million in revenue in the last twelve months, up more than 30%.","why":"CoStar wants fresher, more accurate property data for its listings and analytics, and plans to use its large sales team to sell Vexcel's data to more customers like insurers. CoStar says the deal should add to its adjusted earnings per share in the first full year.","say":"\"CoStar is paying roughly 5x revenue for Vexcel, a fast-growing data business with mostly recurring contracts, and expects the deal to be accretive in year one.\"","src":[["CoStar press release (SEC 8-K Exhibit 99.2)","https://www.sec.gov/Archives/edgar/data/0001057352/000105735226000078/exhibit992-vexcelpressre.htm"]],"q":[["CoStar is paying about $730M for Vexcel, which has about $140M of trailing revenue. Roughly what EV/Revenue multiple is that?",["About 2x trailing revenue","About 5x trailing revenue","About 9x trailing revenue","About 14x trailing revenue"],1,"$730M divided by about $140M of revenue is roughly 5.2x, an EV/Revenue multiple."],["CoStar says buying Vexcel will be accretive to adjusted EPS in year one. What does accretive mean?",["CoStar's EPS goes up because of the deal","CoStar's share count goes down after closing","Vexcel's revenue grows faster than CoStar's","CoStar's debt falls because Vexcel pays cash"],0,"An accretive deal raises the buyer's earnings per share; a dilutive one lowers it."]]},
 {"id":"d31","buyer":"Ferring Pharmaceuticals","target":"Gameto","value":"Up to ~$1.38B","usd":1.3825,"date":"Oct 27, 2026","terms":["Up to $1.3825B total","Part paid only if milestones are hit","Upfront amount not disclosed"],"what":"Swiss drugmaker Ferring, a big name in fertility treatments, signed a deal to buy Gameto, a private biotech that uses cell engineering to develop treatments for infertility and other women's reproductive health issues. The deal is worth up to about $1.38 billion, but part of that is only paid if Gameto hits development, regulatory and sales goals.","why":"Ferring gets a pipeline of new fertility technology, including an egg-maturation program that is still investigational in the U.S., and can use its global sales network to reach more patients. Tying much of the price to milestones protects Ferring if the science or FDA approval doesn't pan out.","say":"\"Ferring's up-to-$1.38 billion deal for Gameto ties part of the price to future milestones, which is how buyers handle the risk that an unapproved biotech product never makes it to market.\"","src":[["Ferring press release","https://www.ferring.com/ferring-pharmaceuticals-and-gameto-sign-agreement-for-proposed-acquisition/"],["PharmaShots","https://pharmashots.com/36809/ferring-to-acquire-gameto"]],"q":[["Ferring's deal for Gameto is worth 'up to' $1.38B because some payments depend on future milestones. What is that kind of payment called?",["Contingent consideration paid later if goals are met","A breakup fee paid if the deal fails to close","A tender offer made directly to public shareholders","A dividend recap funded by new debt at the target"],0,"Milestone payments are contingent consideration: the buyer pays more only if the target reaches set goals."],["Gameto's main program is not yet FDA approved. Why does that make milestone payments attractive to Ferring when buying Gameto?",["They let Ferring avoid any regulatory review of the deal","They make Gameto's shareholders pay Ferring's legal fees","They cut what Ferring pays if the product never gets approved","They guarantee Ferring a fixed return on the whole purchase"],2,"Paying part of the price only on success shifts the risk of a failed trial or rejection back to the sellers."]]},
 {"id":"d32","buyer":"Guidewire","target":"hyperexponential (hx)","value":"Up to $2.1B","usd":2.1,"date":"Oct 27, 2026","terms":["$1.7B base price in cash","Up to $400M more tied to recurring revenue targets","Funded by a $1.0B new term loan plus cash"],"what":"Guidewire, which sells core software to more than 570 property and casualty (P&C) insurers, agreed to buy hyperexponential, a London startup whose AI tools help commercial insurers decide which risks to take on and how to price them. Guidewire pays $1.7 billion in cash up front and up to $400 million more if hx hits recurring revenue goals.","why":"Guidewire runs the back-office systems insurers use for policies, billing and claims, and hx adds the underwriting and pricing step that comes before a policy is written. Guidewire says the deal should add at least 6.5 percentage points to its annual recurring revenue (ARR) growth in fiscal 2027.","say":"\"Guidewire's up-to-$2.1 billion deal for hyperexponential pairs a $1.7 billion cash price with a $400 million earnout, so the sellers only get full value if hx keeps growing recurring revenue.\"","src":[["Guidewire press release (SEC 8-K)","https://www.sec.gov/Archives/edgar/data/0001528396/000119312526432656/d121813dex991.htm"],["FinTech Global","https://fintech.global/2026/10/28/guidewire-agrees-2-1bn-acquisition-of-hyperexponential/"]],"q":[["Guidewire will pay up to $400M extra for hyperexponential if hx hits recurring revenue targets. What is this part of the price usually called?",["A reverse termination fee owed by Guidewire","An earnout paid only if targets are reached","A working capital adjustment made at closing","A rollover of equity held by hx's founders"],1,"An earnout is contingent consideration: the buyer pays more later only if the business hits agreed goals, which bridges a gap in price expectations."],["Guidewire is funding its $1.7B cash payment for hyperexponential with a $1.0B term loan plus cash on hand. What is a key effect for Guidewire's shareholders?",["They are diluted because new shares are issued","They must approve the deal in a special vote","The deal's cost is pushed onto hx's insurance clients","No dilution, but Guidewire takes on new debt"],3,"Paying with cash and debt instead of stock means no new shares, so ownership isn't diluted, but the company adds leverage and interest costs."]]},
 {"id":"d36","buyer":"Ahold Delhaize","target":"Tesco Czechia and Slovakia","value":"~€1.2B (~$1.34B)","usd":1.34,"date":"Oct 30, 2026","terms":["~€1.2B enterprise value (~€1.7B including leases)","~7.2x EV/EBITDA, ~5.0x after synergies","Paid with committed financing and existing resources"],"what":"Ahold Delhaize, the Dutch owner of Food Lion, Stop & Shop and Albert, agreed to buy Tesco's grocery business in Czechia and Slovakia for an enterprise value of about €1.2 billion. The unit has more than 360 company-run stores plus 100+ franchise stores and about €3.5 billion in sales.","why":"Combined with its Albert stores, Ahold expects to become the top grocery brand in Czechia and gains a first foothold in Slovakia. Grocery is a scale game, so more stores mean better buying power with suppliers and lower costs per store.","say":"\"Ahold Delhaize is paying about 7.2 times EBITDA for Tesco's Czech and Slovak stores, but closer to 5 times once you count synergies, which is how a buyer can justify a price that looks higher than it feels.\"","src":[["Ahold Delhaize press release","https://newsroom.aholddelhaize.com/ahold-delhaize-announces-the-acquisition-of-tesco-czechia-and-slovakia-strengthening-its-position-in-europe/"],["Pound Sterling Live (EUR/USD rate)","https://www.poundsterlinglive.com/history/EUR-USD-2026"]],"q":[["Ahold Delhaize says its Tesco Czechia and Slovakia purchase costs about 7.2x EBITDA, or 5.0x 'including synergies.' Why is the second multiple lower?",["Synergies are added to EBITDA, making the denominator larger","Synergies cut the purchase price Ahold Delhaize pays Tesco at closing","The lower multiple leaves out the leases that Tesco's stores carry","The lower multiple uses Tesco's sales instead of EBITDA as its base"],0,"Adding expected cost savings to the target's EBITDA makes the denominator bigger, so the price looks cheaper as a multiple."],["Ahold Delhaize gives Tesco Czechia and Slovakia two values: ~€1.2B EV and ~€1.7B 'lease-adjusted' EV. What explains the gap?",["The €0.5B gap is a breakup fee owed if regulators block the deal","The €0.5B gap is the extra amount Ahold expects to save each year","The €0.5B gap counts store lease obligations as a form of debt","The €0.5B gap is the value of Tesco's franchise stores in Slovakia"],2,"Under IFRS 16, store leases are treated like debt, so adding them raises enterprise value; the matching EBITDA is also measured before rent."]]},
 {"id":"d37","buyer":"Affle","target":"Perion Network","value":"~$420M","usd":0.42,"date":"Nov 1, 2026","terms":["$11.70 per share","All cash, debt-financed by Citibank","~34.5% premium"],"what":"Affle, an Indian mobile ad-tech company, agreed to buy Nasdaq-listed Perion for $11.70 per share in cash, valuing Perion's equity at about $420 million. Perion's board backed the deal, which still needs shareholder and U.S. antitrust approval.","why":"Affle adds Perion's retail media, connected-TV and digital billboard ad tools to its mobile marketing platform, hoping to sell more to the same advertisers. Perion keeps its brand, and its shareholders get a certain cash price.","say":"\"Affle's all-cash offer for Perion pays a 34.5% premium and includes a 40-day go-shop, which lets Perion's board test the market for a better bid before the deal closes.\"","src":[["Perion press release via Yahoo Finance","https://finance.yahoo.com/markets/stocks/articles/perion-enters-definitive-merger-agreement-103000095.html"]],"q":[["Affle's deal to buy Perion includes a 40-day 'go-shop' period. What does that allow Perion to do?",["Ask Affle to raise its $11.70 price once each week","Actively seek competing offers from other buyers","Let Perion holders swap shares for Affle stock","Delay its shareholder vote until regulators approve"],1,"A go-shop lets the target solicit rival bids for a set time after signing, helping the board show it got the best price."],["Affle is paying $11.70 per share for Perion, a 34.5% premium to its Oct 30 close. Roughly where did Perion stock close that day?",["About $8.70, or $11.70 divided by 1.345","About $7.66, or $11.70 minus 34.5% of it","About $15.74, or $11.70 times 1.345","About $11.36, or $11.70 minus $0.345"],0,"Premium = offer / prior price - 1, so the prior price is $11.70 / 1.345, about $8.70."]]}
];
let DEALS_DATE="Nov 2, 2026";
const DEAL_TIERS=[["high","High","$10B+"],["mid","Mid","$2B–$10B"],["low","Low","Under $2B"]];
const dealUSD=d=>{if(typeof d.usd==="number")return d.usd;const m=String(d.value).replace(/,/g,"").match(/([\d.]+)\s*([BMT])/i);if(!m)return 0;const v=+m[1];return m[2].toUpperCase()==="T"?v*1000:m[2].toUpperCase()==="M"?v/1000:v};
const dealTier=d=>{const v=dealUSD(d);return v>=10?"high":v>=2?"mid":"low"};
let dealTab=null,dealSort="new";
function renderDeals(){const el=$("#deals");if(!el)return;const n=Object.keys(S.deals||{}).length;$("#dealCount").textContent=`${n}/${DEALS.length} done`;
  const dTime=d=>{const t=Date.parse(d.date);return isNaN(t)?0:t};const by=k=>DEALS.filter(d=>dealTier(d)===k).sort((a,b)=>dealSort==="size"?dealUSD(b)-dealUSD(a):dTime(b)-dTime(a)||dealUSD(b)-dealUSD(a));if(!dealTab||!by(dealTab).length)dealTab=(DEAL_TIERS.find(t=>by(t[0]).length)||DEAL_TIERS[0])[0];
  const list=by(dealTab);
  el.innerHTML=`<div class="deal-tiers" role="tablist" aria-label="Deal size">${DEAL_TIERS.map(([k,l,r])=>`<button class="dt" role="tab" data-dt="${k}" aria-selected="${k===dealTab}"><b>${l}</b><span>${r}</span><em>${by(k).length}</em></button>`).join("")}</div>${DEAL_LENS[profKey()]?`<p class="deal-lens">${DEAL_LENS[profKey()]}</p>`:""}<div class="deal-bar"><p class="deal-upd">Updated ${DEALS_DATE} · new deals added as they're announced</p><div class="seg deal-sort" role="group" aria-label="Sort deals"><button data-ds="new" aria-pressed="${dealSort==="new"}">Newest</button><button data-ds="size" aria-pressed="${dealSort==="size"}">Largest</button></div></div>`+list.map(d=>{const b=(S.deals||{})[d.id];return `<details class="deal"><summary><div><b>${esc(d.buyer)} → ${esc(d.target)}</b><span>${esc(d.value)} · ${esc(d.date)}</span></div><span style="display:flex;gap:10px;align-items:center">${PE_NAMES.test(d.buyer+" "+(d.terms||[]).join(" ")+" "+d.what)?`<span class="deal-pe" title="Private equity buyer or seller">PE</span>`:""}${b!==undefined?`<span class="pill">${b}/2</span>`:""}<span class="chev"></span></span></summary>
    <div class="deal-body"><div class="deal-terms">${d.terms.map(t=>`<span>${esc(t)}</span>`).join("")}</div><p><b>What happened.</b> ${linkFirms(esc(d.what))}</p><p><b>Why.</b> ${esc(d.why)}</p><div class="ang"><b>Say it in an interview</b>${esc(d.say)}</div>${d.src?`<p class="deal-src">Source: ${d.src.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(n)} ↗</a>`).join(" · ")}</p>`:""}
    <div class="actions"><button class="btn sm" data-deal="${d.id}">Check yourself · 2 questions</button><button class="rel" data-act="int|M&A">Practice M&A questions →</button></div></div></details>`}).join("");
  el.querySelectorAll("[data-dt]").forEach(b=>b.onclick=()=>{dealTab=b.dataset.dt;renderDeals()});el.querySelectorAll("[data-ds]").forEach(b=>b.onclick=()=>{dealSort=b.dataset.ds;renderDeals()});
  bindRel(el);el.querySelectorAll("[data-deal]").forEach(b=>b.onclick=()=>{const d=DEALS.find(x=>x.id===b.dataset.deal);
    quiz({title:d.buyer+" → "+d.target,qs:d.q,noLog:true,onAnswer:(n,ok)=>{const q=d.q[n];logAnswer([`<span class="qctx">${esc(d.buyer)} → ${esc(d.target)}</span>${q[0]}`,q[1],q[2],q[3]],ok)},finish:c=>{S.deals=S.deals||{};const prev=S.deals[d.id]||0;S.deals[d.id]=Math.max(prev,c);save();questEvt("deal");render();renderDeals();return `<h2>${c} of 2</h2><p>${c>prev?`+${(c-prev)*5} XP`:"Your best run counts."}</p>`}})})}

