const APP_SRC=[["Adventis tracker (Nov 16)","https://www.adventiscg.com/class-of-2029-recruiting-timeline"],["Extern program guides (Nov 17)","https://www.extern.com/post/sophomore-internships-2027-guide"],["Extern (updated Oct 9)","https://www.extern.com/post/investment-banking-internships-2028-guide"],["Trackr (Sep 9)","https://the-trackr.com/blog/us-finance-summer-2028-timeline/"],["Superday AI (Sep 5)","https://www.superdayai.com/blog/summer-2028-ib-recruiting-timeline"]];
let openCat=null,openYr="All",openWho="All";
/* who it's for + internship year: r[8] = "Summer 2027" (juniors) or a program tag (Freshman / Sophomore / Freshman & sophomore); untagged rows are Summer 2028 */
const opWho=r=>{const t=r[8]||"";return t==="Summer 2027"||/^2027\b/.test(r[1])?["Junior"]:t==="Freshman"?["Freshman"]:t==="Freshman & sophomore"?["Freshman","Sophomore"]:["Sophomore"]};
const opYear=r=>{const t=r[8]||"";return t==="Summer 2027"||/^2027\b/.test(r[1])?"Summer 2027":/^(Freshman|Sophomore)/.test(t)?"2027 programs":"Summer 2028"};
const OP_WHO=[["All","Everyone"],["Freshman","Freshmen"],["Sophomore","Sophomores"],["Junior","Juniors"]];
const OP_YEARS=[["All","Any year"],["Summer 2027","Summer 2027 internships"],["Summer 2028","Summer 2028 internships"],["2027 programs","Insight & early programs (2027)"]];
const opLive=(r,t)=>!(r[3]==="open"&&r[6]&&r[6]<t);
function renderOpenings(){const el=$("#openings");if(!el)return;const t=today();if(openCat===null)openCat=(typeof prof==="function"&&prof().openCat)||"All";
  const base=APP_OPEN.filter(r=>opLive(r,t));
  const list=base.filter(r=>(openYr==="All"||opYear(r)===openYr)&&(openWho==="All"||opWho(r).includes(openWho))&&(openCat==="All"||r[2]===openCat||(openCat==="Starred"&&Object.values(S.targets||{}).length&&S.targets[r[0]])));
  const open=list.filter(r=>r[3]==="open").sort((a,b)=>(a[6]||"9999").localeCompare(b[6]||"9999"));
  const exp=list.filter(r=>r[3]!=="open").sort((a,b)=>a[4].localeCompare(b[4]));
  const months={};exp.forEach(r=>{const k=r[4]<t?"due":r[4].slice(0,7);(months[k]=months[k]||[]).push(r)});
  const mLabel=k=>k==="due"?"Expected any day":new Date(k+"-15T12:00:00").toLocaleDateString("en-US",{month:"long",year:"numeric"});
  const added=new Set((S.deadlines||[]).map(d=>d.src).filter(Boolean)),tracked=new Set((S.apps||[]).map(a=>a.f+"|"+a.r));
  const row=r=>{const key=r[0]+"|"+r[1];const n=r[6]?daysUntil(r[6]):null;const inFirms=FIRMS.find(f=>f[0]===r[0]);
    return `<div class="op-row ${r[3]==="open"?"is-open":""}"><div class="op-main"><b>${inFirms?`<button class="flink op-f" data-act="firm|${esc(r[0])}">${esc(r[0])}</button>`:esc(r[0])}</b><span>${esc(r[1])}${r[7]?` · ${esc(r[7])}`:""}</span></div>
      <div class="op-when">${r[3]==="open"?`<span class="op-chip open">Open</span><small>${esc(r[5])}${r[6]?` · closes ${new Date(r[6]+"T12:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric"})}${n!==null&&n>=0?` <em class="${n<=14?"hot":""}">${n}d left</em>`:""}`:""}</small>`:`<span class="op-chip">${esc(r[5])}</span>`}</div>
      <button class="op-add" data-op="${esc(key)}" aria-pressed="${added.has(key)}">${added.has(key)?"✓ On calendar":"+ Calendar"}</button><button class="op-add" data-track="${esc(key)}" aria-pressed="${tracked.has(key)}">${tracked.has(key)?"✓ Tracking":"+ Track"}</button></div>`};
  const cats=["All","IB","Buy side","Markets","Consulting","Other"].filter(c=>c==="All"||APP_OPEN.some(r=>r[2]===c));
  const wc=k=>base.filter(r=>(k==="All"||opWho(r).includes(k))&&(openYr==="All"||opYear(r)===openYr)).length,yc=k=>base.filter(r=>(k==="All"||opYear(r)===k)&&(openWho==="All"||opWho(r).includes(openWho))).length;
  el.innerHTML=`<div class="op-head"><p class="note" style="margin:0">${openWho==="Junior"?"Juniors (class of 2028) recruit for Summer 2027. Most big-bank spots are filled, but firms keep posting into the spring.":openWho==="Sophomore"?"Sophomores (class of 2029) recruit for Summer 2028 now, more than a year ahead, plus sophomore insight programs.":openWho==="Freshman"?"Freshmen: insight days and early programs are the best way in before sophomore recruiting.":"Every class year in one place. Pick who you are and the internship year. Banks open applications on a rolling basis, often more than a year ahead."}</p></div>
   <div class="cats" role="group" aria-label="Who it's for">${OP_WHO.map(([k,l])=>`<button class="chip" data-ow="${k}" aria-pressed="${k===openWho}">${l} <em>${wc(k)}</em></button>`).join("")}</div>
   <div class="cats" role="group" aria-label="Internship year">${OP_YEARS.map(([k,l])=>`<button class="chip" data-oy="${k}" aria-pressed="${k===openYr}">${l} <em>${yc(k)}</em></button>`).join("")}</div>
   <div class="cats" role="group" aria-label="Filter">${cats.map(c=>`<button class="chip" data-oc="${c}" aria-pressed="${c===openCat}">${c}</button>`).join("")}</div>
   ${open.length?`<div class="op-sec"><h3><span class="op-dot"></span>Open now <em>${open.length}</em></h3>${open.map(row).join("")}</div>`:""}
   ${Object.keys(months).sort((a,b)=>a==="due"?-1:b==="due"?1:a.localeCompare(b)).map(k=>`<div class="op-sec"><h3>${mLabel(k)} <em>${months[k].length}</em></h3>${months[k].map(row).join("")}</div>`).join("")}
   <p class="note">"Open" means a confirmed posting. Other dates are estimates based on when each firm opened last cycle, so check the firm's careers page. Updated ${APP_OPEN_DATE}. Sources: ${APP_SRC.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener">${esc(n)}</a>`).join(", ")}.</p>`;
  bindRel(el);
  el.querySelectorAll("[data-oc]").forEach(b=>b.onclick=()=>{openCat=b.dataset.oc;renderOpenings()});
  el.querySelectorAll("[data-oy]").forEach(b=>b.onclick=()=>{openYr=b.dataset.oy;renderOpenings()});
  el.querySelectorAll("[data-ow]").forEach(b=>b.onclick=()=>{openWho=b.dataset.ow;renderOpenings()});
  el.querySelectorAll("[data-track]").forEach(b=>b.onclick=()=>{const key=b.dataset.track;const r=APP_OPEN.find(x=>x[0]+"|"+x[1]===key);if(!r)return;
    if(tracked.has(key)){S.apps=(S.apps||[]).filter(a=>a.f+"|"+a.r!==key);toast("Removed from applications")}
    else{if(!isPro()&&(S.apps||[]).length>=5){upgrade("Track unlimited applications with Pro");return}S.apps=(S.apps||[]).concat({id:"ap"+Date.now(),f:r[0],r:r[1],d:r[6]||(r[3]==="exp"?r[4]:""),stage:"Planning",n:r[3]==="exp"?"Opens "+r[5]:""});toast("Tracking it in Applications")}
    save();renderOpenings();renderApps();renderHome()});
  el.querySelectorAll("[data-op]").forEach(b=>b.onclick=()=>{const key=b.dataset.op;const r=APP_OPEN.find(x=>x[0]+"|"+x[1]===key);if(!r)return;
    if((S.deadlines||[]).some(d=>d.src===key)){S.deadlines=S.deadlines.filter(d=>d.src!==key);toast("Removed from your calendar")}
    else{const isOpen=r[3]==="open";const date=isOpen?(r[6]||today()):r[4];S.deadlines=(S.deadlines||[]).concat({id:"dl"+Date.now(),src:key,t:isOpen?(r[6]?`Apply by: ${r[1]}`:`Apply: ${r[1]}`):`Opens (est.): ${r[1]}`,f:r[0],date,k:"Application"});toast(isOpen?"Added. Apply soon":"Added to your calendar")}
    save();renderOpenings();renderCal();renderHome()})}

/* ---------- 4. AI resume review ---------- */
function renderResume(){const el=$("#resume");if(!el)return;const usedToday=(S.resumeLog||{})[today()]||0,canRun=isPro()||usedToday<1;
  el.innerHTML=`<p class="hint">Upload your resume as a PDF or Word file and it's graded out of 100 against the standard Wall Street template, the way a banking recruiter would. The file is read in your browser and your saved resume stays private to you.</p>
   <label class="pe-drop" id="resDrop"><input type="file" id="resFile" accept=".pdf,.docx,.txt,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" hidden>
     <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M12 18v-6m-3 3 3-3 3 3"/></svg>
     <b id="resDropT">${((S.profile||{}).resume||{}).text?"Replace your resume":"Upload your resume"}</b><small>PDF, Word (.docx) or text · or drop it here</small></label>
   <p class="note" id="resNote" aria-live="polite">${((S.profile||{}).resume||{}).text?"Saved: "+esc(S.profile.resume.name||"Resume"):""}</p>
   <div class="res-top"><label>Applying for<select id="resRole">${["Investment banking internship","Private equity","Hedge fund / equity research","Sales & trading","Restructuring","Consulting internship"].map(o=>`<option ${({ib:"Investment banking internship",pe:"Private equity",hf:"Hedge fund / equity research",rx:"Restructuring",mc:"Consulting internship"})[profKey()]===o?"selected":""}>${o}</option>`).join("")}</select></label></div>
   <details class="res-paste"${((S.profile||{}).resume||{}).text?"":""}><summary class="note" style="cursor:pointer">Can't upload the file? Paste the text instead</summary><textarea id="resTxt" style="min-height:200px;margin-top:8px" placeholder="Paste your resume here…" aria-label="Resume text"></textarea></details>
   <div class="actions"><button class="btn" id="resGo">${((S.profile||{}).resume||{}).text?"Review my saved resume":"Review my resume"}</button><button class="ghost outline" id="resRemake" type="button">✦ Remake it for Wall Street ${typeof proBadge==="function"?proBadge():"(Pro)"}</button><span class="note">${isPro()?"Instant check + unlimited AI reviews.":usedToday?"Instant check is unlimited. Free AI review used today.":"Instant check is unlimited, plus 1 free AI review a day."}</span></div><div id="resOut" aria-live="polite">${S.resumeLast?resumeHTML(S.resumeLast,true):""}</div>`;
  const resLoad=async f=>{const note=$("#resNote");note.textContent="Reading your resume…";
    try{if(!window.maResume)throw new Error("The resume reader didn't load. Refresh and try again.");
      const x=await maResume.readFile(f),t=String(x.text||"").replace(/\u00a0/g," ").trim();
      if(t.split(/\s+/).length<20)throw new Error("Couldn't find much text in that file. Try the Word version, or paste the text.");
      $("#resTxt").value=t.slice(0,15000);S.profile=S.profile||{};S.profile.resume={text:t.slice(0,15000),name:(f.name||"Resume").slice(0,80),at:Date.now()};save();
      $("#resDropT").textContent="Replace your resume";note.textContent="Loaded "+(f.name||"your resume")+". Reviewing it now…";$("#resGo").click()}
    catch(e){note.textContent=e&&e.message||"Couldn't read that file. Try a PDF or Word (.docx), or paste the text."}};
  $("#resFile").addEventListener("change",e=>{const f=e.target.files&&e.target.files[0];e.target.value="";if(f)resLoad(f)});
  {const dz=$("#resDrop");["dragenter","dragover"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add("on")}));["dragleave","drop"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove("on")}));dz.addEventListener("drop",e=>{const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];if(f)resLoad(f)})}
  if(((S.profile||{}).resume||{}).text)$("#resTxt").value=S.profile.resume.text;
  $("#resRemake").onclick=()=>{if(!window.maResumeRemake){toast("Refresh and try again");return}if(!$("#resTxt").value.trim()&&!((S.profile||{}).resume||{}).text){toast("Upload your resume (PDF or Word) first");return}maResumeRemake()};
  $("#resGo").onclick=async()=>{const txt=$("#resTxt").value.trim();if(!txt){toast("Upload your resume (PDF or Word) first");$("#resDrop").focus();return}if(txt.split(/\s+/).length<35){toast("Paste your full resume (at least a few sections)");return}
    /* instant rule-based check first: always works, no AI, no limit */
    const inst=window.maResumeCheck?maResumeCheck(txt,$("#resRole").value):null;
    const showInst=extra=>{if(!inst)return;$("#resOut").innerHTML=`<div class="label">Instant check</div>${resumeHTML(inst)}${extra?`<p class="note" style="margin-top:10px">${extra}</p>`:""}`};
    showInst("");
    if(!canRun&&!isPro()){showInst("You've used today's free AI review, so this is the instant check. Pro adds unlimited AI reviews.");return}
    await samplePromise;if(!SAMPLE){showInst(aiLock("The deeper AI review"));if(!inst)$("#resOut").innerHTML=`<p class="note">${aiLock("AI resume review")}</p>`;return}
    const b=$("#resGo");b.disabled=true;b.textContent="Reviewing…";if(inst)$("#resOut").insertAdjacentHTML("beforeend",`<p class="note" id="resAiNote" style="margin-top:10px">Getting the deeper AI review…</p>`);
    const prompt=`You are ${(typeof prof==="function"&&prof().recruiter)||"a recruiter at a top investment bank"} reviewing a college student's resume for a ${$("#resRole").value} role. Be direct and specific, like a mentor who wants them to get the interview. Banking resumes should be one page, use strong action verbs, quantify results, and lead with education.

Resume:
"""${txt.slice(0,6000)}"""

Grade it out of 100 against the standard Wall Street one-page resume template (Education first, then Experience, Leadership & Activities, Skills & Interests; one page; quantified bullets that start with action verbs). Use exactly these categories and maximums: Header & contact 5, Education 20, Experience & bullets 35, Leadership & activities 10, Skills & interests 10, Format & length 20. For every point you take off, give the reason.

Return ONLY JSON: {"score100": integer 0-100 (the sum of the category scores), "categories": [{"name": category name, "max": its maximum, "got": points earned, "notes": [{"pts": negative number of points lost, "why": short specific reason}]}], "score": integer 1-10, "headline": one-sentence overall verdict, "strengths": [2-3 short strings], "top_fixes": [3 specific, prioritized fixes], "bullets": [up to 3 objects {"original": a weak bullet quoted from the resume, "issue": short reason, "rewrite": stronger version keeping only facts present in the original}], "formatting": [1-3 short formatting notes]}`;
    try{const r=await SAMPLE.json(prompt,{modelTier:"quick"});S.resumeLog=S.resumeLog||{};S.resumeLog[today()]=usedToday+1;S.resumeLast={...r,date:today()};save();$("#resOut").innerHTML=`<div class="label">AI review</div>`+resumeHTML(r)}
    catch(e){const why=e&&["limit","unconfirmed","not_granted","capacity"].includes(e.code)?e.message:e&&(e.code===429||e.code==="rate_limited")?"AI is busy right now. Try again in a minute.":"The AI review didn't go through"+(e&&e.message&&e.message!=="AI request failed"?` (${e.message})`:"")+". Try again in a minute.";
      if(inst){const n=$("#resAiNote");if(n)n.textContent=why+" Your instant check is above.";else showInst(why)}else $("#resOut").innerHTML=`<p class="note">${esc(why)}</p>`}
    finally{if(document.contains(b)){b.disabled=false;b.textContent="Review again"}}}}
function resumeHTML(r,old){const has100=r.score100!=null&&isFinite(+r.score100);const s100=has100?Math.max(0,Math.min(100,Math.round(+r.score100))):null;
  const sc=has100?Math.round(s100/10):Math.max(1,Math.min(10,Math.round(+r.score||0))),col=sc>=8?"var(--good)":sc>=6?"var(--warn)":"var(--bad)";
  const cats=Array.isArray(r.categories)?r.categories.filter(c=>c&&c.name&&+c.max>0):[];
  return `<div class="res-out">${old?`<div class="label">Last review · ${esc(r.date||"")}</div>`:""}<div class="grade"><div class="score" style="border-color:${col};color:${col}"><div>${has100?s100:sc}<small>${has100?"/100":"/10"}</small></div></div><div><h4>${esc(r.headline||"")}</h4>
   ${has100?`<p class="note" style="margin:2px 0 8px">Graded against the standard Wall Street one-page template.</p>`:""}
   <div class="label" style="margin-top:10px">Fix first</div><ol>${(r.top_fixes||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ol>
   ${(r.strengths||[]).length?`<div class="label">Working well</div><ul>${(r.strengths||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}</div></div>
   ${cats.length?`<div class="label" style="margin-top:16px">Score breakdown</div><div class="res-cats">${cats.map(c=>{const g=Math.max(0,Math.min(+c.max,Math.round(+c.got||0))),pc=Math.round(g/c.max*100),cc=pc>=85?"var(--good)":pc>=60?"var(--warn)":"var(--bad)";
     return `<details class="res-cat" ${pc<85?"open":""}><summary><span>${esc(c.name)}</span><span class="res-bar"><i style="width:${pc}%;background:${cc}"></i></span><b>${g}/${c.max}</b></summary><ul>${(c.notes||[]).map(n=>`<li class="${+n.pts<0?"lost":"ok"}">${+n.pts<0?`<b>${Math.round(+n.pts)}</b> `:"✓ "}${esc(n.why||"")}</li>`).join("")||`<li class="ok">✓ Nothing to fix here.</li>`}</ul></details>`}).join("")}</div>`:""}
   ${(r.bullets||[]).length?`<div class="label" style="margin-top:16px">Bullet rewrites</div>${r.bullets.map(b=>`<div class="bul"><p class="was">${esc(b.original)}</p><p class="why2">${esc(b.issue)}</p><p class="now">${esc(b.rewrite)}</p></div>`).join("")}`:""}
   ${(r.formatting||[]).length?`<div class="label" style="margin-top:16px">Formatting</div><ul>${r.formatting.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}</div>`}

/* ---------- email updates (opt-in list) ---------- */
const SUB_TOPICS=[["weekly","Weekly recap","The Wire's top stories, your progress and one interview question"],["features","New features","When new tracks, tools or questions launch"],["recruiting","Recruiting alerts","Big application windows opening (summer analyst, PE on-cycle)"]];
let MYSUB=null,subState="loading",SUBS=[];
const emailOk=e=>/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e||"");
function initSubs(){if(!DB||!myId){subState="off";renderSubUI();return}
  DB.doc("subscribers/"+myId).onSnapshot(d=>{MYSUB=d.exists?d.data():null;subState="on";renderSubUI()},()=>{subState="off";renderSubUI()});
  if(USER&&USER.isOwner&&USER.isOwner())DB.collection("subscribers").limit(2000).onSnapshot(snap=>{SUBS=snap.docs.map(d=>({id:d.id,...d.data()}));renderSubUI()},()=>{})}
async function saveSub(email,topics,src){if(!DB||!myId)return false;email=email.trim().toLowerCase();if(!emailOk(email)){toast("Enter a valid email");return false}
  const now=new Date().toISOString();
  try{await DB.doc("subscribers/"+myId).set({email,topics,consent:true,source:src||"settings",school:S.settings.noSchool?"":(S.profile.school||""),grad:S.profile.grad||"",target:S.profile.target||"",joined:(MYSUB&&MYSUB.joined)||now,updated:now});
    S.subEmail=email;save();return true}catch(e){toast(e&&e.code==="not_granted"?"Email updates are available when you sign in":"Couldn't save. Try again.");return false}}
async function unsub(){if(!DB||!myId)return;try{await DB.doc("subscribers/"+myId).delete();toast("Unsubscribed. You won't get any more emails.")}catch(e){toast("Couldn't unsubscribe. Try again.")}}
function subFormHTML(id,src){const em=(MYSUB&&MYSUB.email)||S.subEmail||"";const on=MYSUB?MYSUB.topics||[]:SUB_TOPICS.map(t=>t[0]);
  return `<form class="sub-form" id="${id}" data-src="${src}" novalidate>
    <div class="sub-row"><input type="email" name="em" placeholder="you@school.edu" value="${esc(em)}" aria-label="Email address" autocomplete="email" required><button class="btn" type="submit">${MYSUB?"Save":"Subscribe"}</button></div>
    <div class="sub-topics" role="group" aria-label="What to send"><span class="sub-lbl">Send me</span>${SUB_TOPICS.map(([k,l,d])=>`<label class="sub-chip" title="${esc(d)}"><input type="checkbox" name="t" value="${k}" ${on.includes(k)?"checked":""}><span>${l}</span></label>`).join("")}</div>
    <p class="sub-fine">No spam. One-click unsubscribe in every email. By subscribing you agree to our <a href="/privacy/" target="_blank" rel="noopener">Privacy Policy</a>.</p></form>`}
function bindSubForm(form){if(!form)return;form.onsubmit=async e=>{e.preventDefault();const em=form.querySelector("[name=em]").value;const topics=[...form.querySelectorAll('[name=t]:checked')].map(x=>x.value);
  if(!topics.length){toast("Pick at least one, or unsubscribe");return}
  const b=form.querySelector("button[type=submit]");b.disabled=true;const ok=await saveSub(em,topics,form.dataset.src);b.disabled=false;
  if(ok){toast(MYSUB?"Email preferences saved":"You're subscribed");if(form.dataset.src==="home"){S.subCardDone=true;save()}}}}
function renderSubUI(){
  // home card
  const hc=$("#subCard");if(hc){const show=subState==="on"&&!MYSUB&&!S.subCardDone&&!S.subCardX&&(totalXP()>=10||Object.keys(S.daily||{}).length>=1);
    hc.hidden=!show;if(show){hc.innerHTML=`<div class="sub-card"><div class="sub-card-t"><div><h3 class="sub-h3">Get M&A in your inbox</h3><p class="sub-p">A short weekly recap, plus a heads-up when recruiting windows open.</p></div><button class="sub-x" id="subX" type="button" aria-label="Dismiss">×</button></div>${subFormHTML("subFormHome","home")}</div>`;
      bindSubForm($("#subFormHome"));$("#subX").onclick=()=>{S.subCardX=true;save();renderSubUI()}}}
  // settings box
  const sb=$("#subBox");if(sb){
    if(subState==="off"){sb.innerHTML=`<p class="note" style="margin:0">Email updates are available when you sign in.</p>`}
    else if(subState==="loading"){sb.innerHTML=`<p class="note" style="margin:0">Loading…</p>`}
    else{sb.innerHTML=`${MYSUB?`<p class="sub-status">Subscribed as <b></b> · since ${new Date(MYSUB.joined).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})}</p>`:""}${subFormHTML("subFormSet","settings")}${MYSUB?`<button class="ghost danger" id="unsubBtn" type="button">Unsubscribe from everything</button>`:""}`;
      const st=sb.querySelector(".sub-status b");if(st)st.textContent=MYSUB.email;bindSubForm($("#subFormSet"));if($("#unsubBtn"))$("#unsubBtn").onclick=unsub}
    const ow=$("#subOwner");if(ow){const owner=USER&&USER.isOwner&&USER.isOwner();ow.hidden=!owner;if(owner){const by=k=>SUBS.filter(s=>(s.topics||[]).includes(k)).length;
      ow.innerHTML=`<div class="sub-h">Your subscriber list (only you see this)</div><div class="sub-stats"><div><b>${SUBS.length}</b><span>subscribers</span></div>${SUB_TOPICS.map(([k,l])=>`<div><b>${by(k)}</b><span>${l.toLowerCase()}</span></div>`).join("")}</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="ghost outline" id="subCsv" type="button">Download CSV</button><button class="ghost outline" id="subCopy" type="button">Copy emails</button></div>
        <p class="note">Import the CSV into Beehiiv, Kit or Mailchimp, or ask Claude to send an update from your Gmail.</p>`;
      $("#subCsv").onclick=async()=>{await dlPromise;const q=v=>'"'+String(v??"").replace(/"/g,'""')+'"';const csv=["email,topics,school,grad,target,source,joined",...SUBS.map(s=>[s.email,(s.topics||[]).join(" "),s.school,s.grad,s.target,s.source,s.joined].map(q).join(","))].join("\n");
        if(!DL){toast("Downloads aren't available");return}try{await DL.save({filename:"ma-subscribers.csv",data:new Blob([csv],{type:"text/csv"})})}catch(e){}};
      $("#subCopy").onclick=()=>{const t=SUBS.map(s=>s.email).join(", ");(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(()=>toast(SUBS.length+" emails copied"),()=>toast("Couldn't copy"))}}}}
}

/* ---------- Case Comp: monthly case, school brackets ---------- */
const CASES=[
 {id:"northwind",type:"LBO",title:"Northwind Coffee: take-private",role:"You're an associate at a mid-market private equity fund.",
  brief:"Northwind Coffee is a profitable regional coffee chain with 320 company-owned stores. Same-store sales grow steadily, but margins have been flat for three years. The public stock has lagged, and the board is open to a sale. Your fund needs a 20%+ IRR over a 5-year hold.",
  data:[["Revenue","$900M"],["EBITDA (margin)","$135M (15%)"],["Revenue growth","6% a year"],["Annual capex","$45M"],["Current enterprise value","$1.35B (10.0x EBITDA)"],["Board's asking price","At least 11.0x EBITDA"],["Debt available","5.5x EBITDA at 8% interest"],["Tax rate","25%"],["Peer exit multiples","9x–11x EBITDA"]],
  ask:"Should the fund bid? If yes, what's the most you'd pay, and what has to go right to hit 20%?",
  opts:["Bid at the asking price","Bid below the asking price","Pass"],
  keys:"At 11x entry ($1.49B) with ~$740M of debt, flat 10x exit, 6% growth and flat margins, EBITDA reaches ~$180M by year 5, exit EV ~$1.8B, and debt paydown is modest (~$150M) because interest eats cash flow. That's roughly 1.6x / ~10% IRR, well short of 20%. Hitting 20% needs some mix of entry near 9x, margin expansion toward 18–20% (store efficiency, pricing, new formats), or a multiple-expansion story you can defend. Strong answers either pass or bid well below ask with a specific operating plan, and name risks like coffee bean costs, labor, leverage at 8%, and consumer slowdown."},
 {id:"helio",type:"M&A",title:"Helio Robotics buys Brightline Sensors",role:"You're an analyst on Helio's advisory team.",
  brief:"Helio Robotics makes warehouse robots. Brightline Sensors makes the vision sensors Helio already buys for many of its robots. Helio's CEO wants to buy Brightline at a 30% premium and asks whether the deal adds to earnings per share, and whether to pay in stock or cash.",
  data:[["Helio net income","$400M"],["Helio shares / price","200M shares at $50 (EPS $2.00, P/E 25x)"],["Helio EBITDA","$700M, no debt today"],["Brightline net income","$60M"],["Brightline EBITDA","$90M, no debt"],["Purchase price","$1.2B (20x earnings)"],["Option A: all stock","Issue 24M Helio shares at $50"],["Option B: all cash","Borrow $1.2B at 6% pre-tax"],["Expected synergies","$40M a year pre-tax, by year 2"],["Tax rate","25%"]],
  ask:"Should Helio do the deal, and should it pay with stock, cash or a mix?",
  opts:["Acquire with stock","Acquire with cash","Acquire with a mix","Don't acquire"],
  keys:"Stock: pro forma NI $460M / 224M shares = $2.05 EPS, ~+2.7% accretive. Cash: after-tax interest = $1.2B × 6% × 75% = $54M, so NI $406M / 200M = $2.03, ~+1.5% accretive. With $30M after-tax synergies: stock ~$2.19 (+9.4%), cash ~$2.18 (+9%). Accretive because Helio's P/E (25x) is above the price paid (20x) and the after-tax cost of debt (4.5%) is below Brightline's earnings yield (5%). Cash adds ~1.5x leverage ($1.2B / $790M combined EBITDA), manageable. Stock shares synergy risk with sellers and avoids leverage; cash keeps upside for Helio holders. Strong answers note accretion isn't value creation: premium (~$280M) vs PV of synergies (~$30M × ~10x = ~$300M) is roughly break-even, plus strategic benefits (supply control, margins) and risks (integration, losing Brightline's other customers, sensor tech shifts)."},
 {id:"granite",type:"Sell-side",title:"Granite Ridge Outdoor: pick the bid",role:"You're an analyst at the bank running the sale.",
  brief:"Granite Ridge makes premium camping gear. The founder owns 100% and wants to sell. After a two-round auction, two final bids are in. The founder cares most about price, but also wants certainty that the deal actually closes.",
  data:[["Revenue / growth","$310M, growing 12% a year"],["EBITDA","$50M"],["Trading comps","9x–12x EBITDA"],["Precedent deals","10x–13x EBITDA"],["DCF range","$560M–$640M"],["Bid A: strategic buyer","$600M all cash. Moderate antitrust risk (6–9 month review)"],["Bid B: PE fund","$560M cash + up to $80M earnout if EBITDA hits $65M in 2 years. Committed financing. Founder may roll 20%"],["Founder's goal","Max value, high certainty"]],
  ask:"Which bid should the founder take, and how would you counter to improve it?",
  opts:["Take Bid A","Take Bid B","Counter both","Keep the process running"],
  keys:"Valuation: comps $450–600M, precedents $500–650M, DCF $560–640M. Bid A ($600M, 12x) is all certain cash but carries antitrust timing/closing risk; ask for a reverse termination fee and a ticking fee. Bid B's headline $640M is really $560M certain; hitting $65M EBITDA in 2 years needs ~14% annual growth, above the current 12%, so the earnout is worth well under $80M (maybe $25–40M risk-adjusted). Rollover lets the founder share in a second sale. Strong answers usually favor A on value with protections, or use A to push B to raise cash or ease the earnout, and they name a concrete counter (e.g. A at $620–630M with a reverse break fee; B at $600M+ cash)."},
 {id:"meridian",type:"Restructuring",title:"Meridian Health Labs: fix the balance sheet",role:"You're an analyst advising Meridian's board.",
  brief:"Meridian runs diagnostic labs. Revenue is shrinking as insurers cut payments, and $300M of unsecured bonds come due in 10 months. Meridian can't refinance them at any reasonable rate. The board needs a plan before cash runs low.",
  data:[["Revenue","$1.1B, down 8% this year"],["EBITDA","$120M"],["Cash","$60M"],["First-lien loan","$500M (secured, due in 4 years)"],["Second-lien loan","$400M (secured, due in 5 years)"],["Unsecured bonds","$300M, due in 10 months"],["Sector valuations","6x–7x EBITDA ($720M–$840M)"]],
  ask:"What should Meridian do, and who ends up owning the company?",
  opts:["Out-of-court exchange","Prepackaged Chapter 11","Amend and extend","Sell the company or assets"],
  keys:"Total debt $1.2B is 10x EBITDA versus a value of ~$720–840M, so equity is likely worthless. Waterfall at ~$780M: first lien $500M recovers 100%, second lien gets the remaining ~$280M of $400M (~70%), and unsecured recovers ~0%. The second lien is the fulcrum security and will likely end up owning the equity. Options: an out-of-court exchange (unsecured bonds into new longer-dated notes or equity) is cheaper and faster but needs very high participation; a prepackaged Chapter 11 can bind holdouts and convert second lien into equity in a few months; amend and extend with the first lien buys time but doesn't fix the $300M maturity. Strong answers size the liquidity runway, pick a path with a fallback, and name risks: customer and insurer confidence, holdouts, and further revenue decline."}
];
const MC_CASES=[
 {id:"brewline",type:"Consulting",title:"Brewline Coffee: profits are falling",role:"You're a consultant hired by Brewline's CEO.",
  brief:"Brewline runs 400 coffee shops. Revenue was flat this year, but operating profit dropped by a third. The CEO wants to know why and what to do about it before next quarter.",
  data:[["Revenue (both years)","$200M"],["Drinks sold (both years)","40M at $5.00 average"],["Operating profit","$30M last year → $20M this year"],["Ingredients (beans, milk, cups)","$60M → $66M"],["Labor","$70M → $76M"],["Rent","$24M → $24M"],["Other costs","$16M → $14M"],["Main competitor","Raised prices about 8% this year"]],
  ask:"Why did profits fall, and what should Brewline do?",
  opts:["Raise prices","Cut labor costs","Renegotiate supplier contracts","Close underperforming stores"],
  keys:"Revenue is flat because price and volume are both flat, so the $10M drop is all costs: ingredients +$6M (from 30% to 33% of revenue, likely bean prices), labor +$6M (35% to 38%, likely wages), other −$2M, rent flat. Strong answers find this quickly, then weigh fixes. A competitor raised prices ~8%, so Brewline likely has room: a 5% increase to $5.25 that loses 3% of volume (38.8M drinks) gives about $203.7M revenue; ingredients scale to about $64M at $1.65 per drink, so profit rises to roughly $25–26M if labor, rent and other stay flat. Pair it with labor scheduling and supplier hedging. Risks: customers switching, further wage pressure, commodity swings."},
 {id:"voltway",type:"Consulting",title:"Voltway Scooters: enter Germany?",role:"You're a consultant advising Voltway's leadership team.",
  brief:"Voltway runs shared electric scooters in U.S. cities and is profitable at home. It wants to expand into Germany's 10 largest cities and asks whether the market is worth entering.",
  data:[["Population, 10 largest cities","12 million"],["Share who use shared scooters","8%"],["Rides per user","3 a month"],["Price per ride","€3"],["Competitors","3 players hold 80% of the market"],["Voltway's realistic share","10% within 3 years"],["Profit per ride after variable costs","€0.90"],["Fixed costs in Germany","€6M a year"],["Upfront investment (fleet, permits)","€15M"]],
  ask:"Should Voltway enter Germany? If so, how?",
  opts:["Enter now at full scale","Enter through a partnership","Pilot one city first","Don't enter"],
  keys:"Market size: 12M × 8% × 3 rides × 12 months × €3 ≈ €104M a year (about 34.6M rides). At 10% share Voltway gets ~3.5M rides and ~€10.4M revenue, so contribution is ~€3.1M (3.46M × €0.90), well below €6M of fixed costs: a loss of roughly €2.9M a year before even recovering the €15M investment. Break-even needs €6M ÷ €0.90 ≈ 6.7M rides, about 19% share, which is hard against three entrenched rivals. Strong answers say don't enter at full scale; options are a one-city pilot to test costs and demand, a partnership, or buying a smaller player. Risks: city regulation and permits, price wars, seasonality."}
];
const ALL_CASES=()=>CASES.concat(MC_CASES);
const CASE_PARTS=[["thesis","Recommendation",25],["valuation","Valuation & math",25],["analysis","Analysis",25],["risks","Risks",15],["communication","Writing",10]];
const caseFor=mk=>{const [y,m]=mk.split("-").map(Number);return CASES[(y*12+m-1)%CASES.length]};
const caseNow=()=>caseFor(monthKey());
const caseCloses=()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth()+1,0,23,59)};
const caseDaysLeft=()=>Math.max(0,Math.ceil((caseCloses()-Date.now())/864e5));
const myCase=()=>(S.cases||{})[monthKey()];
const CASE_REVISIONS=3;
let caseTab="case",casePractice=null;
const ccWords=t=>(t.trim().match(/\S+/g)||[]).length;
function caseStats(){const c=myCase();return c?{m:monthKey(),cid:c.cid,score:c.score,rec:c.rec,thesis:(c.thesis||"").slice(0,160)}:null}
function renderCase(){const box=$("#caseBox");if(!box)return;
  if(!box.dataset.built){box.dataset.built="1";box.innerHTML=`<div id="caseHead"></div><div class="cats" id="caseTabs" role="group" aria-label="Case Comp views"></div><div id="caseMain"></div>`}
  const cs=casePractice?ALL_CASES().find(c=>c.id===casePractice):caseNow();const school=S.settings.noSchool?"":(S.profile.school||"");
  $("#caseHead").innerHTML=casePractice?`<button class="ghost back" id="caseBack">← Back to this month's case</button><div class="label">Practice case · not ranked</div><h2 class="case-title">${esc(cs.title)}</h2>`
   :`<div class="case-top"><div><div class="label">${new Date().toLocaleDateString("en-US",{month:"long"})} Case Comp · ${esc(cs.type)} · closes in ${caseDaysLeft()} day${caseDaysLeft()===1?"":"s"}</div><h2 class="case-title">${esc(cs.title)}</h2>
     <p class="note" style="margin:0">One case a month. Write a short deal memo, get judged on a 100-point rubric, and compete for ${school?`<b class="case-school"></b>`:"your school"}.</p></div>
     ${school?"":`<button class="btn sm" id="caseSchool">Add your school</button>`}</div>`;
  const cse=$("#caseHead .case-school");if(cse)cse.textContent=school;
  if($("#caseSchool"))$("#caseSchool").onclick=editProfile;if($("#caseBack"))$("#caseBack").onclick=()=>{casePractice=null;caseTab="case";renderCase()};
  const tabs=casePractice?[["case","The case"]]:[["case","The case"],["school",school?"My school":"School board"],["schools","School vs school"],["past","Practice cases"]];
  $("#caseTabs").innerHTML=tabs.map(([k,l])=>`<button class="chip" data-ct="${k}" aria-pressed="${k===caseTab}">${esc(l)}</button>`).join("");
  $("#caseTabs").querySelectorAll("[data-ct]").forEach(b=>b.onclick=()=>{caseTab=b.dataset.ct;renderCase()});
  const main=$("#caseMain");
  if(caseTab==="case")main.innerHTML=caseBriefHTML(cs)+`<div id="caseWork"></div>`,renderCaseWork(cs);
  else if(caseTab==="past")main.innerHTML=`<div class="case-past">${(profKey()==="mc"?MC_CASES:profKey()==="all"&&typeof ALL_CASES==="function"?ALL_CASES():CASES).filter(c=>c.id!==caseNow().id).map(c=>{const r=(S.casePractice||{})[c.id];return `<button class="case-pi" data-pc="${c.id}"><span><b>${esc(c.title)}</b><span>${esc(c.type)}${r?` · your best ${r.score}/100`:""}</span></span><span class="arrow" aria-hidden="true">→</span></button>`}).join("")}</div><p class="note">Practice cases are graded the same way but don't count for your school. They use your daily grades (${FREE_GRADES} a day free, unlimited with Pro).</p>`,
    main.querySelectorAll("[data-pc]").forEach(b=>b.onclick=()=>{casePractice=b.dataset.pc;caseTab="case";renderCase()});
  else renderCaseBoards()}
function caseBriefHTML(c){return `<div class="case-brief"><div><p class="case-role">${esc(c.role)}</p><p>${esc(c.brief)}</p><div class="case-ask"><span class="label">The ask</span><b>${esc(c.ask)}</b></div></div>
  <table class="case-data"><tbody>${c.data.map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join("")}</tbody></table></div>`}
function renderCaseWork(c){const w=$("#caseWork");if(!w)return;const practice=!!casePractice;
  const done=practice?(S.casePractice||{})[c.id]:myCase();const d=(S.caseDraft||{})[c.id]||{};
  const revLeft=practice?null:(done?(isPro()?Math.max(0,CASE_REVISIONS-(done.attempts-1)):0):1);
  const form=()=>`<form class="case-form" id="caseForm" novalidate>
    <div class="case-grid"><label><span class="label">Recommendation</span><select name="rec">${c.opts.map(o=>`<option ${d.rec===o?"selected":""}>${esc(o)}</option>`).join("")}</select></label>
    <label><span class="label">Your number</span><input name="val" placeholder="e.g. bid up to 9.5x ($1.28B)" value="${esc(d.val||"")}" maxlength="80"></label></div>
    <label><span class="label">One-line thesis <small>shown on your school's board</small></span><input name="thesis" maxlength="160" placeholder="The one sentence a judge should remember" value="${esc(d.thesis||"")}"></label>
    <label><span class="label">Memo <small id="caseWc">0 / 400 words</small></span><textarea name="memo" rows="12" placeholder="Recommendation, valuation and the math behind it, key reasons, risks and how you'd handle them. Aim for 200–400 words.">${esc(d.memo||"")}</textarea></label>
    <div class="actions" style="margin:0"><button class="btn" type="submit" id="caseSubmit">${practice?"Grade my memo":done?"Submit revision":"Submit to the judges"}</button><span class="note" id="caseNote">${practice?"":done?(isPro()?`${revLeft} revision${revLeft===1?"":"s"} left this month. Your best score counts.`:""):"One official submission per month, free. Pro members can revise up to 3 times."}</span></div>
    <div id="caseOut"></div></form>`;
  w.innerHTML=(done?caseResultHTML(done,practice):"")+(revLeft===0&&!practice?`<div class="upsell"><b>Want another shot?</b><span>Pro members can revise their memo up to ${CASE_REVISIONS} times a month. Your best score counts for your school.</span><div class="actions" style="margin-top:8px"><button class="btn sm" id="caseUp">Start free trial</button></div></div>`:form());
  if($("#caseUp"))$("#caseUp").onclick=()=>startPlan("trial");
  const f=$("#caseForm");if(!f)return;const wc=()=>{const n=ccWords(f.querySelector("[name=memo]").value);$("#caseWc").textContent=`${n} / 400 words`;$("#caseWc").style.color=n>400?"var(--bad)":""};wc();
  f.oninput=()=>{S.caseDraft=S.caseDraft||{};S.caseDraft[c.id]={rec:f.querySelector("[name=rec]").value,val:f.querySelector("[name=val]").value,thesis:f.querySelector("[name=thesis]").value,memo:f.querySelector("[name=memo]").value};wc();clearTimeout(f._t);f._t=setTimeout(save,500)};
  f.onsubmit=e=>{e.preventDefault();submitCase(c,f,practice)}}
function caseResultHTML(r,practice){const col=r.score>=80?"var(--good)":r.score>=60?"var(--warn)":"var(--bad)";
  return `<div class="case-res"><div class="case-score ring" style="color:${col};--rc:${col};--p:${r.score}"><b>${r.score}</b><small>/100</small></div><div class="case-res-b">
    <div class="label">${practice?"Practice score":"Your score this month"}${r.attempts>1?` · best of ${r.attempts}`:""}</div><h4>${esc(r.verdict||"")}</h4>
    <div class="case-parts">${CASE_PARTS.map(([k,l,max],pi)=>{const v=(r.parts||{})[k]||0;return `<div><span>${l}</span><i><em style="width:${Math.round(v/max*100)}%;--d:${pi}"></em></i><b>${v}/${max}</b></div>`}).join("")}</div>
    ${(r.strengths||[]).length?`<div class="label" style="margin-top:12px">What the judges liked</div><ul>${r.strengths.map(s=>`<li>${esc(s)}</li>`).join("")}</ul>`:""}
    ${(r.fixes||[]).length?`<div class="label">What would score higher</div><ul>${r.fixes.map(s=>`<li>${esc(s)}</li>`).join("")}</ul>`:""}
    ${r.judge_q?`<div class="ang"><b>A judge would ask</b>${esc(r.judge_q)}</div>`:""}</div></div>`}
async function submitCase(c,f,practice){const rec=f.querySelector("[name=rec]").value,val=f.querySelector("[name=val]").value.trim(),thesis=f.querySelector("[name=thesis]").value.trim(),memo=f.querySelector("[name=memo]").value.trim();
  const out=$("#caseOut");const n=ccWords(memo);
  if(n<80){out.innerHTML=`<p class="note" style="color:var(--warn)">Write at least 80 words so the judges have something to score.</p>`;return}
  if(n>450){out.innerHTML=`<p class="note" style="color:var(--warn)">Keep it under 400 words. Judges reward tight writing.</p>`;return}
  if(!thesis){out.innerHTML=`<p class="note" style="color:var(--warn)">Add a one-line thesis.</p>`;return}
  if(practice&&!isPro()&&gradesToday()>=FREE_GRADES){out.innerHTML=`<p class="note">You've used today's ${FREE_GRADES} free grades. They reset tomorrow, or go unlimited with Pro.</p>`;return}
  await samplePromise;if(!SAMPLE){out.innerHTML=`<p class="note">${aiLock("AI judging")} Here's what strong memos cover:</p><div class="model">${esc(c.keys)}</div>`;return}
  const btn=$("#caseSubmit");btn.disabled=true;btn.textContent="The judges are reading…";
  const prompt=`You are a panel of judges at an undergraduate investment banking case competition (think senior bankers and PE investors). Score this student's memo strictly and fairly against the rubric. Check their math against the case data. Reward clear, decisive recommendations backed by numbers; penalize vague hedging, math errors, or ignoring the ask. A typical solid student memo scores 55-70; 85+ is exceptional.

CASE: ${c.title} (${c.type})
${c.role}
${c.brief}
DATA: ${c.data.map(([k,v])=>k+": "+v).join("; ")}
THE ASK: ${c.ask}
JUDGES' NOTES (private, don't quote): ${c.keys}

STUDENT SUBMISSION
Recommendation: ${rec}
Their number: ${val||"(none given)"}
Thesis: ${thesis}
Memo: """${memo.slice(0,4000)}"""

RUBRIC: thesis (recommendation clarity and conviction) 0-25; valuation (numbers, math, valuation logic) 0-25; analysis (key drivers, strategic logic, alternatives) 0-25; risks (real risks plus mitigants) 0-15; communication (concise, structured, professional) 0-10.
Return ONLY JSON: {"parts":{"thesis":int,"valuation":int,"analysis":int,"risks":int,"communication":int},"verdict":"one short sentence","strengths":[1-3 short strings],"fixes":[1-3 short, specific strings],"judge_q":"one tough follow-up question a judge would ask this student"}`;
  try{const r=await SAMPLE.json(prompt,{modelTier:"complex"});const parts={};let tot=0;CASE_PARTS.forEach(([k,,max])=>{const v=Math.max(0,Math.min(max,Math.round(+(r.parts||{})[k]||0)));parts[k]=v;tot+=v});
    const res={cid:c.id,score:tot,parts,verdict:r.verdict||"",strengths:(r.strengths||[]).slice(0,3),fixes:(r.fixes||[]).slice(0,3),judge_q:r.judge_q||"",rec,val,thesis,at:Date.now()};
    if(practice){S.casePractice=S.casePractice||{};const prev=S.casePractice[c.id];res.attempts=(prev?prev.attempts:0)+1;S.casePractice[c.id]=prev&&prev.score>tot?{...prev,attempts:res.attempts}:res;bumpGrades()}
    else{S.cases=S.cases||{};const prev=S.cases[monthKey()];res.attempts=(prev?prev.attempts:0)+1;
      S.cases[monthKey()]=prev&&prev.score>tot?{...prev,attempts:res.attempts,last:res}:res;logEvent(`Submitted the ${c.title.split(":")[0]} case (${S.cases[monthKey()].score}/100)`)}
    save();syncSoon();render();checkBadges();renderCaseWork(c);
    if(!practice&&prevBetter(res))toast(`Scored ${tot}. Your best (${myCase().score}) still counts.`);else toast(`Scored ${tot}/100`)}
  catch(e){btn.disabled=false;btn.textContent="Try again";out.innerHTML=`<p class="note">${e&&e.code==="rate_limited"?"The judges are busy. Try again in a minute.":"Couldn't grade right now. Your memo is saved; try again."}</p>`}}
function prevBetter(res){const c=myCase();return c&&c.score>res.score}
function caseEntries(){const mk=monthKey();return PLAYERS.filter(p=>p.cc&&p.cc.m===mk&&typeof p.cc.score==="number").map(p=>({p,score:p.cc.score,school:p.school||"",key:normSchool(p.school||"")}))}
function renderCaseBoards(){const main=$("#caseMain");if(!main||caseTab==="case"||caseTab==="past")return;
  if(dbState==="off"){main.innerHTML=`<p class="note">School boards are available when you sign in. You can still work the case.</p>`;return}
  const all=caseEntries();
  if(caseTab==="school"){const mine=normSchool(S.settings.noSchool?"":(S.profile.school||""));
    if(!mine){main.innerHTML=`<div class="empty-s"><b>Add your school to see your bracket</b><span>Every school gets its own leaderboard each month.</span><button class="btn sm" id="caseSchool2">Add your school</button></div>`;$("#caseSchool2").onclick=editProfile;return}
    const rows=all.filter(e=>e.key===mine).sort((a,b)=>b.score-a.score);
    main.innerHTML=rows.length?`<ol class="case-board">${rows.map((e,i)=>`<li class="${e.p.id===myId?"me":""}"><span class="cb-rank">${i+1}</span><button class="cb-who" data-pid="${esc(e.p.id)}">${avatar(e.p.id,realName(e.p.id),30)}<span><b class="cb-n" data-id="${esc(e.p.id)}"></b><small>${esc(e.p.cc.rec||"")}</small></span></button><span class="cb-th"></span><b class="cb-s">${e.score}</b></li>`).join("")}</ol><p class="note">Top 5 scores count toward your school's ranking. Closes ${caseCloses().toLocaleDateString("en-US",{month:"short",day:"numeric"})}.</p>`
      :`<div class="empty-s"><b>No one from your school has submitted yet</b><span>Be first. Then send the case to your club.</span>${S.club&&S.club.code?"":`<button class="btn sm" id="caseInv">Invite classmates</button>`}</div>`;
    main.querySelectorAll(".case-board li").forEach((li,i)=>{const e=rows[i];li.querySelector(".cb-n").textContent=realName(e.p.id);li.querySelector(".cb-th").textContent=e.p.cc.thesis||""});
    main.querySelectorAll("[data-pid]").forEach(b=>b.onclick=()=>{const p=PLAYERS.find(x=>x.id===b.dataset.pid);if(p)showPlayer(p)});
    if($("#caseInv"))$("#caseInv").onclick=()=>runAct("sub|compete|club");return}
  const g={};all.forEach(e=>{if(!e.key)return;(g[e.key]=g[e.key]||{name:e.school,s:[]}).s.push(e.score)});
  const schools=Object.values(g).map(x=>{const top=x.s.sort((a,b)=>b-a).slice(0,5);return{name:x.name,n:x.s.length,avg:Math.round(top.reduce((a,b)=>a+b,0)/top.length),best:top[0]}}).sort((a,b)=>b.avg-a.avg||b.n-a.n);
  const mine=normSchool(S.profile.school||"");
  main.innerHTML=schools.length?`<table class="case-schools"><thead><tr><th>#</th><th>School</th><th>Entries</th><th>Top score</th><th>School score</th></tr></thead><tbody>${schools.map((x,i)=>`<tr class="${normSchool(x.name)===mine?"me":""}"><td>${i+1}</td><td class="cs-n"></td><td>${x.n}</td><td>${x.best}</td><td><b>${x.avg}</b></td></tr>`).join("")}</tbody></table><p class="note">School score is the average of each school's top 5 memos this month. More entries can only help.</p>`
    :`<p class="note">No schools on the board yet this month. Submit the case to put yours up first.</p>`;
  main.querySelectorAll(".cs-n").forEach((td,i)=>td.textContent=schools[i].name)}

