const PLAN_TO_PROF={"Investment banking":"ib","Private equity":"pe","Hedge funds & markets":"hf","Restructuring":"rx","Consulting":"mc","Equity research":"er"};
const profKey=()=>{const k=S.settings.prof||(S.plan&&PLAN_TO_PROF[S.plan.target])||"all";return PROFS.some(p=>p[0]===k)?k:"all"};
const prof=()=>PROFS.find(p=>p[0]===profKey())[2];
const profSecs=()=>prof().secs||null;
document.addEventListener("click",e=>{if(!e.target.closest||!e.target.closest(".prof-row"))document.querySelectorAll(".prof-menu").forEach(m=>{if(!m.hidden){m.hidden=true;m.previousElementSibling.setAttribute("aria-expanded","false")}})});
function scrollProfRows(){document.querySelectorAll(".prof-row").forEach(row=>{const on=row.querySelector('[aria-selected="true"]');if(on&&row.clientWidth&&row.scrollWidth>row.clientWidth)row.scrollLeft=Math.max(0,on.offsetLeft-row.offsetLeft-60)})}
function setProf(k){S.settings.prof=k;save();mockSec="All";if(mockPack&&!profPacks().includes(mockPack))mockPack="";mockQ=null;const p=prof();firmCat=p.firms?"__path":"All";openCat=p.openCat||"All";OPEN.clear();
  ["renderProf","render","renderCerts","renderDeals","renderCheats","renderMock","renderChal","renderPracticeCases","renderCompete","renderRoad","renderOpenings","renderFirms"].forEach(f=>{try{if(typeof window[f]==="function")window[f]()}catch(e){console.warn(f,e)}});syncSoon();toast(k==="all"?"Showing every career path":`Showing ${PROFS.find(x=>x[0]===k)[1]}`)}
