  const curName=PROFS.find(x=>x[0]===k)[1];
  document.querySelectorAll(".prof-row").forEach(row=>{row.innerHTML=`<button class="prof-pick" type="button" aria-haspopup="true" aria-expanded="false"><span class="prof-l">Path</span><b>${k==="all"?"All paths":curName}</b><span class="prof-car" aria-hidden="true"></span></button><div class="prof-menu" hidden>${PROFS.map(([id,n])=>`<button class="prof-b" type="button" data-prof="${id}" aria-selected="${id===k}">${id==="all"?"All paths":n}${id===k?' <span aria-hidden="true">✓</span>':""}</button>`).join("")}</div>`;
    const pk=row.querySelector(".prof-pick"),mn=row.querySelector(".prof-menu");
    pk.onclick=e=>{e.stopPropagation();const o=mn.hidden;document.querySelectorAll(".prof-menu").forEach(m=>{m.hidden=true;m.previousElementSibling.setAttribute("aria-expanded","false")});mn.hidden=!o;pk.setAttribute("aria-expanded",String(o))};
    row.querySelectorAll("[data-prof]").forEach(b=>b.onclick=()=>{mn.hidden=true;if(b.dataset.prof!==profKey())setProf(b.dataset.prof)});
  });requestAnimationFrame(scrollProfRows);
  document.querySelectorAll("[data-blurb]").forEach(el=>{const v=el.dataset.blurb;el.textContent=v==="practice"?(p.blurb||"Interview reps, speed drills and modeling."):v==="learn"?(PROF_BLURB.learn||{}).all:(PROF_BLURB[v]||{})[k]||(PROF_BLURB[v]||{}).all||el.textContent});
  const lc=$("#ladCta");if(lc){const t=lc.querySelector("b");if(t)t.textContent=k==="mc"?"Career ladder: Intern → Partner":"Career ladder: Intern → MD"}
