/* --- seasons, weekly XP, activity events --- */
function seasonOf(d=new Date()){const m=d.getMonth()+1,y=d.getFullYear();return m>=8?`Fall ${y}`:`Spring ${y}`}
function weekOfKey(k){const [y,w]=k.split("-W").map(Number);const d=new Date(Date.UTC(y,0,4));d.setUTCDate(d.getUTCDate()+(w-1)*7);return d}
const seasonPts=()=>{const s=seasonOf();return Object.entries(S.gauntlet||{}).filter(([k])=>seasonOf(weekOfKey(k))===s).reduce((a,[,g])=>a+(g.score||0),0)};
function weekXP(){const w=isoWeek(),x=totalXP();S.wk=S.wk||{};if(S.wk.week!==w){S.wk={week:w,start:x};save()}return Math.max(0,x-S.wk.start)}
function logEvent(t){S.events=(S.events||[]);if(S.events[0]&&S.events[0].t===t)return;S.events.unshift({t,at:Date.now()});S.events=S.events.slice(0,15);save();syncSoon()}
function checkSeasonRollover(){const cur=seasonOf();if(S.lastSeason&&S.lastSeason!==cur&&S.lastSeasonRank){const r=S.lastSeasonRank,tier=r<=1?"Champion":r<=3?"Top 3":r<=10?"Top 10":r<=25?"Top 25":null;if(tier){S.titles=(S.titles||[]).concat(`${S.lastSeason} Gauntlet ${tier}`);logEvent(`Earned the title ${S.lastSeason} Gauntlet ${tier}`)}}S.lastSeason=cur;save()}
const normSchool=s=>(s||"").toLowerCase().replace(/\b(the|university|of|college|at)\b/g,"").replace(/[^a-z0-9]/g,"");

/* --- profile views (who viewed you) --- */
let VIEWS=[];
function initViews(){if(!DB)return;DB.collection("views").limit(500).onSnapshot(snap=>{VIEWS=snap.docs.map(d=>({id:d.id,...d.data()}));{const f=VIEWS.find(v=>v.id==="_founder");FOUNDER_ID=(f&&f.founder)||null;VIEWS=VIEWS.filter(v=>v.id[0]!=="_");setTimeout(()=>{try{decorateFounder()}catch(e){}},0)}loadNames(VIEWS.map(v=>v.id));if($("#cmpMe"))renderCompete()},()=>{})}
async function recordView(target){if(!DB||!myId||!target||target===myId||target==="me")return;try{const ref=DB.doc("views/"+myId);const cur=(VIEWS.find(v=>v.id===myId)||{}).seen||{};const seen={...cur,[target]:Date.now()};const keys=Object.keys(seen).sort((a,b)=>seen[b]-seen[a]).slice(0,60);const trimmed={};keys.forEach(k=>trimmed[k]=seen[k]);await ref.set({seen:trimmed})}catch(e){}}
function viewersOf(id){const cut=Date.now()-30*864e5;return VIEWS.filter(v=>v.id!==id&&v.seen&&v.seen[id]&&v.seen[id]>cut).sort((a,b)=>b.seen[id]-a.seen[id])}
function openViewers(){const vs=viewersOf(myId);
  openPanel(`<div class="label">Profile analytics ${proBadge()}</div><h2>${vs.length} profile view${vs.length===1?"":"s"} in 30 days</h2>
   ${isPro()?(vs.length?`<div class="mk-list">${vs.map(v=>`<button class="mk-main vrow" data-pid="${esc(v.id)}"><span style="display:flex;gap:10px;align-items:center">${avatar(v.id,realName(v.id),32)}<span><b class="vn" data-id="${esc(v.id)}"></b><small>${ago(v.seen[myId])}</small></span></span><span class="arrow">→</span></button>`).join("")}</div>`:`<p class="note">No views yet. Share your profile card to get noticed.</p>`)
   :`<p class="sub">See exactly who looked at your profile, and when.</p><div class="perf blur" aria-hidden="true">${[1,2,3].map(()=>`<div class="mk-main"><span><b>Someone at a target school</b><small>2h ago</small></span></div>`).join("")}</div><div class="actions"><button class="btn" id="vPro">Unlock with Pro</button></div>`}`);
  panel.querySelectorAll(".vn").forEach(n=>n.textContent=realName(n.dataset.id));
  panel.querySelectorAll(".vrow").forEach(b=>b.onclick=()=>{const p=PLAYERS.find(x=>x.id===b.dataset.pid);if(p)showPlayer(p)});
  if($("#vPro"))$("#vPro").onclick=()=>{closePanel();showTab("pro")}}

/* --- rivals + feed + schools (rendered inside Compete) --- */
function rivalHTML(){const rid=S.profile.rival;if(!rid)return `<div class="rival empty"><div><div class="label">Rival</div><b>Pick a rival</b><span>Open anyone's profile and tap "Set as rival" to get a weekly head-to-head.</span></div></div>`;
  const r=PLAYERS.find(p=>p.id===rid),me=weekXP(),them=r?(r.wk===isoWeek()?(r.wkXP||0):0):0;const lead=me-them;
  return `<div class="rival"><div><div class="label">Rival · this week</div><b>${lead>0?"You're ahead":lead<0?"You're behind":"Dead even"}</b><span class="rv-n"></span></div>
   <div class="h2h"><div><b>${me}</b><span>You</span></div><span class="vs">vs</span><div><b>${them}</b><span class="rv-n2"></span></div></div></div>`}
function feedHTML(){const evs=[];PLAYERS.concat(myId&&!PLAYERS.find(p=>p.id===myId)?[{id:myId,events:S.events||[]}]:[]).forEach(p=>(p.events||[]).forEach(e=>evs.push({id:p.id,...e})));
  const club=S.club&&S.club.code,mine=feedScope==="club"&&club?evs.filter(e=>{const p=PLAYERS.find(x=>x.id===e.id);return e.id===myId||(p&&p.club===club)}):feedScope==="following"?evs.filter(e=>(S.profile.follows||[]).includes(e.id)||e.id===myId):evs;
  const list=mine.sort((a,b)=>b.at-a.at).slice(0,20);
  return `<div class="feed-head"><h2>Activity</h2><div class="cats">${[["all","Everyone"],["following","Following"],["club","My club"]].map(([k,l])=>`<button class="chip" data-fs="${k}" aria-pressed="${feedScope===k}">${l}</button>`).join("")}</div></div>
   ${list.length?`<ol class="feed">${list.map(e=>`<li><button class="feed-i" data-pid="${esc(e.id)}">${avatar(e.id,realName(e.id),28)}<span><b class="fn" data-id="${esc(e.id)}"></b> ${esc(e.t.charAt(0).toLowerCase()+e.t.slice(1))}<small>${ago(e.at)}</small></span></button></li>`).join("")}</ol>`:`<p class="note">${feedScope==="following"?"Follow people to see what they're up to.":feedScope==="club"?"Join a club to see your club's activity.":"Nothing yet. Clear a track or play the Gauntlet to show up here."}</p>`}`}
let feedScope="all";
function schoolsHTML(){const g={};PLAYERS.forEach(p=>{const k=normSchool(p.school);if(!k)return;g[k]=g[k]||{name:p.school,n:0,xp:0,season:0};g[k].n++;g[k].xp+=p.xp||0;g[k].season+=p.season===seasonOf()?(p.seasonPts||0):0});
  const rows=Object.values(g).sort((a,b)=>b.xp-a.xp).slice(0,15);const mine=normSchool(S.profile.school);
  return rows.length?`<ol class="board">${rows.map((r,i)=>`<li><div class="brow ${normSchool(r.name)===mine?'me':''}" style="cursor:default"><span class="pos">${i+1}</span><span class="li-logo" style="--h:${hueOf(r.name)};width:32px;height:32px;font-size:11px">${esc(initials(r.name))}</span><span class="who"><span>${esc(r.name)}</span><small>${r.n} player${r.n===1?"":"s"} · ${r.season} season pts</small></span><span class="val">${r.xp.toLocaleString()} XP</span></div></li>`).join("")}</ol>`:`<p class="note">Schools appear once players add one to their profile.</p>`}

/* --- shareable profile card --- */
let DL=null;const dlPromise=capUse("downloads").then(d=>DL=d);
function drawCard(cv){const c=cv.getContext("2d"),W=1080,H=1350;cv.width=W;cv.height=H;const me=myStats(),h=hueOf(myId||"me");
  const g=c.createLinearGradient(0,0,W,H);g.addColorStop(0,`hsl(${h},35%,14%)`);g.addColorStop(1,`hsl(${h+40},40%,26%)`);c.fillStyle=g;c.fillRect(0,0,W,H);
  c.strokeStyle="rgba(255,255,255,.06)";for(let x=0;x<W;x+=72){c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.stroke()}for(let y=0;y<H;y+=72){c.beginPath();c.moveTo(0,y);c.lineTo(W,y);c.stroke()}
  c.fillStyle="#fff";c.font="800 64px Archivo, Arial";c.fillText("M&A",80,140);c.fillStyle="#F5C451";c.font="600 26px 'IBM Plex Mono', monospace";c.fillText(seasonOf().toUpperCase(),80,190);
  c.fillStyle=`hsl(${h},40%,48%)`;c.beginPath();c.arc(160,350,80,0,7);c.fill();c.fillStyle="#fff";c.font="600 64px 'IBM Plex Sans', Arial";c.textAlign="center";c.fillText(initials(myName||"You"),160,372);c.textAlign="left";
  c.font="700 60px 'IBM Plex Sans', Arial";c.fillText((myName||"M&A member").slice(0,22),280,340);c.font="400 32px 'IBM Plex Sans', Arial";c.fillStyle="rgba(255,255,255,.75)";c.fillText([RANKS[me.rank][0],S.settings.noSchool?"":S.profile.school].filter(Boolean).join(" · ").slice(0,40),280,392);
  const ranked=PLAYERS.map(p=>p.xp||0).sort((a,b)=>b-a),pos=ranked.findIndex(v=>v<=me.xp),pct=PLAYERS.length>3&&pos>=0?Math.max(1,Math.round((pos+1)/PLAYERS.length*100)):null;
  const tiles=[[me.xp.toLocaleString(),"XP"],[pct?`Top ${pct}%`:"#"+((pos>=0?pos:0)+1),"Overall"],[me.mockN?me.mockAvg.toFixed(1):"–","Interview avg"],[String(me.levels),"Levels cleared"],[String(seasonPts()),"Season pts"],[String(me.streak),"Day streak"]];
  tiles.forEach(([v,l],i)=>{const x=80+(i%2)*470,y=500+Math.floor(i/2)*190;c.fillStyle="rgba(255,255,255,.08)";c.beginPath();c.roundRect(x,y,440,160,24);c.fill();c.fillStyle="#fff";c.font="700 64px 'IBM Plex Sans', Arial";c.fillText(v,x+36,y+92);c.fillStyle="rgba(255,255,255,.7)";c.font="400 26px 'IBM Plex Sans', Arial";c.fillText(l,x+36,y+132)});
  const certs=Object.keys(S.certs||{}).map(t=>T(t)&&T(t).name);c.fillStyle="#F5C451";c.font="600 28px 'IBM Plex Mono', monospace";
  const line=(certs.length?"CERTIFIED: "+certs.join(" · "):`${Object.keys(S.badges||{}).length} BADGES EARNED`).slice(0,52);c.fillText(line,80,1130);
  c.fillStyle="rgba(255,255,255,.6)";c.font="400 26px 'IBM Plex Sans', Arial";c.fillText("Train for IB, PE and markets · Compete on M&A",80,1250)}
function openShare(){openPanel(`<div class="label">Share</div><h2>Your profile card</h2><p class="sub">Post it to LinkedIn, Instagram or TikTok. Your stats are pulled live.</p>
   <canvas id="shareCv" class="share-cv" aria-label="Profile card image"></canvas>
   <div class="actions"><button class="btn" id="shSave">Save image</button><button class="ghost outline" id="shCopy">Copy caption</button></div><p class="note" id="shNote"></p>`);
  panel.classList.add("wide");const cv=$("#shareCv");(document.fonts?document.fonts.ready:Promise.resolve()).then(()=>drawCard(cv));
  const me=myStats(),cap=`${RANKS[me.rank][0]} on M&A · ${me.xp} XP${me.mockN?` · ${me.mockAvg.toFixed(1)}/10 interview avg`:""}${Object.keys(S.certs||{}).length?` · Certified in ${Object.keys(S.certs).map(t=>T(t).name).join(", ")}`:""}. Training for high finance recruiting: ${SITE_URL}`;
  $("#shCopy").onclick=async()=>{try{await navigator.clipboard.writeText(cap);toast("Caption copied")}catch(e){$("#shNote").textContent=cap}};
  $("#shSave").onclick=async()=>{await dlPromise;if(!DL){$("#shNote").textContent="Saving images isn't available. You can also screenshot the card.";return}
    cv.toBlob(async b=>{try{await DL.save({filename:"ma-profile-card.png",data:b});logEvent("Shared their profile card")}catch(e){$("#shNote").textContent=e&&e.code==="cancelled"?"":"Couldn't save. Try a screenshot instead."}},"image/png")};
}

/* --- certification exams (Pro) --- */
function certStatus(t){const tr=T(t);return{done:clearedCount(t)===tr.levels.length,cert:(S.certs||{})[t]}}
function renderCerts(){const el=$("#certs");if(!el)return;
  el.innerHTML=`<div class="sec-head"><h2>Certifications ${proBadge()}</h2><span class="pill">${Object.keys(S.certs||{}).length}/${ORDER.length} earned</span></div>
   <p class="hint">Finish a track, then pass a timed 10-question exam with 80% or better. No explanations until the end, no going back. Certificates show on your profile and share card.</p>
   <div class="cert-grid">${((typeof prof==="function"&&prof().learnTracks)||ORDER).map(t=>{const tr=T(t),st=certStatus(t);return `<div class="cert ${st.cert?'got':''}"><b>${tr.name}</b><span>${st.cert?`Certified ${new Date(st.cert.date+"T12:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric"})} · ${st.cert.score}/10`:st.done?"Ready for the exam":`${clearedCount(t)}/${tr.levels.length} levels to unlock`}</span>${st.cert?"":`<button class="${st.done?'btn sm':'ghost'}" data-cert="${t}" ${st.done?"":"disabled"}>${st.done?(isPro()?"Take exam":"Unlock with Pro"):"Locked"}</button>`}</div>`}).join("")}</div>`;
  el.querySelectorAll("[data-cert]").forEach(b=>b.onclick=()=>isPro()?runCert(b.dataset.cert):upgrade("Certification exams are part of Pro"))}
function runCert(t){const tr=T(t),pool=tr.levels.flatMap(l=>l.q).slice().sort(()=>Math.random()-.5).slice(0,10).map(shuffleOpts);const ans=[];const t0=Date.now(),LIMIT=600;
  const draw=()=>{const n=ans.length,q=pool[n];panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="q-meta"><span class="label">${tr.name} certification · ${n+1}/10</span><span class="timer" id="ceT"></span></div><div class="dots">${pool.map((_,i)=>`<i class="${i<n?'cur':''}"></i>`).join("")}</div><div class="q" style="margin-top:14px">${q.q}</div><div class="opts">${q.o.map((o,j)=>`<button class="opt" data-k="${j}"><span class="k">${"ABCD"[j]}</span><span>${o}</span></button>`).join("")}</div>`;
    panel.querySelector(".close").onclick=()=>{clearInterval(timerH);closePanel();toast("Exam abandoned. You can retake it anytime.")};panel.querySelector(".opt").focus();
    panel.querySelectorAll(".opt").forEach(b=>b.onclick=()=>{ans.push(+b.dataset.k===q.a);if(ans.length<10)draw();else fin()})};
  const fin=()=>{clearInterval(timerH);const sc=ans.filter(Boolean).length,pass=sc>=8,secs=Math.round((Date.now()-t0)/1000);
    if(pass){S.certs=S.certs||{};S.certs[t]={date:today(),score:sc};save();logEvent(`Earned the ${tr.name} certification`);syncSoon();render()}
    panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="result"><div class="label">${tr.name} certification</div><h2 style="font-size:40px;margin:8px 0">${sc}/10</h2><p>${pass?"Passed. It's on your profile now.":"Not quite. You need 8/10. Review the track and retake it anytime."}</p>
      <div style="text-align:left;margin-top:14px">${pool.map((q,i)=>`<div class="why" style="border-left-color:${ans[i]?'var(--good)':'var(--bad)'}"><b>${ans[i]?"✓":"✗"} ${q.q}</b><br>${q.o[q.a]}. ${q.w}</div>`).join("")}</div>
      <div class="actions">${pass?'<button class="btn" id="ceShare">Share your card</button>':`<button class="btn" id="ceRetry">Retake</button>`}<button class="ghost" id="ceDone">Done</button></div></div>`;bindClose();
    if($("#ceShare"))$("#ceShare").onclick=openShare;if($("#ceRetry"))$("#ceRetry").onclick=()=>runCert(t);$("#ceDone").onclick=closePanel;renderCerts()};
  openPanel("");panel.classList.add("wide");timerH=setInterval(()=>{const e=$("#ceT");const left=LIMIT-Math.round((Date.now()-t0)/1000);if(e){e.textContent=fmtSec(Math.max(0,left));e.classList.toggle("low",left<=60)}if(left<=0){while(ans.length<10)ans.push(false);fin()}},500);draw()}

/* --- daily briefing (free) + adaptive weekly focus (Pro) on Home --- */
function renderBriefing(){const el=$("#briefing");if(!el)return;const top=NEWS.slice(0,3);if(!top.length){el.innerHTML="";return}
  el.innerHTML=`<div class="brief-card"><div class="bc-top"><span class="label">Today's briefing</span><button class="flink" data-act="news">All news →</button></div>
   <ol class="bc-list compact">${top.map(n=>`<li><button class="bc-h" data-act="news">${esc(n.h)}</button></li>`).join("")}</ol></div>`;bindRel(el)}
function focusTasks(){const t=[];const due=dueReviews().length;if(due)t.push([`Clear ${due} review question${due===1?"":"s"}`,"review","Spaced repetition locks in what you missed."]);
  const stats=MOCK_SECTIONS.map(sec=>{const sc=MOCK_QS.filter(q=>q.c===sec&&!q.f).map(q=>S.mockBest[q.id]).filter(Boolean);return{sec,n:sc.length,avg:sc.length?sc.reduce((a,b)=>a+b,0)/sc.length:0}});
  const weak=stats.filter(s=>s.n).sort((a,b)=>a.avg-b.avg)[0],untried=stats.find(s=>!s.n);
  if(weak&&weak.avg<7)t.push([`Raise your ${weak.sec} score (${weak.avg.toFixed(1)}/10)`,`int|${weak.sec}|2`,"Your weakest interview section."]);else if(untried)t.push([`Try your first ${untried.sec} question`,`int|${untried.sec}`,"You haven't been graded here yet."]);
  const lows=[];for(const tr of TRACKS)tr.levels.forEach((L,i)=>{if((S.best[lid(tr.id,i)]||0)===2)lows.push([tr,i])});if(lows.length){const [tr,i]=lows[0];t.push([`Perfect "${tr.levels[i].n}" (2/3 now)`,`lvl|${tr.id}|${i}`,"Stars count toward badges and XP."])}
  const nx=nextPlanLevel();if(nx)t.push([`Next level: ${nx.tr.levels[nx.i].n}`,`lvl|${nx.tr.id}|${nx.i}`,"Keeps your plan on pace."]);
  const chal=CHAL.find(c=>!(S.models||{})[c.id]&&(!c.pro||isPro()));if(chal)t.push([`Solve "${chal.t}"`,`chal|${chal.id}`,"Modeling is tested in every superday."]);
  if(!S.gauntlet[isoWeek()])t.push(["Play this week's Gauntlet","gauntlet","Season points count toward your title."]);
  return t.slice(0,5)}
function renderFocus(){const el=$("#focus");if(!el)return;const pro=isPro(),tasks=focusTasks();el.hidden=!pro;if($("#homeLinks"))$("#homeLinks").hidden=pro||!!(S.settings.homeHide||{}).links;if(!pro){el.innerHTML="";return}
  el.innerHTML=`<div class="focus-card"><div class="bc-top"><span class="label">Your weekly plan ${proBadge()}</span><span class="note">Rebuilt from your weak spots</span></div>
   <ol class="focus-list ${pro?'':'blur'}" aria-hidden="${!pro}">${tasks.map(([l,a,w])=>`<li><button class="fi" data-act="${esc(a)}"><span><b>${esc(l)}</b><small>${esc(w)}</small></span><span class="arrow">→</span></button></li>`).join("")||"<li class='note'>You're all caught up.</li>"}</ol>
   ${pro?"":`<button class="btn sm" id="focusPro" style="margin-top:10px">Get a plan that adapts to you</button>`}</div>`;
  if(pro)bindRel(el);else $("#focusPro").onclick=()=>showTab("pro")}

/* --- application tracker (free up to 5, Pro unlimited) --- */
const STAGES=["Planning","Applied","Online test","First round","Superday","Offer","Rejected"];
function renderApps(){const el=$("#apps");if(!el)return;const apps=S.apps||[],lim=isPro()?Infinity:5;
  const counts=STAGES.map(s=>apps.filter(a=>a.stage===s).length);
  el.innerHTML=`<div class="sec-head"><h2>Applications</h2><span class="pill">${apps.length}${isPro()?"":"/5 free"}</span></div>
   <div class="pipe">${STAGES.map((s,i)=>`<div class="${counts[i]?'on':''} ${s==="Offer"?'ok':''} ${s==="Rejected"?'no':''}"><b>${counts[i]}</b><span>${s}</span></div>`).join("")}</div>
   <div class="ap-quick"><input id="apQ" list="apOpts" autocomplete="off" placeholder="Type a firm or program, then press Enter" aria-label="Add an application"><datalist id="apOpts">${[...new Set((typeof APP_OPEN!=="undefined"?APP_OPEN:[]).map(r=>r[0]+" — "+r[1]).concat(FIRMS.map(f=>f[0])))].map(v=>`<option value="${esc(v)}">`).join("")}</datalist>
     <select id="apQS" aria-label="Stage">${STAGES.map(s=>`<option${s==="Applied"?" selected":""}>${s}</option>`).join("")}</select><button class="btn sm" id="apQGo" type="button">Add</button></div>
   <button class="ghost" id="apAdd" style="padding-left:0">+ Add with more details</button>
   <form id="apForm" class="crm-form" hidden autocomplete="off"><label>Firm<input id="apF" required list="apFirms"></label><datalist id="apFirms">${FIRMS.map(f=>`<option value="${esc(f[0])}">`).join("")}</datalist><label>Role<input id="apR" placeholder="Summer analyst, M&A"></label><label>Deadline<input type="date" id="apD"></label><label>Stage<select id="apS">${STAGES.map(s=>`<option>${s}</option>`).join("")}</select></label><label class="wide" style="grid-column:1/-1">Notes<input id="apN" placeholder="Referral from…, recruiter name, next step"></label><label>&nbsp;<button class="btn sm" type="submit" id="apSave">Save</button></label></form>
   ${apps.length?`<div class="tbl-wrap"><table class="crm"><thead><tr><th>Firm</th><th>Role</th><th>Stage</th><th>Deadline</th><th>Notes</th><th></th></tr></thead><tbody>${apps.slice().sort((a,b)=>(a.d||"9999").localeCompare(b.d||"9999")).map(a=>{const n=a.d?daysUntil(a.d):null;return `<tr><td><b>${esc(a.f)}</b></td><td>${esc(a.r)}</td><td class="nw"><select class="apStage" data-id="${esc(a.id)}" aria-label="Stage">${STAGES.map(s=>`<option ${s===a.stage?"selected":""}>${s}</option>`).join("")}</select></td><td class="nw">${a.d?esc(a.d):"–"}${n!==null&&n>=0&&n<=7&&!["Offer","Rejected"].includes(a.stage)?` <span class="pill warn">${n===0?"today":n+"d"}</span>`:""}</td><td>${esc(a.n)}</td><td class="nw"><button class="rowbtn" data-apdel="${esc(a.id)}">Remove</button></td></tr>`}).join("")}</tbody></table></div>`:`<p class="note">Track every application from planning to offer. Deadlines within a week show up on Home.</p>`}`;
  {const q=$("#apQ"),go=()=>{const v=q.value.trim();if(!v){q.focus();return}if(apps.length>=lim){upgrade("Track unlimited applications with Pro");return}
      const [f0,p0]=v.split(/\s+—\s+/);const row=(typeof APP_OPEN!=="undefined"?APP_OPEN:[]).find(r=>r[0]===f0&&(!p0||r[1]===p0))||null;
      const f=row?row[0]:(FIRMS.find(x=>x[0].toLowerCase()===f0.toLowerCase())||[f0])[0];
      if((S.apps||[]).some(a=>a.f===f&&a.r===(row?row[1]:(p0||"")))){toast("Already tracking that");return}
      S.apps=(S.apps||[]).concat({id:"ap"+Date.now(),f,r:row?row[1]:(p0||""),d:row?(row[6]||(row[3]==="exp"?row[4]:"")):"",stage:$("#apQS").value,n:row&&row[3]==="exp"?"Opens "+row[5]:""});save();renderApps();renderHome();toast(`Added ${f}`);setTimeout(()=>{const n=$("#apQ");if(n)n.focus()},0)};
    q.onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();go()}};$("#apQGo").onclick=go}
  $("#apAdd").onclick=()=>{if(apps.length>=lim){upgrade("Track unlimited applications with Pro");return}$("#apForm").hidden=!$("#apForm").hidden;if(!$("#apForm").hidden)$("#apF").focus()};
  $("#apForm").onsubmit=e=>{e.preventDefault();S.apps=(S.apps||[]).concat({id:"ap"+Date.now(),f:$("#apF").value.trim(),r:$("#apR").value.trim(),d:$("#apD").value,stage:$("#apS").value,n:$("#apN").value.trim()});save();renderApps();renderHome();toast("Application added")};
  el.querySelectorAll(".apStage").forEach(s=>s.onchange=()=>{const a=S.apps.find(x=>x.id===s.dataset.id);const prev=a.stage;a.stage=s.value;save();if(["Superday","Offer"].includes(s.value)&&prev!==s.value)logEvent(s.value==="Offer"?`Got an offer from ${a.f}`:`Landed a superday at ${a.f}`);renderApps();renderHome()});
  el.querySelectorAll("[data-apdel]").forEach(b=>b.onclick=()=>{S.apps=S.apps.filter(a=>a.id!==b.dataset.apdel);save();renderApps();renderHome()})}

/* --- networking email drafts (1 free/day, Pro unlimited) --- */
function draftEmail(c){const used=(S.drafts||{})[today()]||0;
  openPanel(`<div class="label">Email draft · ${esc(c.name)}${c.firm?" · "+esc(c.firm):""}</div><h2>Draft an email</h2>
   <div class="seg" role="group" aria-label="Email type" id="emType">${[["intro","Cold intro"],["follow","Follow-up"],["thanks","Thank-you"],["referral","Ask for referral"]].map(([k,l],i)=>`<button data-em="${k}" aria-pressed="${i===0}">${l}</button>`).join("")}</div>
   <label class="note" style="display:block;margin-top:12px">Anything to mention?<input id="emExtra" placeholder="e.g. we talked about their restructuring group"></label>
   <div class="actions"><button class="btn" id="emGo">Write it</button><span class="note">${isPro()?"Unlimited with Pro.":used?"Free draft used today.":"1 free draft a day."}</span></div><div id="emOut"></div>`);
  let type="intro";panel.querySelectorAll("[data-em]").forEach(b=>b.onclick=()=>{type=b.dataset.em;panel.querySelectorAll("[data-em]").forEach(x=>x.setAttribute("aria-pressed",x===b))});
  $("#emGo").onclick=async()=>{if(!isPro()&&used>=1){upgrade("Unlimited email drafts are part of Pro");return}const b=$("#emGo");const pr=S.profile;
    try{const r=MA_SF.email(type,{...c,extra:$("#emExtra").value},{name:myName,school:pr.school,grad:pr.grad,major:pr.major,target:pr.target});S.drafts=S.drafts||{};S.drafts[today()]=used+1;save();
      $("#emOut").innerHTML=`<label class="note" style="display:block;margin-top:14px">Subject<input id="emSub" value="${esc(r.subject||"")}"></label><label class="note" style="display:block;margin-top:8px">Body<textarea id="emBody" style="min-height:200px">${esc(r.body||"")}</textarea></label><div class="actions"><button class="btn sm" id="emCopy">Copy email</button><button class="ghost" id="emLog">Log as emailed</button></div>`;
      $("#emCopy").onclick=async()=>{try{await navigator.clipboard.writeText(`Subject: ${$("#emSub").value}\n\n${$("#emBody").value}`);toast("Email copied")}catch(e){$("#emBody").select()}};
      $("#emLog").onclick=()=>{const x=S.contacts.find(y=>y.id===c.id);if(x){x.status=type==="thanks"?"Chatted":"Emailed";x.last=today();x.next=addDays(type==="intro"?7:5);delete x.ex;save();renderCRM()}toast("Contact updated");closePanel()}}
    catch(e){$("#emOut").innerHTML=`<p class="note">Couldn't write it right now. Try again.</p>`}finally{if(document.contains(b)){b.disabled=false;b.textContent="Write again"}}}}

/* --- speak-it delivery stats (Pro) --- */
const FILLERS=["um","uh","like","you know","basically","so yeah","kind of","sort of","i mean","actually","literally"];
function deliveryStats(text,secs){const t=" "+text.toLowerCase().replace(/[^a-z' ]/g," ")+" ";const words=text.trim().split(/\s+/).filter(Boolean).length;const f={};FILLERS.forEach(w=>{const n=(t.match(new RegExp(" "+w.replace(" ","\\s+")+" ","g"))||[]).length;if(n)f[w]=n});
  const fillers=Object.values(f).reduce((a,b)=>a+b,0),wpm=secs>5?Math.round(words/(secs/60)):null;return{words,secs,wpm,fillers,f}}
function deliveryHTML(d){const pace=d.wpm===null?"–":d.wpm<110?"Slow":d.wpm>170?"Fast":"Good";
  return `<div class="deliv"><div class="label">Delivery ${proBadge()}</div><div class="me-stats" style="grid-template-columns:repeat(4,1fr)"><div><b>${d.wpm??"–"}</b><span>words / min · ${pace}</span></div><div><b>${d.fillers}</b><span>filler words</span></div><div><b>${fmtSec(d.secs)}</b><span>length</span></div><div><b>${d.words}</b><span>words</span></div></div>
   ${d.fillers?`<p class="note">Most used: ${Object.entries(d.f).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([w,n])=>`"${w}" ×${n}`).join(", ")}. Aim for 130–160 words a minute and almost no fillers.</p>`:`<p class="note">Clean delivery. Aim for 130–160 words a minute.</p>`}</div>`}

/* ---------- connective tissue: cross-links, palette, transitions ---------- */
const LEVEL_SEC={f:["Accounting","Accounting","Enterprise Value","Valuation & DCF","M&A"],ib:["Behavioral","Behavioral","Behavioral","Valuation & DCF","Behavioral"],pe:["LBO & PE","LBO & PE","LBO & PE","LBO & PE","LBO & PE"],pm:["Markets & Hedge Funds","Markets & Hedge Funds","Markets & Hedge Funds","Markets & Hedge Funds"],rx:["Restructuring","Restructuring","Restructuring","Restructuring"],b:["Behavioral","Behavioral","Behavioral","Behavioral"],x:[null,null,null]};
const SEC_LEVEL={"Accounting":["f",1],"Enterprise Value":["f",2],"Valuation & DCF":["f",3],"M&A":["f",4],"LBO & PE":["pe",1],"Markets & Hedge Funds":["pm",2],"Restructuring":["rx",1],"Behavioral":["b",2]};
const LEVEL_TOOL={"f-3":"dcf","pe-1":"lbo","pe-2":"lbo","pe-3":"lbo"};
const NEWS_SEC={Markets:"Markets & Hedge Funds",Economy:"Markets & Hedge Funds",Deals:"M&A",Banks:"M&A",PE:"LBO & PE"};
const TYPE_SEC={"Bulge bracket":"M&A","Elite boutique":"M&A","Middle market":"M&A","Private equity":"LBO & PE","Hedge fund":"Markets & Hedge Funds"};
function findLevel(q){for(const tr of TRACKS)for(let i=0;i<tr.levels.length;i++)if(tr.levels[i].q.includes(q))return{tr,i};return null}
function goInterview(sec,diff){closeAll();mockSec=sec||"All";mockDiff=diff||0;mockQ=null;showTab("interview");renderMock()}
function goLevel(tid,i){closeAll();const tr=T(tid);showTab("train");OPEN.add(tid);render();
  if(levelOpen(tr,i))showBrief(tr,i);else{const d=document.querySelector(`details.track[data-tr="${tid}"]`);if(d)d.scrollIntoView({block:"center"});toast(trackUnlocked(tr)?"Clear the earlier levels in this track first":tr.req.why)}}
function goTool(name){closeAll();showTab("practice");showSub("practice",name)}
function goFirm(name){toggleWire(false,true);showFirm(name)}
function closeAll(){if(!ov.hidden)closePanel();if(!$("#wire").hidden)toggleWire(false,true);closePalette(true)}
const linkRow=items=>items.length?`<div class="related"><span class="label">Keep going</span>${items.map(([l,act])=>`<button class="rel" data-act="${esc(act)}">${l} <span aria-hidden="true">→</span></button>`).join("")}</div>`:"";
function bindRel(root){(root||document).querySelectorAll("[data-act]").forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();runAct(b.dataset.act)})}
function runAct(a){const [k,...rest]=a.split("|");
  if(k==="url"){const u=rest.join("|");if(/^\/[a-z0-9\-\/]*$/i.test(u))location.href=u;return}
  if(k==="int")goInterview(rest[0],+rest[1]||0);else if(k==="lvl")goLevel(rest[0],+rest[1]);else if(k==="tool")goTool(rest[0]);else if(k==="firm")goFirm(rest[0]);
  else if(k==="tab"){closeAll();showTab(rest[0])}else if(k==="news"){closeAll();toggleWire(true)}else if(k==="gauntlet"){closeAll();showTab("compete");showSub("compete","overview")}
  else if(k==="rapid"){closeAll();showTab("practice");showSub("practice","rapid");setTimeout(()=>$("#rfBtn").click(),50)}else if(k==="profile"){closeAll();showPlayer({id:myId||"me",...myStats()})}
  else if(k==="edit"){closeAll();editProfile()}else if(k==="set"){closeAll();showTab("settings")}else if(k==="track"){closeAll();showTab("train");OPEN.add(rest[0]);render();const d=document.querySelector(`details.track[data-tr="${rest[0]}"]`);if(d)d.scrollIntoView({block:"center"})}
  else if(k==="badges"){closeAll();openBadges()}
  else if(k==="share"){closeAll();openShare()}else if(k==="views"){closeAll();openViewers()}
  else if(k==="ladder"){closeAll();openLadder(rest[0]&&rest[0]!=="x"?rest[0]:"you")}
  else if(k==="subs"){closeAll();showTab("settings");setTimeout(()=>{const g=$("#sg-email");if(g)g.scrollIntoView({block:"start"})},80)}
  else if(k==="certs"){closeAll();showTab("learn");showSub("learn","certs")}
  else if(k==="pack"){closeAll();if(!isPro()){upgrade("Firm packs are part of Pro");return}mockPack=rest.join("|");mockSec="All";mockDiff=0;mockQ=null;showTab("interview");renderMock()}
  else if(k==="co"){closeAll();showCompany(rest.join("|"))}
  else if(k==="quote"){closeAll();showQuote(rest.join("|"))}
  else if(k==="markets"){closeAll();openMarkets()}
  else if(k==="deal"){closeAll();showTab("learn");showSub("learn","deals");const dd=DEALS.find(d=>d.id===rest[0]);if(dd){dealTab=dealTier(dd);renderDeals()}const det=dd&&[...document.querySelectorAll("details.deal")].find(x=>x.querySelector(`[data-deal="${dd.id}"]`));if(det){det.open=true;det.scrollIntoView({block:"center"})}}
  else if(k==="chal"){closeAll();goTool("chal");openChal(CHAL.find(c=>c.id===rest[0]))}
  else if(k==="sub"){closeAll();const v=(TAB_ALIAS[rest[0]]||[rest[0]])[0];showTab(v);showSub(v,rest[1])}
  else if(k==="review"){closeAll();if(dueReviews().length)runReview();else{showTab("train");toast("Nothing due right now")}}
  else if(k==="duel"){closeAll();showTab("compete");showSub("compete","club");startDuel(randCode(5),true)}
  else if(k==="plan"){closeAll();onboarding(true)}
  else if(k==="q"){closeAll();const q=MOCK_QS.find(x=>x.id===rest[0]);if(q&&q.d===3&&!isPro()){upgrade("Advanced questions are part of Pro");return}mockSec="All";mockDiff=0;mockQ=q;showTab("interview");renderMock()}}
function briefLinks(tr,i){const sec=(LEVEL_SEC[tr.id]||[])[i],tool=LEVEL_TOOL[tr.id+"-"+i],out=[];
  if(sec)out.push([`Practice ${sec} interview questions`,`int|${sec}`]);if(tool)out.push([`Try it in the ${tool.toUpperCase()} builder`,`tool|${tool}`]);
  if(tr.id==="ib"&&i===0)out.push(["Browse bank profiles and pay","tab|firms"]);if(tr.id==="ib"&&i===2)out.push(["Open your networking tracker","tab|recruit"]);if(tr.id==="pe"&&i===4)out.push(["See private equity pay ladders","firm|Blackstone"]);
  return linkRow(out)}
function linkFirms(html){const names=FIRMS.map(f=>f[0]).sort((a,b)=>b.length-a.length);const short={"Morgan Stanley":1,"Goldman Sachs":1};
  let out=html;names.forEach(n=>{const re=new RegExp("(?<![\\w>])("+n.replace(/[.*+?^${}()|[\]\\&]/g,"\\$&")+")(?![\\w<])","g");out=out.replace(re,`<button class="flink" data-act="firm|${n}">$1</button>`)});
  return out}

/* command palette */
let palIdx=0,palItems=[];
function palIndex(){const it=[];
  [["home","Home"],["learn","Learn · Tracks"],["sub|learn|deals","Learn · Deal breakdowns"],["practice","Practice · Interview"],["sub|practice|rapid","Practice · Rapid Fire"],["sub|practice|chal","Practice · Modeling"],["compete","Compete"],["sub|compete|boards","Compete · Leaderboards"],["sub|compete|club","Compete · Club & duels"],["career","Career · Roadmap"],["sub|career|open","Career · Application openings"],["ladder|x","Career ladder: Intern → MD"],["sub|career|firms","Career · Firms"],["pro","M&A Pro"],["settings","Settings"],["subs|x","Email updates"]].forEach(([t,l])=>it.push({g:"Go to",l,act:t.startsWith("sub|")||t.startsWith("subs|")||t.startsWith("ladder|")?t:"tab|"+t}));
  it.push({g:"Do",l:"Answer today's question",act:"tab|home"},{g:"Do",l:"Play Rapid Fire",act:"rapid"},{g:"Do",l:"Weekly Gauntlet",act:"gauntlet"},{g:"Do",l:"Open The Wire",act:"news"},{g:"Do",l:"View my profile",act:"profile"},{g:"Do",l:"Edit my profile",act:"edit"},{g:"Do",l:"LBO builder",act:"tool|lbo"},{g:"Do",l:"DCF builder",act:"tool|dcf"});
  ORDER.map(T).forEach(tr=>tr.levels.forEach((L,i)=>it.push({g:"Levels",l:`${L.n}`,s:`${tr.name} · Level ${i+1}`,act:`lvl|${tr.id}|${i}`})));
  MOCK_SECTIONS.forEach(sec=>it.push({g:"Interview sections",l:sec,s:`${MOCK_QS.filter(q=>q.c===sec).length} questions`,act:`int|${sec}`}));
  MOCK_QS.forEach(q=>it.push({g:"Interview questions",l:q.q,s:`${q.c} · ${DIFF[q.d]}`,act:`q|${q.id}`}));
  FIRMS.forEach(f=>it.push({g:"Firms",l:f[0],s:f[1],act:`firm|${f[0]}`}));
  NEWS.forEach(n=>it.push({g:"News",l:n.h,s:n.k+" · "+n.d,act:"news"}));
  TICKER.forEach(t=>{const [n,ty]=tInfo(t[0]);it.push({g:"Markets",l:t[0]+" · "+n,s:(t[1]||"")+(t[2]!=null?"  "+(t[2]>=0?"+":"")+t[2]+"%":""),act:"quote|"+t[0]})});
  it.push({g:"Do",l:"Market lookup",act:"markets"},{g:"Do",l:"My badges",act:"badges"});
  DEALS.forEach(d=>it.push({g:"Deals",l:d.buyer+" → "+d.target,s:d.value,act:"deal|"+d.id}));
  CHAL.forEach(c=>it.push({g:"Challenges",l:c.t,s:"Modeling challenge",act:"chal|"+c.id}));
  it.push({g:"Do",l:"Share my profile card",act:"share"},{g:"Do",l:"Who viewed my profile",act:"views"},{g:"Do",l:"Application tracker",act:"sub|recruit|apps"},{g:"Do",l:"Today's briefing",act:"tab|home"});
  FIRM_PACKS.forEach(f=>it.push({g:"Firm packs",l:f,s:"Interview pack · Pro",act:"pack|"+f}));
  it.push({g:"Do",l:"Review missed questions",act:"review"},{g:"Do",l:"Start a live duel",act:"duel"},{g:"Do",l:"My club",act:"gauntlet"},{g:"Do",l:"AI resume review",act:"sub|recruit|res"},{g:"Do",l:"Recruiting calendar",act:"sub|recruit|cal"},{g:"Do",l:"Modeling challenges",act:"sub|tools|chal"},{g:"Do",l:"Rebuild my plan",act:"plan"});
  return it}
function openPalette(){if(!A().search){A().search=1;save()}const p=$("#palette");p.hidden=false;$("#palBg").hidden=false;const inp=$("#palIn");inp.value="";palQuery("");inp.focus();document.body.style.overflow="hidden"}
function closePalette(silent){const p=$("#palette");if(!p||p.hidden)return;p.hidden=true;$("#palBg").hidden=true;if(ov.hidden&&$("#wire").hidden)document.body.style.overflow="";if(!silent)$("#palBtn").focus()}
function palQuery(q){const toks=q.toLowerCase().split(/\s+/).filter(Boolean);const all=palIndex();
  palItems=(toks.length?all.filter(x=>{const h=(x.l+" "+(x.s||"")+" "+x.g).toLowerCase();return toks.every(t=>h.includes(t))}):all.filter(x=>x.g==="Go to"||x.g==="Do")).slice(0,40);if(toks.length&&q.trim().length>=2){const cs=coSearch(q,8).filter(c=>!TICKER.find(t=>t[0]===c.s));palItems=palItems.slice(0,32).concat(cs.map(c=>({g:"Companies",l:c.s+" · "+c.n,s:c.e,act:"co|"+c.s})))}palIdx=0;drawPal()}
function drawPal(){let g="";$("#palList").innerHTML=palItems.length?palItems.map((x,i)=>{const head=x.g!==g?(g=x.g,`<div class="pal-g">${x.g}</div>`):"";return head+`<button class="pal-i ${i===palIdx?'on':''}" data-i="${i}" role="option" aria-selected="${i===palIdx}"><span>${esc(x.l)}</span>${x.s?`<small>${esc(x.s)}</small>`:""}</button>`}).join(""):`<p class="note" style="padding:14px">Nothing matches. Try a firm, a topic like "DCF", or a tab name.</p>`;
  $("#palList").querySelectorAll(".pal-i").forEach(b=>{b.onclick=()=>{const x=palItems[+b.dataset.i];closePalette(true);runAct(x.act)};b.onmousemove=()=>{if(palIdx!==+b.dataset.i){palIdx=+b.dataset.i;$("#palList").querySelectorAll(".pal-i").forEach((y,j)=>{y.classList.toggle("on",j===palIdx);y.setAttribute("aria-selected",j===palIdx)})}}});
  const on=$("#palList .pal-i.on");if(on)on.scrollIntoView({block:"nearest"})}

$("#brandBtn").onclick=()=>{const bb=$("#brandBtn");bb.classList.remove("spin");void bb.offsetWidth;bb.classList.add("spin");closeAll();window._noVT=true;try{showTab("home")}finally{window._noVT=false}};
$("#brandBtn").addEventListener("animationend",e=>{if(e.target.id==="brandBtn")e.target.classList.remove("spin")});
$("#palBtn").onclick=openPalette;$("#palBg").onclick=()=>closePalette();
$("#palIn").addEventListener("input",e=>palQuery(e.target.value));
$("#palIn").addEventListener("keydown",e=>{if(e.key==="ArrowDown"){e.preventDefault();palIdx=Math.min(palItems.length-1,palIdx+1);drawPal()}else if(e.key==="ArrowUp"){e.preventDefault();palIdx=Math.max(0,palIdx-1);drawPal()}else if(e.key==="Enter"){const x=palItems[palIdx];if(x){closePalette(true);runAct(x.act)}}else if(e.key==="Escape"){e.stopPropagation();closePalette()}});
document.addEventListener("keydown",e=>{const typing=/INPUT|TEXTAREA|SELECT/.test((e.target.tagName||""));if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#palette").hidden?openPalette():closePalette()}else if(e.key==="/"&&!typing&&$("#palette").hidden){e.preventDefault();openPalette()}});
if(!/Mac|iPhone|iPad/.test(navigator.platform||""))$("#palBtn kbd").textContent="Ctrl K";

