function coLoad(){if(window.CO_RAW)return Promise.resolve();if(coP)return coP;coP=new Promise(res=>{const sc=document.createElement("script");sc.src="js/companies.js";sc.async=true;sc.onload=()=>{CO=null;res();try{renderTape()}catch(e){}try{if(!$("#palette").hidden)palQuery($("#palIn").value)}catch(e){}try{if($("#mkQ"))$("#mkQ").dispatchEvent(new Event("input"))}catch(e){}};sc.onerror=()=>{coP=null;res()};document.head.appendChild(sc)});return coP}
{const go=()=>(window.requestIdleCallback||(f=>setTimeout(f,2000)))(()=>coLoad(),{timeout:5000});document.readyState==="complete"?go():window.addEventListener("load",go,{once:true})} /* after the load event, so it never delays it */
function coList(){if(CO)return CO;if(!window.CO_RAW){coLoad();return []}CO=window.CO_RAW.split("\n").map(l=>{const [s,n,e,se,i,c]=l.split("|");return{s,n,e:CO_EX[+e],sec:CO_SEC[+se]||"",ind:CO_IND[+i]||"",ctry:CO_CTRY[+c]||"",sl:s.toLowerCase(),nl:n.toLowerCase()}});return CO}
function coSearch(q,limit=40){q=q.trim().toLowerCase();if(!q)return[];const out=[];const wre=new RegExp("(^|[^a-z0-9])"+q.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));
  for(const c of coList()){let sc=0;if(c.sl===q)sc=1000;else if(c.sl.startsWith(q))sc=700-c.s.length;else if(c.nl.startsWith(q))sc=600-c.n.length/10;else if(wre.test(c.nl))sc=400-c.n.length/10;else if(q.length>=3&&c.nl.includes(q))sc=200;else if(q.length>=3&&(c.ind.toLowerCase().includes(q)||c.sec.toLowerCase().includes(q)))sc=100;if(sc)out.push([sc,c])}
  return out.sort((a,b)=>b[0]-a[0]).slice(0,limit).map(x=>x[1])}
const coBy=s=>coList().find(c=>c.s===s);
function showCompany(sym,fromList){if(TICKER.find(t=>t[0]===sym))return showQuote(sym,fromList);if(!window.CO_RAW){coLoad().then(()=>{if(window.CO_RAW)showCompany(sym,fromList)});return}const c=coBy(sym);if(!c)return;const w=(S.watch||[]).includes(sym);
  const firstWord=c.n.split(/[\s,.]+/)[0];const re=new RegExp("\\b("+[c.n.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),firstWord.length>3?firstWord:"\u0000"].join("|")+")\\b","i");
  const stories=NEWS.filter(x=>re.test(x.h+" "+x.w+" "+x.m));const deal=DEALS.find(d=>re.test(d.buyer+" "+d.target));
  const pitch=MOCK_QS.find(q=>q.q==="Pitch me a stock."),shortQ=MOCK_QS.find(q=>q.q==="Pitch me a short.");
  openPanel(`${fromList?'<button class="ghost back" id="qBack">← All markets</button>':""}<div class="label">${esc(c.e)}${c.sec?" · "+esc(c.sec):""}</div>
    <div class="q-head"><div><h2>${esc(c.s)}</h2><p class="sub" style="margin:0">${esc(c.n)}</p></div><button class="star" id="qStar" aria-pressed="${w}">${w?"★ Watching":"☆ Watch"}</button></div>
    <div class="co-facts">${[["Exchange",c.e],["Sector",c.sec||"–"],["Industry",c.ind||"–"],["Country",c.ctry||"–"]].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join("")}</div>
    <p class="note">M&A shows closing prices only for the symbols on the tape. Check the latest price and filings here:</p>
    <div class="co-links"><a class="ghost outline" href="https://finance.yahoo.com/quote/${encodeURIComponent(c.s.replace(".","-"))}" target="_blank" rel="noopener">Price on Yahoo Finance ↗</a><a class="ghost outline" href="https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${encodeURIComponent(c.s)}&type=10-K" target="_blank" rel="noopener">10-K filings on SEC EDGAR ↗</a></div>
    <div class="ang" style="margin-top:14px"><b>Interview angle</b>Could you pitch ${esc(c.n.split(" ").slice(0,3).join(" "))}? Know what it sells, who it competes with, how it's valued, and one catalyst.</div>
    ${stories.length?`<div class="label" style="margin-top:18px">In this week's news</div>${stories.map(x=>`<button class="q-story" data-act="news"><b>${esc(x.h)}</b><span>${esc(x.k)} · ${esc(x.d)}</span></button>`).join("")}`:""}
    ${linkRow([[`Pitch it in a mock interview`,"q|"+(pitch?pitch.id:"")],[`Pitch it as a short`,"q|"+(shortQ?shortQ.id:"")]].concat(deal?[[`Deal breakdown: ${deal.buyer} → ${deal.target}`,"deal|"+deal.id]]:[]))}`);
  bindRel(panel);
  $("#qStar").onclick=()=>{toggleWatch(sym);const on=(S.watch||[]).includes(sym);$("#qStar").setAttribute("aria-pressed",on);$("#qStar").textContent=on?"★ Watching":"☆ Watch"};
  if($("#qBack"))$("#qBack").onclick=()=>openMarkets()}

