const TINFO={"DOW":["Dow Jones Industrial Average","Index","30 large U.S. blue-chip companies, weighted by share price. One of the oldest U.S. stock indexes.",["Dow"]],
 "S&P 500":["S&P 500","Index","500 of the largest U.S. companies, weighted by market value. The main benchmark for U.S. stocks.",["S&P 500"]],
 "NASDAQ":["Nasdaq Composite","Index","Thousands of stocks listed on the Nasdaq exchange, heavy in technology.",["Nasdaq","tech"]],
 "RUSSELL 2000":["Russell 2000","Index","2,000 smaller U.S. companies. The standard gauge of small caps.",["Russell","small"]],
 "VIX":["Cboe Volatility Index","Index","Expected 30-day volatility of the S&P 500. Traders call it the fear gauge: it rises when markets get nervous.",["VIX","volatil"]],
 "10Y YIELD":["10-Year Treasury Yield","Rates","The interest rate on 10-year U.S. government bonds. It drives mortgage rates and the risk-free rate in valuations.",["Treasury","yield","rate","Fed"]],
 "BRENT":["Brent Crude Oil","Commodities","The global benchmark price for crude oil, per barrel.",["oil","Brent","Iran"]],
 "WTI":["WTI Crude Oil","Commodities","The U.S. benchmark price for crude oil, per barrel.",["oil","WTI"]],
 "GOLD":["Gold","Commodities","Price per ounce. Investors often buy gold when they're worried about inflation or turmoil.",["gold"]],
 "SILVER":["Silver","Commodities","Price per ounce. Used in industry and as a store of value.",["silver"]],
 "BITCOIN":["Bitcoin","Crypto","The largest cryptocurrency by market value.",["Bitcoin","crypto"]],
 "TSLA":["Tesla","Stocks","Electric vehicles, batteries and energy storage.",["Tesla"]],
 "ANT":["Anthropic","Stocks","AI company that builds the Claude models. Listed on Nasdaq in November 2026.",["Anthropic","Claude"]],
 "SPCX":["SpaceX","Stocks","Rockets, satellites and the Starlink internet service.",["SpaceX"]],
 "AXP":["American Express","Stocks","Credit cards and payments, focused on higher-spending customers.",["American Express","Amex"]],
 "RHI":["Robert Half","Stocks","Staffing and recruiting firm.",["Robert Half"]],
 "CCI":["Crown Castle","Stocks","Owns cell towers that wireless carriers rent space on.",["Crown Castle"]],
 "BE":["Bloom Energy","Stocks","Fuel cells that generate electricity on site.",["Bloom"]],
 "FIX":["Comfort Systems USA","Stocks","Heating, cooling and building systems contractor.",["Comfort Systems"]]};
const TANGLE={Index:"Know where the S&P 500, Nasdaq and 10-year yield sit before any interview. \"What's the market doing?\" comes up constantly.",Rates:"Higher yields raise the risk-free rate, which raises WACC and lowers DCF values. Expect a question on this.",Commodities:"Oil feeds straight into inflation and company costs. Know who wins (producers) and who loses (airlines, shippers).",Crypto:"Rarely a core IB topic, but hedge funds may ask your view. Have a short, reasoned take.",Stocks:"Could you pitch it? Know what the company does, why the stock moved, and whether you'd buy or short it."};
const tInfo=s=>{if(TINFO[s])return TINFO[s];const c=typeof coBy==="function"?coBy(s):null;return c?[c.n,"Stocks",[c.sec,c.ind].filter(Boolean).join(" · "),[s,c.n.split(/[\s,.]+/)[0]]]:[s,"Stocks","",[s]]};
const fmtChg=c=>c===null||c===undefined?"":`<span class="tc ${c>=0?'up':'dn'}">${c>=0?"▲":"▼"} ${Math.abs(c).toFixed(2)}%</span>`;
function tapeList(){const w=S.watch||[];const only=S.settings.tapeWatch&&w.length;const list=TICKER.filter(t=>!only||w.includes(t[0]));return list.slice().sort((a,b)=>(w.includes(b[0])?1:0)-(w.includes(a[0])?1:0))}
function renderTape(){const tr=$("#tapeTrack");if(!tr)return;$("#tapeTag").textContent="Prices: "+TICKER_DATE+(/\d:\d\d|ET/.test(TICKER_DATE)?"":" close");const w=S.watch||[];
  const list=tapeList();
  const item=(t,hid)=>{const [s,p,c]=t;return `<button class="tk ${w.includes(s)?'starred':''}" data-sym="${esc(s)}" ${hid?'tabindex="-1"':""}>${w.includes(s)?'<span class="tstar" aria-label="Watchlist">★</span>':""}<b>${esc(s)}</b>${p?`<span class="tp">${esc(p)}</span>`:""}${fmtChg(c)}</button>`};
  const set=hid=>list.map(t=>item(t,hid)).join('<span class="tsep" aria-hidden="true">·</span>')+'<span class="tsep" aria-hidden="true">·</span>';
  tr.innerHTML=`<div class="tape-set">${set(false)}</div><div class="tape-set" aria-hidden="true">${set(true)}</div>`;
  startTape();
  tr.querySelectorAll("[data-sym]").forEach(b=>b.onclick=e=>{e.stopPropagation();openMarkets(b.dataset.sym)});
  $("#tapeSearch").onclick=e=>{e.stopPropagation();openMarkets()};
  $("#tape").hidden=!!S.settings.hideTape;setTimeout(fxTapeTicks,400)}
let mktFilter="All",mktSort="default",mktQ="";
const MK_HUE={Index:220,Rates:265,Commodities:38,Crypto:28,Stocks:200,Co:210};
const mkAv=(s,ty)=>`<span class="mk-av" style="--h:${MK_HUE[ty]??210}" aria-hidden="true">${esc(s.replace(/[^A-Z0-9&]/gi,"").slice(0,ty==="Index"?1:2)||"·")}</span>`;
const mkMax=()=>Math.max(1,...TICKER.map(t=>Math.abs(t[2]||0)));
const mkBar=c=>c===null||c===undefined?`<span class="mk-bar"></span>`:`<span class="mk-bar" aria-hidden="true"><i class="${c>=0?"up":"dn"}" style="width:${Math.max(6,Math.min(50,Math.sqrt(Math.abs(c)/mkMax())*50))}%"></i></span>`;
const mkChg=c=>c===null||c===undefined?`<span class="mk-c flat">–</span>`:`<span class="mk-c ${c>=0?"up":"dn"}">${c>=0?"+":"−"}${Math.abs(c).toFixed(2)}%</span>`;
function mkPulseHTML(){const pick=["S&P 500","NASDAQ","DOW","10Y YIELD"].map(s=>TICKER.find(t=>t[0]===s)).filter(Boolean);
  const ch=TICKER.filter(t=>typeof t[2]==="number"),up=ch.filter(t=>t[2]>=0).length,dn=ch.length-up;
  const stocks=ch.filter(t=>tInfo(t[0])[1]==="Stocks").sort((a,b)=>b[2]-a[2]);const g=stocks[0],l=stocks[stocks.length-1];
  return `<div class="mk-pulse">${pick.map(t=>`<button class="mk-tile ${t[2]==null?"":t[2]>=0?"up":"dn"}" data-mq="${esc(t[0])}"><span>${esc(t[0]==="DOW"?"Dow":t[0]==="NASDAQ"?"Nasdaq":t[0]==="10Y YIELD"?"10-yr yield":t[0])}</span><b>${esc(t[1])}</b>${t[2]==null?`<small>&nbsp;</small>`:`<small>${t[2]>=0?"▲":"▼"} ${Math.abs(t[2]).toFixed(2)}%</small>`}</button>`).join("")}</div>
   <div class="mk-breadth"><div class="mk-bb" role="img" aria-label="${up} up, ${dn} down"><i class="up" style="width:${ch.length?up/ch.length*100:50}%"></i><i class="dn" style="width:${ch.length?dn/ch.length*100:50}%"></i></div><span><b class="up">${up} up</b> · <b class="dn">${dn} down</b> on the tape</span>
   ${g&&g[2]>0?`<button class="mk-mover up" data-mq="${esc(g[0])}">Top gainer <b>${esc(g[0])}</b> +${g[2].toFixed(1)}%</button>`:""}${l&&l[2]<0?`<button class="mk-mover dn" data-mq="${esc(l[0])}">Top loser <b>${esc(l[0])}</b> −${Math.abs(l[2]).toFixed(1)}%</button>`:""}</div>`}
function openMarkets(sym){if(sym)return showQuote(sym);
  openPanel(`<div class="label">Markets · ${window.TAPE_LIVE?'live prices · '+TICKER_DATE:'prices from '+TICKER_DATE+' close'}</div><h2>Market lookup</h2>
    ${mkPulseHTML()}
    <div class="mk-search"><input id="mkQ" placeholder="Search 5,800+ U.S. companies, a symbol, or a market like oil" value="${esc(mktQ)}" aria-label="Search markets" autocomplete="off"></div>
    <div class="cats" id="mkCats" role="group" aria-label="Filter"></div>
    <div class="mk-head"><span>Name</span><button class="flink" id="mkSort">${mktSort==="up"?"Biggest gainers":mktSort==="down"?"Biggest losers":"Default order"} ⇅</button></div>
    <div id="mkList" class="mk-list"></div>
    <label class="srow" style="border:0"><span><b>Ticker shows my watchlist only</b><span>Star symbols to build a watchlist. Starred items always lead the tape.</span></span><input type="checkbox" class="sw" id="mkOnly" ${S.settings.tapeWatch?"checked":""}></label>
    <p class="note">${window.TAPE_LIVE?'Live prices from Yahoo Finance, updated every minute (can lag a few minutes).':'Closing prices from '+TICKER_DATE+'. Live prices show during market hours.'}</p>`);
  panel.classList.add("wide");
  const cats=["All","Companies","Watchlist","Index","Rates","Commodities","Crypto","Stocks"];
  const draw=()=>{$("#mkCats").innerHTML=cats.map(c=>`<button class="chip" data-c="${c}" aria-pressed="${c===mktFilter}">${c==="Index"?"Indexes":c}</button>`).join("");
    $("#mkCats").querySelectorAll("[data-c]").forEach(b=>b.onclick=()=>{mktFilter=b.dataset.c;draw()});
    const q=mktQ.trim().toLowerCase(),w=S.watch||[];
    let rows=mktFilter==="Companies"?[]:TICKER.filter(t=>{const [n,ty,d,k]=tInfo(t[0]);if(mktFilter==="Watchlist"&&!w.includes(t[0]))return false;if(mktFilter!=="All"&&mktFilter!=="Watchlist"&&ty!==mktFilter)return false;return !q||new RegExp("(^|[^a-z0-9])"+q.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),"i").test(t[0]+" "+n+" "+ty+" "+d+" "+k.join(" "))});
    if(mktSort!=="default")rows=rows.slice().sort((a,b)=>((mktSort==="up"?b[2]-a[2]:a[2]-b[2])||0)).sort((a,b)=>(a[2]===null)-(b[2]===null));
    $("#mkList").innerHTML=rows.length?rows.map(t=>{const [n,ty]=tInfo(t[0]);return `<div class="mk-row"><button class="mk-star" data-star="${esc(t[0])}" aria-pressed="${w.includes(t[0])}" aria-label="${w.includes(t[0])?"Remove from":"Add to"} watchlist">${w.includes(t[0])?"★":"☆"}</button><button class="mk-main" data-q="${esc(t[0])}"><span class="mk-id">${mkAv(t[0],ty)}<span><b>${esc(t[0])}</b><small>${esc(n)} · ${ty}</small></span></span><span class="mk-num">${mkBar(t[2])}${t[1]?`<span class="mk-p">${esc(t[1])}</span>`:""}${mkChg(t[2])}</span></button></div>`}).join(""):`<p class="note" style="padding:12px 0">${mktFilter==="Watchlist"?"Your watchlist is empty. Tap ☆ on any row to add it.":"Nothing matches. Try a symbol like TSLA or a word like oil."}</p>`;
    {const showCo=(mktFilter==="All"||mktFilter==="Companies")&&q;const wc=mktFilter==="Watchlist"?(S.watch||[]).filter(x=>!TICKER.find(t=>t[0]===x)).map(coBy).filter(Boolean):[];const cos=showCo?coSearch(q,40).filter(c=>!TICKER.find(t=>t[0]===c.s)):wc;
     if(mktFilter==="Companies"&&!q)$("#mkList").innerHTML=`<p class="note" style="padding:12px 0">Search ${coList().length.toLocaleString()} companies listed on NASDAQ, NYSE and NYSE American by name or symbol.</p>`;
     else if(cos.length){if(!rows.length)$("#mkList").innerHTML="";$("#mkList").insertAdjacentHTML("beforeend",`<div class="mk-sub">${mktFilter==="Watchlist"?"Companies you watch":`U.S. listed companies${cos.length>=40?" · top 40 matches":""}`}</div>`+cos.map(c=>`<div class="mk-row"><button class="mk-star" data-star="${esc(c.s)}" aria-pressed="${w.includes(c.s)}" aria-label="${w.includes(c.s)?"Remove from":"Add to"} watchlist">${w.includes(c.s)?"★":"☆"}</button><button class="mk-main" data-co="${esc(c.s)}"><span class="mk-id">${mkAv(c.s,"Co")}<span><b>${esc(c.s)}</b><small>${esc(c.n)}${c.sec?" · "+esc(c.sec):""}</small></span></span><span class="mk-num"><small class="mk-ex">${esc(c.e)}</small></span></button></div>`).join(""))}}
    if(!fxCalm())$("#mkList").querySelectorAll(".mk-row").forEach((r,i)=>{if(i<24){r.style.setProperty("--i",i);r.classList.add("mk-in")}});
    $("#mkList").querySelectorAll("[data-co]").forEach(b=>b.onclick=()=>showCompany(b.dataset.co,true));
    $("#mkList").querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>showQuote(b.dataset.q,true));
    $("#mkList").querySelectorAll("[data-star]").forEach(b=>b.onclick=()=>{toggleWatch(b.dataset.star);draw();const n=$(`#mkList [data-star="${CSS.escape(b.dataset.star)}"]`);if(n)n.focus()})};
  $("#mkQ").oninput=e=>{mktQ=e.target.value;draw()};
  $("#mkQ").onkeydown=e=>{if(e.key==="Enter"){const f=$("#mkList [data-q]");if(f)f.click()}};
  $("#mkSort").onclick=()=>{mktSort=mktSort==="default"?"up":mktSort==="up"?"down":"default";$("#mkSort").textContent=(mktSort==="up"?"Biggest gainers":mktSort==="down"?"Biggest losers":"Default order")+" ⇅";draw()};
  $("#mkOnly").onchange=e=>{S.settings.tapeWatch=e.target.checked;save();renderTape();if(e.target.checked&&!(S.watch||[]).length)toast("Star a few symbols first")};
  panel.querySelectorAll("[data-mq]").forEach(b=>b.onclick=()=>showQuote(b.dataset.mq,true));
  draw();$("#mkQ").focus()}
let tapeX=0,tapeLast=0,tapeHover=false,tapeKey=false,tapeRAF=null;
function startTape(){const tape=$("#tape"),tr=$("#tapeTrack");if(!tape||!tr)return;
  if(!tape.dataset.bound){tape.dataset.bound="1";
    tape.addEventListener("pointerenter",e=>{if(e.pointerType==="mouse")tapeHover=true});
    tape.addEventListener("pointerleave",()=>{tapeHover=false});
    tape.addEventListener("focusin",e=>{tapeKey=!!(e.target.matches&&e.target.matches(":focus-visible"))});
    tape.addEventListener("focusout",()=>{tapeKey=false})}
  if(tapeRAF)return;
  const step=t=>{tapeRAF=requestAnimationFrame(step);const dt=tapeLast?Math.min(64,t-tapeLast):16;tapeLast=t;
    if(document.hidden)return;
    const set=tr.firstElementChild;if(!set)return;const w=set.getBoundingClientRect().width;if(!w)return;
    tapeX-=dt*0.06*(({slow:.5,fast:1.7})[S.settings.tapeSpeed]||1);if(-tapeX>=w)tapeX+=w;tr.style.transform=`translate3d(${tapeX}px,0,0)`};
  tapeRAF=requestAnimationFrame(step)}
function toggleWatch(s){setTimeout(checkBadges,50);const w=new Set(S.watch||[]);w.has(s)?w.delete(s):w.add(s);S.watch=[...w];save();renderTape();toast(w.has(s)?`${s} added to your watchlist`:`${s} removed from your watchlist`)}
function showQuote(sym,fromList){const t=TICKER.find(x=>x[0]===sym);if(!t)return;const [n,ty,d,keys]=tInfo(sym),w=(S.watch||[]).includes(sym);
  const re=new RegExp(keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|"),"i");
  const stories=NEWS.filter(x=>re.test(x.h+" "+x.w+" "+x.m));
  const firm=FIRMS.find(f=>keys.some(k=>f[0].toLowerCase()===k.toLowerCase()));
  const sec=ty==="Stocks"||ty==="Index"||ty==="Crypto"?"Markets & Hedge Funds":ty==="Rates"?"Valuation & DCF":"Markets & Hedge Funds";
  openPanel(`${fromList?'<button class="ghost back" id="qBack">← All markets</button>':""}<div class="label">${ty} · ${window.TAPE_LIVE?TICKER_DATE:TICKER_DATE+' close'}</div>
    <div class="q-head"><div><h2>${esc(sym)}</h2><p class="sub" style="margin:0">${esc(n)}</p></div><button class="star" id="qStar" aria-pressed="${w}">${w?"★ Watching":"☆ Watch"}</button></div>
    <div class="q-big">${t[1]?`<b>${esc(t[1])}</b>`:""}${t[2]===null||t[2]===undefined?`<span class="note">No daily change recorded</span>`:fmtChg(t[2])}</div>
    ${d?`<p>${esc(d)}</p>`:""}
    <div class="ang"><b>Interview angle</b>${TANGLE[ty]||TANGLE.Stocks}</div>
    ${stories.length?`<div class="label" style="margin-top:18px">In this week's news</div>${stories.map(x=>`<button class="q-story" data-act="news"><b>${esc(x.h)}</b><span>${esc(x.k)} · ${esc(x.d)}</span></button>`).join("")}`:""}
    ${linkRow([[`Practice ${sec} questions`,`int|${sec}`]].concat(firm?[[`${firm[0]} profile`,`firm|${firm[0]}`]]:[]).concat(ty==="Rates"?[["See rates in the DCF builder","tool|dcf"]]:[]))}`);
  bindRel(panel);
  $("#qStar").onclick=()=>{toggleWatch(sym);const on=(S.watch||[]).includes(sym);$("#qStar").setAttribute("aria-pressed",on);$("#qStar").textContent=on?"★ Watching":"☆ Watch"};
  if($("#qBack"))$("#qBack").onclick=()=>openMarkets()}

function etNow(){const f=new Intl.DateTimeFormat("en-US",{timeZone:"America/New_York",hour12:false,weekday:"short",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"}).formatToParts(new Date());const g=t=>f.find(x=>x.type===t).value;return{wd:g("weekday"),h:+g("hour")%24,m:+g("minute"),s:+g("second")}}
function tickMarket(){const el=$("#mktTxt");if(!el)return;const t=etNow(),days=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"],di=days.indexOf(t.wd),sec=t.h*3600+t.m*60+t.s,open=9.5*3600,close=16*3600;
  const isOpen=di>=1&&di<=5&&sec>=open&&sec<close;let left;
  if(isOpen)left=close-sec;else{let d=0,target;if(di>=1&&di<=5&&sec<open){target=open-sec}else{d=1;let nd=(di+1)%7;while(nd===0||nd===6){d++;nd=(nd+1)%7}target=d*86400-sec+open}left=target}
  const D=Math.floor(left/86400),H=Math.floor(left%86400/3600),M=Math.floor(left%3600/60),Sx=left%60,p=n=>String(n).padStart(2,"0");
  el.textContent=`NYSE ${isOpen?"open · closes in":"closed · opens in"} ${D?D+"d ":""}${p(H)}:${p(M)}:${p(Sx)}`;$("#mkt").classList.toggle("open",isOpen)}
setInterval(tickMarket,1000);

/* ---------- club email invites ---------- */
const SITE_URL=/^https?:$/.test(location.protocol)&&!/claude\.ai$/.test(location.hostname)?location.origin+"/":"https://mnaprep.com/";
function inviteClub(name){const code=S.club.code,link=SITE_URL+"#join-"+code,from=myName?myName.split(" ")[0]:"";
  const subject=`Join ${name} on M&A`;
  const body=`Hey,\n\n${from?from+" invited you":"You're invited"} to join ${name} on M&A, where we train for investment banking and PE interviews together and compete on a private club leaderboard.\n\nJoin here: ${link}\n\nOr open M&A, go to Compete, and enter club code: ${code}`;
  openPanel(`<div class="label">Invite to ${esc(name)}</div><h2>Invite by email</h2><p class="sub">Add emails, then open the invite in your mail app. You can also copy the message or the link and send it however you like.</p>
   <form id="invForm" class="pform" style="grid-template-columns:1fr" autocomplete="off">
    <label>Emails<input id="invTo" placeholder="name@school.edu, friend@gmail.com" aria-label="Email addresses"></label>
    <label>Subject<input id="invSub" value="${esc(subject)}"></label>
    <label>Message<textarea id="invBody" style="min-height:200px">${esc(body)}</textarea></label>
    <div class="actions"><a class="btn" id="invMail" href="#" target="_blank" rel="noopener">Open in email</a><button type="button" class="ghost outline" id="invCopyMsg">Copy message</button><button type="button" class="ghost outline" id="invCopyLink">Copy join link</button></div>
   </form>
   <p class="note" style="margin-top:12px">Join link: <span class="code" style="letter-spacing:0;user-select:all;word-break:break-all">${esc(link)}</span></p>
   <p class="note">If your email app doesn't open, use Copy message and paste it into an email.</p>`);
  panel.classList.add("wide");
  const upd=()=>{const to=$("#invTo").value.split(/[,;\s]+/).filter(x=>/.+@.+\..+/.test(x)).join(",");$("#invMail").href=`mailto:${to.replace(/[^\w.@+,-]/g,"")}?subject=${encodeURIComponent($("#invSub").value)}&body=${encodeURIComponent($("#invBody").value)}`};
  ["invTo","invSub","invBody"].forEach(i=>$("#"+i).addEventListener("input",upd));upd();
  const copy=async(txt,msg,fb)=>{try{await navigator.clipboard.writeText(txt);toast(msg)}catch(e){fb.select();toast("Select and copy the highlighted text")}};
  $("#invCopyMsg").onclick=()=>copy(`Subject: ${$("#invSub").value}\n\n${$("#invBody").value}`,"Invite copied",$("#invBody"));
  $("#invCopyLink").onclick=()=>copy(link,"Join link copied",$("#invBody"));
  $("#invMail").onclick=()=>{toast("Opening your email app…")};
  $("#invTo").focus()}
function handleJoinHash(h){h=h||(location.hash||"").slice(1);const m=h.match(/^join-([a-z0-9]{4,8})$/);if(!m)return false;const code=m[1];
  showTab("compete");showSub("compete","club");
  if(S.club&&S.club.code===code){toast("You're already in this club");return true}
  const off=()=>PLAYERS.find(p=>p.club===code&&p.clubOfficer);
  openPanel(`<div class="label">Club invite</div><h2>Join ${off()?esc(off().clubName):"this club"}?</h2><p class="sub">You'll show up on the club's private leaderboard and officer view. Club code: <b class="code">${esc(code)}</b></p>${S.club&&S.club.code?`<p class="note">This will move you out of ${esc(S.club.name||"your current club")}.</p>`:""}<div class="actions"><button class="btn" id="jnYes">Join club</button><button class="ghost" id="jnNo">Not now</button></div>`);
  $("#jnYes").onclick=()=>{const o=off();S.club={code,name:o?o.clubName:"",officer:false};save();syncProfile();closePanel();renderClub();toast(o?`Joined ${o.clubName}`:"Joined. The club name appears once your officer is online.")};
  $("#jnNo").onclick=closePanel;return true}

/* ================= GAME LAYER v50 ================= */
const GS=()=>S.settings;
/* sound: tiny synthesized tones, no files */
let _ac=null;
function sfx(kind){const v=({soft:.05,on:.12})[GS().sound||"off"];if(!v)return;try{_ac=_ac||new (window.AudioContext||window.webkitAudioContext)();const ac=_ac;if(ac.state==="suspended")ac.resume();
  const seq={ok:[[660,0,.09],[990,.07,.16]],no:[[233,0,.14],[196,.09,.22]],clear:[[523,0,.1],[659,.09,.1],[784,.18,.1],[1047,.27,.26]],quest:[[784,0,.08],[1175,.07,.2]],rank:[[392,0,.12],[523,.1,.12],[659,.2,.12],[784,.3,.12],[1047,.42,.4]],chest:[[659,0,.08],[880,.08,.08],[1319,.16,.3]]}[kind]||[];
  const t0=ac.currentTime+.01;seq.forEach(([f,s,d])=>{const o=ac.createOscillator(),g=ac.createGain();o.type=kind==="no"?"triangle":"sine";o.frequency.value=f;g.gain.setValueAtTime(0,t0+s);g.gain.linearRampToValueAtTime(v,t0+s+.012);g.gain.exponentialRampToValueAtTime(.0001,t0+s+d);o.connect(g);g.connect(ac.destination);o.start(t0+s);o.stop(t0+s+d+.03)})}catch(e){}}
function buzz(p){if(GS().haptics===false||fxCalm())return;try{navigator.vibrate&&navigator.vibrate(p)}catch(e){}}

/* celebrations: full / subtle / off */
{const _fc=fxConfetti;fxConfetti=function(x,y,o={}){const c=GS().celebrate||"full";if(c==="off")return;if(c==="subtle")o={...o,n:Math.ceil((o.n||90)*.35),power:(o.power||6)*.7};return _fc(x,y,o)}}
{const _ru=fxRankUp;fxRankUp=function(a,b){sfx("rank");buzz([20,60,30]);return _ru(a,b)}}

/* daily quests */
const QUEST_POOL=[
 {id:"daily",t:"Answer today's daily question",n:1,ev:"daily",tier:0},
 {id:"correct5",t:"Get 5 answers right",n:5,ev:"correct",tier:0},
 {id:"level1",t:"Clear a level",n:1,ev:"level",tier:1},
 {id:"rf8",t:"Score 8+ in one Rapid Fire round",n:8,ev:"rfBest",tier:1,max:true},
 {id:"review3",t:"Remember 3 review questions",n:3,ev:"review",tier:1,need:()=>Object.keys(S.review||{}).length>=3},
 {id:"deal",t:"Finish a deal breakdown",n:1,ev:"deal",tier:1},
 {id:"stars3",t:"Get 3 stars on any level",n:1,ev:"stars3",tier:2},
 {id:"iv7",t:"Score 7+ on an interview answer",n:7,ev:"ivBest",tier:2,max:true},
 {id:"correct15",t:"Get 15 answers right",n:15,ev:"correct",tier:2},
 {id:"level2",t:"Clear 2 levels",n:2,ev:"level",tier:2},
 {id:"coffee",t:"Finish a voice coffee chat",n:1,ev:"coffee",tier:2}
];
const qHash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
function todayQuests(){const d=today();if(!S.quests||S.quests.d!==d){const h=qHash(d+(myId||""));const pick=tier=>{const opts=QUEST_POOL.filter(q=>q.tier===tier&&(!q.need||q.need())&&!(q.id==="daily"&&GS().hideDaily));return opts[(h>>>(tier*5))%opts.length]||opts[0]};
    const ids=[0,1,2].map(t=>pick(t)).filter(Boolean).map(q=>q.id);S.quests={d,ids,p:{},done:{},chest:0};
    if(S.daily&&today() in S.daily)S.quests.p.daily=1}
  return S.quests.ids.map(id=>QUEST_POOL.find(q=>q.id===id)).filter(Boolean)}
function questEvt(ev,val){try{const Q=todayQuests(),st=S.quests;const mx=QUEST_POOL.some(q=>q.ev===ev&&q.max);st.p[ev]=mx?Math.max(st.p[ev]||0,+val||0):(st.p[ev]||0)+(val===undefined?1:+val);
  S.questXP=S.questXP||{};let fresh=[];
  Q.forEach(q=>{if(!st.done[q.id]&&(st.p[q.ev]||0)>=q.n){st.done[q.id]=1;S.questXP[st.d]=(S.questXP[st.d]||0)+10;fresh.push(q)}});
  const all=Q.length&&Q.every(q=>st.done[q.id]);if(all&&!st.chest){st.chest=1;S.questXP[st.d]=(S.questXP[st.d]||0)+20}
  if(ev==="daily")freezeEarn();
  save();
  if(fresh.length){setTimeout(()=>{if(all){toast("All quests done · +20 XP bonus");sfx("chest");buzz([12,40,12,40,24]);const c=$("#quests .quests");if(c&&!c.closest("[hidden]"))fxBurstFrom(c,{n:70,power:7});else fxConfetti(innerWidth/2,innerHeight*.35,{n:60})}else{toast(`Quest done: ${fresh[0].t} · +10 XP`);sfx("quest");buzz(12)}render()},ov.hidden?0:450)}else renderQuests()}catch(e){console.warn("quest",e)}}
{const _tx=totalXP;totalXP=function(){return _tx()+Object.values(S.questXP||{}).reduce((a,b)=>a+(+b||0),0)}}
function renderQuests(){const el=$("#quests");if(!el)return;if(GS().hideQuests){el.hidden=true;return}el.hidden=false;
  const Q=todayQuests(),p=S.quests.p,dn=S.quests.done,nd=Q.filter(q=>dn[q.id]).length,all=nd===Q.length;
  el.innerHTML=`<div class="quests ${all?"all":""}"><div class="qs-top"><span class="label">Today's quests</span><span class="qs-chest">${all?"Bonus earned · +20 XP":`${nd}/${Q.length} done · finish all for +20 XP`}</span></div>
   ${Q.map(q=>{const v=Math.min(q.n,p[q.ev]||0),d=!!dn[q.id];return `<button class="qrow ${d?"done":""}" data-qgo="${q.ev}" type="button"><span class="qck" aria-hidden="true"></span><span class="qt">${esc(q.t)}</span><span class="qbar" aria-hidden="true"><i style="width:${v/q.n*100}%"></i></span><span class="qn">${d?"+10 XP":`${v}/${q.n}`}</span></button>`}).join("")}
   <div class="qs-foot">New quests at midnight${S.freezes?` · ${S.freezes} streak freeze${S.freezes>1?"s":""} saved`:""}</div></div>`;
  el.querySelectorAll("[data-qgo]").forEach(b=>b.onclick=()=>{const g=b.dataset.qgo;
    if(g==="daily"){const dg=$("#dailyGo");const d=$("#daily");if(d)d.scrollIntoView({block:"center",behavior:"smooth"});if(dg)setTimeout(()=>dg.click(),250)}
    else if(g==="rfBest"){showTab("practice");showSub("practice","rapid")}
    else if(g==="ivBest"){showTab("practice");showSub("practice","interview")}
    else if(g==="deal"){showTab("learn");showSub("learn","deals")}
    else if(g==="review"){if(dueReviews().length)runReview();else{showTab("learn");showSub("learn","tracks")}}
    else{const nx=nextLevel();if(nx)showBrief(nx.tr,nx.i);else{showTab("learn");showSub("learn","tracks")}}})}

/* streak freezes */
const hasDay=k=>(k in (S.daily||{}))||!!(S.frozen||{})[k];
streak=function(){let n=0;const d=new Date();if(!hasDay(today()))d.setDate(d.getDate()-1);while(hasDay(d.toLocaleDateString("en-CA"))){n++;d.setDate(d.getDate()-1)}return n};
function freezeEarn(){const st=streak();if(st>0&&st%7===0&&S.frzLast!==today()&&(S.freezes||0)<2){S.freezes=(S.freezes||0)+1;S.frzLast=today();setTimeout(()=>toast(`${st}-day streak · you earned a streak freeze`),1600)}}
function freezeCheck(){if(GS().autoFreeze===false||!(S.freezes>0))return;const y=addDaysKey(-1),y2=addDaysKey(-2);if(!hasDay(y)&&hasDay(y2)&&!hasDay(today())){S.frozen=S.frozen||{};S.frozen[y]=1;S.freezes--;save();setTimeout(()=>toast("You missed yesterday. A streak freeze kept your streak alive."),1200)}}

/* quiz: sound, haptics, combo, auto-advance, quest counting */
{const _q=quiz;quiz=function(opts){let run=0;const oa=opts.onAnswer;return _q({...opts,onAnswer:(n,ok)=>{if(oa)oa(n,ok);if(ok){run++;questEvt("correct")}else run=0;sfx(ok?"ok":"no");buzz(ok?8:[14,40,14]);
  setTimeout(()=>{const fb=$("#fb");if(!fb)return;const w=fb.querySelector(".why");if(w&&ok&&run>=2&&GS().combo!==false)w.insertAdjacentHTML("afterbegin",`<span class="combo">${run} in a row</span>`);
    if(ok&&GS().autoNext){const nx=$("#nx");if(nx){nx.classList.add("auto");setTimeout(()=>{if(nx.isConnected&&!nx.disabled)nx.click()},1150)}}},0)}})}}

/* keyboard answers */
document.addEventListener("keydown",e=>{if(GS().keys===false||e.metaKey||e.ctrlKey||e.altKey||e.key.length!==1)return;const t=e.target;if(t&&(t.tagName==="INPUT"||t.tagName==="TEXTAREA"||t.tagName==="SELECT"||t.isContentEditable))return;
  const k=e.key.toLowerCase();let i="1234".indexOf(k);if(i<0)i="abcd".indexOf(k);if(i<0)return;
  const scope=!ov.hidden?panel:(document.querySelector('.view[data-view="home"]:not([hidden])')?$("#daily"):null);if(!scope)return;
  const opts=[...scope.querySelectorAll(".opt")].filter(o=>!o.disabled&&!o.closest("[hidden]"));if(!opts[i])return;e.preventDefault();opts[i].click()});

/* skills chart */
function renderMastery(){const el=$("#mastery");if(!el)return;el.hidden=true;return;if(GS().hideMastery){el.hidden=true;return}el.hidden=false;
  const tids=((typeof prof==="function"&&prof().learnTracks)||ORDER).filter(t=>T(t));
  const rows=tids.map(T).map(tr=>{let s=0;tr.levels.forEach((_,i)=>s+=S.best[lid(tr.id,i)]||0);return{tr,p:Math.round(s/(tr.levels.length*3)*100),un:trackUnlocked(tr)}});
  const live=rows.filter(r=>r.un),avg=live.length?Math.round(live.reduce((a,r)=>a+r.p,0)/live.length):0;
  const weak=live.filter(r=>r.p<100).sort((a,b)=>a.p-b.p)[0];
  el.innerHTML=`<div class="mast"><div class="mast-top"><div><div class="label">Your skills</div><b>${avg}% mastery</b><span>Stars earned out of 3 on every level you can play.</span></div>${weak?`<button class="ghost outline" id="mastGo" type="button">Train ${esc(weak.tr.name)} →</button>`:""}</div>
   <div class="mast-bars">${rows.map(r=>`<div class="mb ${r.un?"":"lk"} ${weak&&r===weak?"weak":""}"><span>${esc(r.tr.name)}</span><div class="mt"><i style="--w:${r.p}%"></i></div><b>${r.un?r.p+"%":"Locked"}</b></div>`).join("")}</div></div>`;
  if($("#mastGo"))$("#mastGo").onclick=()=>{const tr=weak.tr;let i=tr.levels.findIndex((_,k)=>!cleared(tr.id,k)&&levelOpen(tr,k));if(i<0)i=tr.levels.findIndex((_,k)=>(S.best[lid(tr.id,k)]||0)<3);showBrief(tr,Math.max(0,i))}}

{const _r=render;render=function(){_r();try{renderMastery();renderQuests()}catch(e){console.warn(e)}}}
freezeCheck();todayQuests();setTimeout(()=>{try{renderMastery();renderQuests()}catch(e){}},0);

/* ================= FEEDBACK + RETEST v51 ================= */
const QIDX=(()=>{const m=new Map();for(const tr of TRACKS)tr.levels.forEach((L,i)=>L.q.forEach(q=>{if(!m.has(q[0]))m.set(q[0],{tr,i,q})}));return m})();
const qKey=k=>qHash(k).toString(36);
{const _la=logAnswer;logAnswer=function(raw,ok){_la(raw,ok);if(!raw||!raw[0])return;S.qstat=S.qstat||{};const h=qKey(raw[0]);const s=S.qstat[h]||(S.qstat[h]={r:0,w:0});ok?s.r++:s.w++;s.d=today()}}
const advanceReview=(k,ok)=>{const r=(S.review||{})[k];if(!r)return;if(ok){r.box++;if(r.box>=BOX_DAYS.length)delete S.review[k];else r.due=addDaysKey(BOX_DAYS[r.box])}else{r.box=0;r.due=addDaysKey(1)}};

/* weak-spot pool: what you miss most, what's due, and levels short of 3 stars */
function weakPool(tid,n=8){const allow=tid?[tid]:((typeof prof==="function"&&prof().learnTracks)||null);const out=[];
  for(const [k,{tr,i,q}] of QIDX){if(allow&&!allow.includes(tr.id))continue;if(!(cleared(tr.id,i)||levelOpen(tr,i)))continue;
    const s=(S.qstat||{})[qKey(k)]||{r:0,w:0},rv=(S.review||{})[k],stars=S.best[lid(tr.id,i)]||0;
    const sc=s.w*2-s.r*.8+(rv?3+(rv.due<=today()?2:0):0)+(3-stars)*.6+(s.r+s.w?0:.3)+Math.random()*.9;out.push([sc,q,!!(s.w||rv)])}
  out.sort((a,b)=>b[0]-a[0]);return out.slice(0,n)}
function weakCount(tid){return weakPool(tid,99).filter(x=>x[2]).length}
function runWeak(tid){const picked=weakPool(tid,8);if(picked.length<3){toast("Clear a level first so there's something to drill");return}
  const qs=picked.map(x=>x[1]),name=tid?T(tid).name:"Weak spots";
  quiz({title:tid?`${name} · weak spots`:"Weak-spot drill",qs,onAnswer:(i,ok)=>{advanceReview(qs[i][0],ok);save()},
    finish:c=>{questEvt("weak");setTimeout(render,0);const miss=qs.length-c;
      return `<div class="label">Weak-spot drill</div><h2 style="margin:6px 0 0">${c} of ${qs.length}</h2><p>${miss===0?"Clean. These spots aren't weak anymore.":`${miss} still shaky. They're in your review queue and will come back until they stick.`}</p>
       <div class="actions"><button class="btn" id="wkAgain">New drill</button><button class="ghost" id="wkDone">Done</button></div>`}});}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("#wkAgain");if(a){runWeak();return}const d=e.target.closest&&e.target.closest("#wkDone");if(d)closePanel()});

/* quiz: retry misses at the end, explain my mistake */
const EXPLAIN_FREE=3;const explainsToday=()=>((S.explains||{})[today()]||0);const _expCache=new Map();
{const _q2=quiz;quiz=function(opts){const missed=[];const oa=opts.onAnswer;const of=opts.finish;
  const o2={...opts,onAnswer:(n,ok)=>{if(oa)oa(n,ok);if(!ok)missed.push(opts.qs[n]);
      if(!ok&&!opts.isRetest)setTimeout(()=>addExplain(opts.qs[n]),0)},
    finish:c=>{let html=of(c);if(missed.length&&!opts.isRetest&&GS().retest!==false){const m=missed.slice();
        html+=`<div class="retest"><div><b>Retry ${m.length===1?"the one":"the "+m.length} you missed</b><span>Answering again right away is the fastest way to make it stick.</span></div><button class="btn sm" id="retestBtn" type="button">Retry now</button></div>`;
        setTimeout(()=>{const b=$("#retestBtn");if(b)b.onclick=()=>quiz({title:(opts.title||"Drill")+" · retry",qs:m,isRetest:true,noLog:true,onAnswer:(i,ok)=>{if(ok){S.qstat=S.qstat||{};const s=S.qstat[qKey(m[i][0])];if(s)s.r++;save()}},
          finish:k=>`<div class="label">Retry</div><h2 style="margin:6px 0 0">${k} of ${m.length}</h2><p>${k===m.length?"Fixed. They'll still come back in review once to make sure it sticks.":"Still tricky. These stay in your review queue."}</p>`})},0)}
      return html}};
  return _q2(o2)}}
function addExplain(raw){const fb=$("#fb");if(!fb||fb.querySelector(".xpl"))return;const why=fb.querySelector(".why");if(!why)return;
  const pick=panel.querySelector(".opt.wrong span:last-child"),right=panel.querySelector(".opt.right span:last-child");if(!pick||!right)return;
  why.insertAdjacentHTML("afterend",`<div class="xpl"><button class="ghost xpl-b" type="button">Why was my answer wrong?</button></div>`);
  fb.querySelector(".xpl-b").onclick=async()=>{const box=fb.querySelector(".xpl");const key=raw[0]+"|"+pick.textContent;
    if(_expCache.has(key)){box.innerHTML=_expCache.get(key);return}
    if(!isPro()&&explainsToday()>=EXPLAIN_FREE){box.innerHTML=`<p class="note">You've used today's ${EXPLAIN_FREE} free mistake explanations. They reset tomorrow, or go unlimited with Pro.</p>`;return}
    const r=window.MA_SF?MA_SF.explain(raw,pick.textContent,right.textContent):{mistake:"",trick:""};S.explains=S.explains||{};S.explains[today()]=explainsToday()+1;save();
    const h=`<div class="xpl-out"><div><span class="label">Your mistake</span><p>${esc(r.mistake||"")}</p></div>${r.trick?`<div><span class="label">Remember it</span><p>${esc(r.trick)}</p></div>`:""}</div>`;_expCache.set(key,h);box.innerHTML=h}}

/* surfaces */
function renderWeakCard(){const el=$("#weakCard");if(!el)return;const n=weakCount(),due=dueReviews().length;
  el.innerHTML=`<div class="weak"><div><div class="label">Weak-spot drill</div><b>${n?`8 questions built around ${n} you've missed`:"8 questions picked for you"}</b><span>Mixes questions you've missed, review items that are due${due?` (${due} now)`:""} and levels short of 3 stars. Comes back until they stick.</span></div><button class="btn" id="weakGo" type="button">Start drill</button></div>`;
  $("#weakGo").onclick=()=>runWeak()}
QUEST_POOL.splice(6,0,{id:"weak",t:"Finish a weak-spot drill",n:1,ev:"weak",tier:1});
