const curGroup={};
const paneEl=id=>document.querySelector(`[data-pane="${id}"]`);
const viewEl=v=>document.querySelector(`.view[data-view="${v}"]`);
function groupOf(id){for(const v in GROUPS)for(const g of GROUPS[v])if(g[0]===id||g[2].includes(id))return [v,g];return null}
function paneAllowed(v,pid){if(v!=="practice")return true;const s=prof().subs;return !s||s.includes(pid)}
function initGroups(){
  const ov=paneEl("overview");if(ov&&!paneEl("me")){const me=document.createElement("div");me.className="pane";me.dataset.pane="me";me.hidden=true;["cmpMe","rivalBox"].forEach(id=>{const e=document.getElementById(id);if(e)me.appendChild(e)});ov.parentNode.insertBefore(me,ov)}
  for(const v in GROUPS){const view=viewEl(v),nav=view&&view.querySelector(".subnav");if(!nav)continue;
    nav.querySelectorAll("[data-sub]").forEach(b=>b.remove());
    GROUPS[v].forEach(([gid,label,,hid])=>{const b=document.createElement("button");b.type="button";b.dataset.grp=gid;b.textContent=label;b.setAttribute("aria-pressed","false");if(hid){b.hidden=true;b.dataset.hid="1"}nav.insertBefore(b,nav.querySelector(".fx-ind"));b.onclick=()=>openGroup(v,gid)});
    let anchor=nav;GROUPS[v].forEach(([,,panes])=>panes.forEach(pid=>{const p=paneEl(pid);if(!p)return;if(PANE_LABEL[pid]){const h=document.createElement("h2");h.className="grp-h";h.dataset.for=pid;h.textContent=PANE_LABEL[pid];h.hidden=true;anchor.after(h);anchor=h}anchor.after(p);anchor=p}));
    curGroup[v]=GROUPS[v][0][0]}
  applyGroups()}
function applyGroups(){for(const v in GROUPS){const view=viewEl(v);if(!view)continue;const nav=view.querySelector(".subnav");
    const vis=GROUPS[v].filter(([,,panes])=>panes.some(p=>paneEl(p)&&paneAllowed(v,p)));
    nav.querySelectorAll("[data-grp]").forEach(b=>{if(!b.dataset.hid)b.hidden=!vis.some(g=>g[0]===b.dataset.grp)});
    if(!vis.some(g=>g[0]===curGroup[v]))curGroup[v]=vis[0]&&vis[0][0];
    showGroupPanes(v,curGroup[v],true)}
  renderDrawerSubs()}
function showGroupPanes(v,gid,quiet){const view=viewEl(v),g=GROUPS[v].find(x=>x[0]===gid);if(!view||!g)return;curGroup[v]=gid;
  let firstOn=true;
  GROUPS[v].forEach(([,,panes])=>panes.forEach(pid=>{const p=paneEl(pid);if(!p)return;const on=g[2].includes(pid)&&paneAllowed(v,pid);const was=!p.hidden;p.hidden=!on;
    const h=view.querySelector(`.grp-h[data-for="${pid}"]`);if(h)h.hidden=!(on&&!firstOn);if(on)firstOn=false;
    if(on&&!was&&!quiet&&!fxCalm()){p.classList.remove("enter");void p.offsetWidth;p.classList.add("enter")}}));
  view.querySelectorAll(".subnav [data-grp]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.grp===gid)));
  if(g[2].some(p=>p==="dcf"||p==="lbo")&&!quiet)setTimeout(()=>{try{drawTools()}catch(e){}},0)}
function openGroup(v,gid,scrollTo){showGroupPanes(v,gid);renderDrawerSubs();
  if(scrollTo){const t=document.querySelector(`.grp-h[data-for="${scrollTo}"]`);if(t&&!t.hidden)setTimeout(()=>t.scrollIntoView({block:"start",behavior:fxCalm()?"auto":"smooth"}),360)}}
showSub=function(view,sub){const r=groupOf(sub);if(!r)return;const [v,g]=r;const ve=viewEl(v);if(ve&&ve.hidden)showTab(v);openGroup(v,g[0],g[0]===sub?null:sub)};

/* drawer */
function buildDrawer(){if($("#drawer"))return;
  const icon=d=>`<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${d}"/></svg>`;
  const html=`<div class="dr-scrim" id="drScrim" hidden></div>
  <aside class="drawer" id="drawer" aria-label="Main menu" aria-hidden="true">
    <div class="dr-top"><span class="dr-brand">M<span>&amp;</span>A</span><button class="dr-x" id="drX" type="button" aria-label="Close menu">×</button></div>
    <div class="dr-me" id="drMe"></div>
    <nav class="dr-nav">${Object.keys(DR_NAMES).map(t=>`<div class="dr-sec" data-sec="${t}"><button class="tab dr-item" type="button" data-tab="${t}" aria-selected="false">${icon(DR_META[t][1])}<span><b>${DR_NAMES[t]}</b><small>${DR_META[t][0]}</small></span></button><div class="dr-subs" data-subs="${t}"></div></div>`).join("")}</nav>
    <div class="dr-foot"><button type="button" data-dr="you">Your profile</button><button type="button" data-dr="news">News</button><button type="button" data-dr="settings">Settings</button><button type="button" data-dr="pro">M&amp;A Pro</button></div>
  </aside>`;
  document.body.insertAdjacentHTML("beforeend",html);
  $("#drawer").querySelectorAll(".dr-item").forEach(b=>b.onclick=()=>{closeDrawer();showTab(b.dataset.tab)});
  $("#drawer").querySelectorAll("[data-dr]").forEach(b=>b.onclick=()=>{const k=b.dataset.dr;closeDrawer();if(k==="you")showSub("compete","me");else if(k==="news")toggleWire(true);else showTab(k)});
  $("#drScrim").onclick=closeDrawer;$("#drX").onclick=closeDrawer;
  const mb=$("#menuBtn");if(mb)mb.onclick=()=>$("#drawer").classList.contains("open")?closeDrawer():openDrawer();
  document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#drawer").classList.contains("open")){e.stopPropagation();closeDrawer()}},true);
  let sx=null,sy=0;document.addEventListener("touchstart",e=>{const t=e.touches[0];sx=(t.clientX<18&&ov.hidden)?t.clientX:null;sy=t.clientY},{passive:true});
  document.addEventListener("touchmove",e=>{if(sx===null)return;const t=e.touches[0];if(t.clientX-sx>50&&Math.abs(t.clientY-sy)<40){sx=null;openDrawer()}},{passive:true});
  const dr=$("#drawer");let dx=null;dr.addEventListener("touchstart",e=>{dx=e.touches[0].clientX},{passive:true});dr.addEventListener("touchmove",e=>{if(dx!==null&&dx-e.touches[0].clientX>60){dx=null;closeDrawer()}},{passive:true});
  renderDrawerSubs()}
function renderDrawerSubs(){const dr=$("#drawer");if(!dr)return;const curV=(document.querySelector(".view:not([hidden])")||{}).dataset;const cv=curV&&curV.view;
  dr.querySelectorAll("[data-subs]").forEach(box=>{const v=box.dataset.subs;const gs=(GROUPS[v]||[]).filter(([gid,,panes,hid])=>!hid&&panes.some(p=>paneEl(p)&&paneAllowed(v,p)));
    box.innerHTML=gs.map(([gid,label])=>`<button type="button" class="dr-sub" data-v="${v}" data-g="${gid}" ${cv===v&&curGroup[v]===gid?'aria-current="true"':""}>${esc(label)}</button>`).join("");
    box.querySelectorAll(".dr-sub").forEach(b=>b.onclick=()=>{closeDrawer();showSub(b.dataset.v,b.dataset.g)})});
  const hs=(S.settings.hideTabs)||{};dr.querySelectorAll(".dr-sec").forEach(s=>s.hidden=!!hs[s.dataset.sec])}
let drLast=null;
function openDrawer(){const dr=$("#drawer");if(!dr)return;renderDrawerSubs();
  const me=$("#drMe");if(me){const x=totalXP(),r=rankOf(x),nx=RANKS[r+1];me.innerHTML=`<div><b>${esc(RANKS[r][0])}</b><span>${x} XP${nx?` · ${nx[1]-x} to ${esc(nx[0])}`:""}</span></div><div class="dr-bar"><i style="width:${nx?Math.round((x-RANKS[r][1])/(nx[1]-RANKS[r][1])*100):100}%"></i></div>`}
  drLast=document.activeElement;$("#drScrim").hidden=false;requestAnimationFrame(()=>{dr.classList.add("open");$("#drScrim").classList.add("on")});dr.setAttribute("aria-hidden","false");
  const mb=$("#menuBtn");if(mb)mb.setAttribute("aria-expanded","true");document.body.classList.add("dr-lock");
  setTimeout(()=>{const a=dr.querySelector('.dr-item[aria-selected="true"]')||dr.querySelector(".dr-item");a&&a.focus({preventScroll:true})},60)}
function closeDrawer(){const dr=$("#drawer");if(!dr||!dr.classList.contains("open"))return;dr.classList.remove("open");$("#drScrim").classList.remove("on");dr.setAttribute("aria-hidden","true");
  const mb=$("#menuBtn");if(mb)mb.setAttribute("aria-expanded","false");document.body.classList.remove("dr-lock");
  setTimeout(()=>{if(!dr.classList.contains("open"))$("#drScrim").hidden=true},320);if(drLast&&drLast.focus&&drLast!==document.body)try{drLast.focus({preventScroll:true})}catch(e){}}
{const _st=showTab;showTab=function(t,f){_st(t,f);setTimeout(renderDrawerSubs,0)}}
$("#avBtn").onclick=()=>showSub("compete","me");
initGroups();

/* ================= FOUNDER BADGE ================= */
let FOUNDER_ID=null,amFounder=false;
const founderBadge=()=>`<span class="founder-b" title="Founder of M&amp;A">M<i>&amp;</i>A founder</span>`;
function isFounderId(id){return !!id&&((!!FOUNDER_ID&&id===FOUNDER_ID)||((id===myId||id==="me")&&amFounder))}
async function initFounder(){try{if(USER&&(USER.isFounder?USER.isFounder():USER.isOwner&&await USER.isOwner())){amFounder=true;if(DB&&myId&&FOUNDER_ID!==myId)DB.doc("views/_founder").set({founder:myId}).catch(()=>{});decorateFounder()}}catch(e){}}
function decorateFounder(){
  if(amFounder){const n=document.querySelector("#cmpMe .me-name");if(n&&!n.querySelector(".founder-b")){const sm=n.querySelector("small");sm?sm.insertAdjacentHTML("beforebegin"," "+founderBadge()):n.insertAdjacentHTML("beforeend"," "+founderBadge())}}
  document.querySelectorAll(".brow[data-p]").forEach(b=>{if(isFounderId(b.dataset.p)&&!b.querySelector(".founder-b")){const nm=b.querySelector(".nm");if(nm)nm.insertAdjacentHTML("afterend"," "+founderBadge())}});
  const li=panel&&panel.querySelector(".li-name");if(li&&panel.dataset.pid&&isFounderId(panel.dataset.pid)&&!li.querySelector(".founder-b"))li.insertAdjacentHTML("beforeend"," "+founderBadge())}
{const _iv=initViews;initViews=function(){_iv();initFounder()}}
{const _rc=renderCompete;renderCompete=function(){_rc();try{decorateFounder()}catch(e){}}}
{const _sp=showPlayer;showPlayer=function(p){panel.dataset.pid=p&&p.id||"";_sp(p);try{decorateFounder()}catch(e){}}}

