const FINAL_PASS=70;
function finalState(tid){return (S.finals||{})[tid]||null}
function finalUnlocked(tid){const tr=T(tid);return !!tr&&clearedCount(tid)===tr.levels.length}
{const _tx2=totalXP;totalXP=function(){return _tx2()+Object.values(S.finals||{}).filter(f=>f.offer).length*60}}

function startFinal(tid){const F=FINALS[tid];if(!F)return;
  if(!finalUnlocked(tid)){toast(`Clear every ${T(tid).name} level to unlock the final round`);return}
  const ai=!!SAMPLE&&(isPro()||gradesToday()<FREE_GRADES);
  const res=[];let ri=0,clock=null;
  const head=(r)=>`<div class="fr-head"><span class="label">${esc(F.name)} · Round ${ri+1} of ${F.rounds.length}</span><div class="fr-steps">${F.rounds.map((_,k)=>`<i class="${k<ri?"done":k===ri?"cur":""}"></i>`).join("")}</div></div><div class="fr-who"><b>${esc(r.who)}</b><span>${esc(r.topic)}</span></div>${F.case?`<div class="fr-case">${esc(F.case)}</div>`:""}`;
  const intro=()=>{openPanel(`<div class="fr"><div class="label">Final round · ${esc(T(tid).name)}</div><h2>${esc(F.name)}</h2><p class="sub">${esc(F.fmt)}. This is how ${esc(F.who)} decides who gets the offer.</p>
     ${F.case?`<div class="fr-case">${esc(F.case)}</div>`:""}
     <ol class="fr-plan">${F.rounds.map(r=>`<li><b>${esc(r.who)}</b><span>${esc(r.topic)}</span></li>`).join("")}</ol>
     <p class="note">Score ${FINAL_PASS}+ overall, with no round under 40, to get the offer. ${ai?"AI grades your written answers at the end.":(SAMPLE?`You've used today's free grades, so you'll check your own written answers against the key points.`:aiLock("AI grading")+" For now you'll check them against the key points.")}</p>
     <div class="actions"><button class="btn" id="frGo" type="button">Start the final round</button></div></div>`);
    $("#frGo").onclick=()=>{ri=0;draw()}};
  const next=()=>{clearInterval(clock);ri++;if(ri<F.rounds.length)draw();else finish()};
  const draw=()=>{const r=F.rounds[ri];clearInterval(clock);
    if(r.type==="mcq"){let k=0,ok=0;const one=()=>{const q=shuffleOpts(r.qs[k]);
        panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="fr">${head(r)}<div class="label" style="margin-top:14px">Question ${k+1} of ${r.qs.length}</div><div class="q">${q.q}</div><div class="opts">${q.o.map((o,j)=>`<button class="opt" data-k="${j}"><span class="k">${"ABCD"[j]}</span><span>${o}</span></button>`).join("")}</div><div id="fb"></div></div>`;bindClose();
        panel.querySelectorAll(".opt").forEach(b=>b.onclick=()=>{const good=+b.dataset.k===q.a;if(good)ok++;sfx(good?"ok":"no");buzz(good?8:[14,40,14]);panel.querySelectorAll(".opt").forEach(x=>{x.disabled=true;if(+x.dataset.k===q.a)x.classList.add("right")});if(!good)b.classList.add("wrong");
          $("#fb").innerHTML=`<div class="why"><b>${good?"Correct.":"Not quite."}</b> ${q.w}</div><div class="actions"><button class="btn" id="nx">${k<r.qs.length-1?"Next question":"Finish round"}</button></div>`;$("#nx").focus();
          $("#nx").onclick=()=>{k++;if(k<r.qs.length)one();else{res[ri]={score:Math.round(ok/r.qs.length*100),detail:`${ok} of ${r.qs.length} right`};next()}}});
        panel.querySelector(".opt").focus()};one()}
    else if(r.type==="num"){const t0=Date.now();
      panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="fr">${head(r)}<div class="fr-setup">${esc(r.setup)}</div><div class="fr-clock"><span id="frClk">0:00</span> / ${Math.floor(r.clock/60)}:${String(r.clock%60).padStart(2,"0")} target</div>
        <div class="fr-cells">${r.cells.map(([l],j)=>`<label class="fr-cell"><span>${esc(l)}</span><input inputmode="decimal" data-j="${j}" autocomplete="off" aria-label="${esc(l)}"></label>`).join("")}</div><div id="frOut"></div><div class="actions"><button class="btn" id="frCheck" type="button">Submit answers</button></div></div>`;bindClose();
      clock=setInterval(()=>{const s=Math.floor((Date.now()-t0)/1000),e=$("#frClk");if(!e){clearInterval(clock);return}e.textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;e.parentElement.classList.toggle("over",s>r.clock)},1000);
      panel.querySelector(".fr-cell input").focus();
      panel.querySelectorAll(".fr-cell input").forEach((inp,j,all)=>inp.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();if(all[j+1])all[j+1].focus();else $("#frCheck").click()}}));
      $("#frCheck").onclick=()=>{clearInterval(clock);let ok=0;const secs=Math.floor((Date.now()-t0)/1000);
        panel.querySelectorAll(".fr-cell input").forEach(inp=>{const j=+inp.dataset.j,[l,ans,how,tol]=r.cells[j];const v=parseFloat(String(inp.value).replace(/[$,%x\s]/gi,""));const good=isFinite(v)&&Math.abs(v-ans)<=(tol||0)+1e-9;if(good)ok++;inp.disabled=true;
          const cell=inp.closest(".fr-cell");cell.classList.add(good?"ok":"no");cell.insertAdjacentHTML("beforeend",`<small>${good?"✓":`Answer: ${ans.toLocaleString()}`} · ${esc(how)}</small>`)});
        sfx(ok===r.cells.length?"clear":ok?"ok":"no");
        res[ri]={score:Math.round(ok/r.cells.length*100),detail:`${ok} of ${r.cells.length} cells right in ${Math.floor(secs/60)}:${String(secs%60).padStart(2,"0")}`};
        $("#frCheck").outerHTML=`<button class="btn" id="frNext" type="button">${ri<F.rounds.length-1?"Next round":"See the decision"}</button>`;$("#frNext").onclick=next;$("#frNext").focus()}}
    else{panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="fr">${head(r)}<div class="q">${esc(r.q)}</div><textarea id="frAns" rows="7" placeholder="Answer the way you'd say it out loud…"></textarea><div class="actions"><button class="btn" id="frSub" type="button">${ai?"Submit answer":"Check my answer"}</button><span class="note" id="frCount"></span></div><div id="frSelf"></div></div>`;bindClose();
      const ta=$("#frAns");ta.focus();ta.oninput=()=>{const n=ta.value.trim().split(/\s+/).filter(Boolean).length;$("#frCount").textContent=n?`${n} words`:""};
      $("#frSub").onclick=()=>{const a=ta.value.trim();if(a.split(/\s+/).length<8){toast("Give a fuller answer, at least a couple of sentences");return}
        if(ai){res[ri]={open:true,answer:a};next();return}
        ta.disabled=true;$("#frSub").remove();
        $("#frSelf").innerHTML=`<div class="label" style="margin-top:14px">Tick what your answer covered</div><div class="fr-keys">${r.k.map((k,j)=>`<label><input type="checkbox" data-j="${j}"> <span>${esc(k)}</span></label>`).join("")}</div><div class="actions"><button class="btn" id="frSelfGo" type="button">${ri<F.rounds.length-1?"Next round":"See the decision"}</button></div>`;
        $("#frSelfGo").onclick=()=>{const n=panel.querySelectorAll(".fr-keys input:checked").length;const sc=Math.round(Math.min(10,2+n/r.k.length*8))*10;res[ri]={score:sc,detail:`You covered ${n} of ${r.k.length} key points`,answer:a,missed:r.k.filter((_,j)=>!panel.querySelector(`.fr-keys input[data-j="${j}"]`).checked)};next()}}}};
  const finish=async()=>{const opens=F.rounds.map((r,i)=>[r,i]).filter(([r,i])=>res[i]&&res[i].open);
    if(opens.length){panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="fr fr-wait"><div class="label">${esc(F.name)}</div><h2>The panel is deciding…</h2><p class="sub">Claude is grading your ${opens.length} written answer${opens.length>1?"s":""}.</p><div class="fr-dots"><i></i><i></i><i></i></div></div>`;bindClose();
      const prompt=`${F.persona} Grade the candidate's written answers honestly, like a demanding but fair final-round panel. ${F.case?`The case: ${F.case}\n`:""}Calibrate each answer from 1 to 10: 5 = weak, 7 = would pass, 9+ = exceptional.

${opens.map(([r,i],n)=>`Answer ${n+1} (${r.who}, ${r.topic})
Question: ${r.q}
A strong answer covers: ${r.k.join("; ")}
Candidate's answer: """${res[i].answer.slice(0,2500)}"""`).join("\n\n")}

Return JSON: {"answers":[{"score":1-10,"verdict":"one short sentence","missed":["key point they missed", "..."],"tip":"one specific sentence on how to improve"}], "panel_note":"one or two sentences the panel would say about the candidate overall"}. The answers array must have ${opens.length} items in order.`;
      try{const r=await SAMPLE.json(prompt,{modelTier:"default"});if(!isPro())bumpGrades();
        opens.forEach(([rd,i],n)=>{const a=(r.answers||[])[n]||{};const sc=Math.max(1,Math.min(10,Math.round(+a.score||0)));res[i]={score:sc*10,detail:a.verdict||"",missed:a.missed||[],tip:a.tip||"",answer:res[i].answer}});res.note=r.panel_note||""}
      catch(e){opens.forEach(([rd,i])=>{res[i]={score:60,detail:"Couldn't grade this one right now, so it's scored as a neutral 6.",answer:res[i].answer,missed:[]}})}}
    const scores=F.rounds.map((_,i)=>(res[i]||{}).score||0),overall=Math.round(scores.reduce((a,b)=>a+b,0)/scores.length),floor=Math.min(...scores),offer=overall>=FINAL_PASS&&floor>=40;
    S.finals=S.finals||{};const prev=S.finals[tid]||{};const first=offer&&!prev.offer;S.finals[tid]={best:Math.max(prev.best||0,overall),last:overall,offer:!!(prev.offer||offer),date:today(),tries:(prev.tries||0)+1};save();
    if(offer){questEvt("final");logEvent&&logEvent(`Got the offer in the ${T(tid).name} final round`)}
    const weakest=F.rounds.map((r,i)=>[r,i]).sort((a,b)=>scores[a[1]]-scores[b[1]])[0];
    panel.innerHTML=`<button class="close" aria-label="Close">×</button><div class="fr fr-res ${offer?"offer":""}">
      <div class="label">${esc(F.name)} · decision</div><h2>${offer?"You got the offer.":"No offer this time."}</h2>
      <div class="fr-score"><b id="frOv">${overall}</b><span>/ 100 overall · ${FINAL_PASS} needed${offer&&first?" · +60 XP":""}</span></div>
      ${res.note?`<p class="fr-note">"${esc(res.note)}"</p>`:""}
      <div class="fr-bars">${F.rounds.map((r,i)=>{const x=res[i]||{};return `<div class="fr-bar ${scores[i]<40?"low":""}"><div class="fr-bt"><b>${esc(r.who)}</b><span>${esc(r.topic)}</span><em>${scores[i]}</em></div><div class="fr-bm"><i style="--w:${scores[i]}%"></i></div>${x.detail?`<p>${esc(x.detail)}</p>`:""}${x.tip?`<p class="fr-tip">${esc(x.tip)}</p>`:""}${x.missed&&x.missed.length?`<p class="fr-miss">Missed: ${x.missed.map(esc).join("; ")}</p>`:""}</div>`}).join("")}</div>
      ${!offer?`<p class="note">Your weakest round was <b>${esc(weakest[0].who)}: ${esc(weakest[0].topic)}</b>. ${floor<40&&overall>=FINAL_PASS?"Every round has to clear 40, even with a strong total.":"Work on that, then come back."}</p>`:""}
      <div class="actions"><button class="btn" id="frAgain" type="button">${offer?"Run it again":"Try again"}</button><button class="ghost" id="frDone" type="button">Done</button></div></div>`;bindClose();
    $("#frAgain").onclick=()=>startFinal(tid);$("#frDone").onclick=closePanel;
    if(offer){sfx("rank");buzz([20,60,30]);setTimeout(()=>fxBurstFrom($(".fr-score"),{n:110,power:9}),250)}
    const ov=$("#frOv");if(ov&&!fxCalm()){ov.textContent="0";setTimeout(()=>fxNum(ov,overall,""),200)}};
  intro()}
