function renderFinalCards(){document.querySelectorAll("#tracks details.track[data-tr]").forEach(d=>{const tid=d.dataset.tr,F=FINALS[tid];if(!F)return;const body=d.querySelector(".track-body");if(!body||body.querySelector(".final-card"))return;
  const un=finalUnlocked(tid),st=finalState(tid),left=T(tid).levels.length-clearedCount(tid);
  body.insertAdjacentHTML("beforeend",`<div class="final-card ${un?"":"lk"} ${st&&st.offer?"won":""}"><div class="fc-ic" aria-hidden="true">${st&&st.offer?"✓":"★"}</div><div class="fc-t"><span class="label">Final round</span><b>${esc(F.name)}</b><span>${esc(F.fmt)}${st?` · Best ${st.best}/100${st.offer?" · Offer received":""}`:""}</span></div><button class="${un?"btn sm":"ghost outline"}" type="button" data-final="${tid}" ${un?"":"aria-disabled=\"true\""}>${un?(st?"Run it again":"Start"):`${left} level${left===1?"":"s"} to unlock`}</button></div>`);
  body.querySelector("[data-final]").onclick=e=>{e.stopPropagation();startFinal(tid)}})}
{const _r3=render;render=function(){_r3();try{renderFinalCards()}catch(e){console.warn(e)}}}
