const PE_TARGETS=["","Investment banking","Private equity","Hedge funds","Equity research","Sales & trading","Restructuring","Consulting","Not sure yet"];
const PE_MON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const peToMonth=s=>{const m=String(s||"").match(/([A-Za-z]{3})[a-z]*\.?\s+(\d{4})/);if(!m)return"";const i=PE_MON.findIndex(x=>x.toLowerCase()===m[1].toLowerCase());return i<0?"":`${m[2]}-${String(i+1).padStart(2,"0")}`};
const peFromMonth=v=>{const m=String(v||"").match(/^(\d{4})-(\d{2})$/);return m?`${PE_MON[+m[2]-1]} ${m[1]}`:""};
const peHsOk=u=>!u||/^https?:\/\/([a-z0-9-]+\.)*joinhandshake\.com\/\S+$/i.test(u.trim());
const peLinkOk=u=>!u||/^https?:\/\/(www\.)?linkedin\.com\/in\/[A-Za-z0-9\-_%]+\/?$/i.test(u.trim());
const PE_AI_FREE=2;const peAiLeft=()=>isPro()?Infinity:Math.max(0,PE_AI_FREE-((S.aiEdits||{})[today()]||0));
function peStrength(p){const ex=(p.exp||[]).filter(e=>e.t||e.o);const items=[
  ["Headline",15,!!(p.headline||"").trim(),"head"],["School",10,!!(p.school||"").trim(),"school"],["Class year",5,/^\d{4}$/.test(p.grad||""),"grad"],["Major",5,!!(p.major||"").trim(),"major"],
  ["Location",5,!!(p.location||"").trim(),"loc"],["Target career",10,!!p.target,"target"],["About (80+ characters)",10,(p.about||"").trim().length>=80,"about"],["Profile photo",10,!!p.photo,"photo"],
  ["An experience with a result",10,ex.some(e=>(e.d||"").trim().length>=30),"exp"],["5 or more skills",10,(p.skills||[]).length>=5,"skills"],["LinkedIn or Handshake link",10,(!!(p.linkedin||"").trim()&&peLinkOk(p.linkedin))||(!!(p.handshake||"").trim()&&peHsOk(p.handshake)),"link"]];
  return {pct:items.reduce((a,i)=>a+(i[2]?i[1]:0),0),missing:items.filter(i=>!i[2])}}

