{const _sp2=showPlayer;showPlayer=function(p){_sp2(p);try{const isMe=!myId||p.id===myId||p.id==="me";const u=isMe?(S.profile||{}).linkedin:p.linkedin;const id=panel.querySelector(".li-id");const hs=isMe?(S.profile||{}).handshake:p.handshake;if(id&&!id.querySelector(".li-links")&&((u&&peLinkOk(u))||(hs&&peHsOk(hs))))(id.querySelector(".li-conn")||id).insertAdjacentHTML("afterend",`<div class="li-links">${u&&peLinkOk(u)?`<a class="li-link" href="${esc(u)}" target="_blank" rel="noopener">in · LinkedIn ↗</a>`:""}${hs&&peHsOk(hs)?`<a class="li-link hs" href="${esc(hs)}" target="_blank" rel="noopener">Handshake ↗</a>`:""}</div>`)}catch(e){}}}


/* ================= PROFILE PHOTOS ================= */
var AVATARS={};
const okPhoto=u=>typeof u==="string"&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(u)&&u.length<120000;
function photoFor(id){if(!id)return "";if((id===myId||id==="me")&&okPhoto((S.profile||{}).photo))return S.profile.photo;const a=AVATARS[id];return okPhoto(a)?a:""}
function squarePhoto(file){return new Promise((res,rej)=>{const url=URL.createObjectURL(file);const im=new Image();im.onload=()=>{try{const s=Math.min(im.naturalWidth,im.naturalHeight),N=192,c=document.createElement("canvas");c.width=c.height=N;const g=c.getContext("2d");g.imageSmoothingQuality="high";g.drawImage(im,(im.naturalWidth-s)/2,(im.naturalHeight-s)/2,s,s,0,0,N,N);let q=.86,d=c.toDataURL("image/jpeg",q);while(d.length>60000&&q>.4){q-=.1;d=c.toDataURL("image/jpeg",q)}URL.revokeObjectURL(url);res(d)}catch(e){rej(e)}};im.onerror=e=>{URL.revokeObjectURL(url);rej(e)};im.src=url})}
async function syncPhoto(){if(!DB||!myId)return;const ph=(S.profile||{}).photo;try{if(okPhoto(ph)&&!S.settings.hidden)await DB.doc("avatars/"+myId).set({img:ph,t:Date.now()});else await DB.doc("avatars/"+myId).delete()}catch(e){}}
function refreshAvatars(){try{renderCompete()}catch(e){}const av=$("#avBtn");if(av)av.innerHTML=avatar(myId||"me",myName||"You",30)}
{const _iv2=initViews;initViews=function(){_iv2();try{DB.collection("avatars").limit(500).onSnapshot(snap=>{const m={};snap.docs.forEach(d=>{const x=d.data();if(x&&okPhoto(x.img))m[d.id]=x.img});AVATARS=m;refreshAvatars()},()=>{});if(okPhoto((S.profile||{}).photo))syncPhoto()}catch(e){}}}
setTimeout(refreshAvatars,0);


