  const all=(typeof PLAYERS!=="undefined"?PLAYERS:[]).map(p=>({id:p.id,v:p.xp||0}));if(myId&&!all.some(x=>x.id===myId))all.push({id:myId,v:totalXP()});all.sort((a,b)=>b.v-a.v);
